(window.GIM_TS=window.GIM_TS||{})["Chullin.7"]={"from":168,"a":[["ומתרצים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה הוא אומר],\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 כשאמר: \u0003\"צא נחור\"\u0004 פטור מכיסוי, \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003שחיטה היא כלל, אבל\u0004 כשאומר: \u0003\"צא טרוף\"\u0004 — \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003שחיטה שאינה ראויה שמה שחיטה, וליבעי\u0004 \u0005[ויצטרך]\u0006 \u0003כסוי,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003כ\u0004דבריו של \u0003ר' חייא בר אבא,\u0004 שראה רבי את דברי ר' שמעון בכיסוי הדם, ששחיטה שאינה ראויה אינה שחיטה, ופטורה מכיסוי.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003\"צא נחור\"\u0004 אמר לו רבי לר' חייא, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 לו רבי: \u0003\"צא טרוף\"? וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003קסבר\u0004 \u0005[סבור\u0006 רבי\u0005]\u0006 כי \u0003שחיטה שאינה ראויה\u0004 — \u0003שמה שחיטה,\u0004 ומחייבת בכיסוי; \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: ראה רבי דבריו של רבי שמעון בכסוי הדם, ושנאו בלשון חכמים!\u0004","ומתרצים: \u0003לא מיבעיא קאמר\u0004 \u0005[\u0006בלשון \u0005לא נצרכה הוא אומר],\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 \u0003\"צא טרוף\"\u0004 אינו חייב בכיסוי, מפני ש\u0003שחיטה שאינה ראויה לא שמה שחיטה, אבל \"צא נחור\"\u0004 — \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אין שחיטה לעוף מן התורה, ו\u0004אם כן \u0003נחירתו זו היא שחיטתו, וליבעי\u0004 \u0005[ויצטרך]\u0006 \u0003כסוי,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שיש לעוף שחיטה מן התורה, כפי שדרש רבי מ\u0003\"כאשר צויתיך\"\u0004 (דברים יב, כא).","ושואלים על גוף המעשה: \u0003ומי נפל ליה יאניבא בכיתניה\u0004 \u0005[והאם נפל לו\u0006 לר' חייא \u0005עש בפשתנו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבין בר אבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבין בר שבא: משעלו בני הגולה\u0004 מבבל לארץ ישראל \u0003פסקו\u0004 בארץ ישראל \u0003הזיקין\u0004 (כוכבי שביט) \u0003והזועות\u0004 (רעידות אדמה) \u0003והרוחות\u0004 הסוערות, \u0003והרעמים, ולא החמיץ יינם, ולא לקה פשתנם\u0004 בעש וכדומה, \u0003ונתנו חכמים עיניהם\u0004 ותלו דבר זה \u0003בר' חייא ובניו\u0004 שעלו מבבל, וזכותם הועילה לבני ארץ ישראל. ואם כן, כיצד ייתכן שנפל עש בפשתנו של ר' חייא עצמו?","ומשיבים: \u0003כי מהניא זכותייהו\u0004 — \u0003אעלמא, אדידהו\u0004 — \u0003לא\u0004 \u0005[כאשר מועילה זכותם\u0006 — הרי זה \u0005על העולם,\u0006 אבל \u0005עליהם\u0006 — \u0005לא].\u0006 ו\u0003כ\u0004דברי \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה אמר רב: בכל יום ויום בת קול יוצאת ואומרת: \"כל העולם כולו ניזון בשביל\u0004 (בגלל, בזכות) \u0003חנינא בני,\u0004 הוא חנינא בן דוסא, שהיה ידוע בחסידותו, \u0003וחנינא בני\u0004 — \u0003די לו בקב חרובין מערב שבת לערב שבת.\u0004","\u0003חרש שוטה וקטן ששחטו\u0004 חיה או עוף \u0003ואחרים רואין אותם\u0004 שהם שוחטים כראוי, שבאופן זה שחיטתם כשרה (לעיל ב,א) — \u0003חייב\u0004 הרואה אותם שוחטים \u0003לכסות\u0004 את הדם אחריהם. שחטו \u0003בינן לבין עצמן\u0004 ששחיטתם פסולה — משנודע הדבר לאחר, הריהו \u0003פטור מלכסות.\u0004","\u0003וכן לענין\u0004 איסור \u0003אותו ואת בנו\u0004 בבהמה: חרש שוטה וקטן \u0003ששחטו\u0004 את האם, \u0003ואחרים רואין אותן\u0004 — \u0003אסור לשחוט\u0004 את הבן \u0003אחריהם\u0004 באותו יום; שחטו \u0003בינן לבין עצמן\u0004 — \u0003ר' מאיר מתיר לשחוט אחריהן, וחכמים אוסרים,\u0004 שמא שחטו כראוי. \u0003ומודים\u0004 חכמים \u0003שאם שחט\u0004 אחריהם בו ביום — \u0003שאינו סופג את הארבעים,\u0004 שמא לא שחטו כראוי.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003מאי שנא רישא דלא פליגי\u0004 \u0005[במה שונה תחילת\u0006 המשנה, לענין כיסוי הדם, \u0005שאינם חלוקים]\u0006 על כך שחרש שוטה וקטן ששחטו בינם לבין עצמם — פטור מלכסות אחריהם, ומתוך כך משמע שגם לדעתם כששחטו בינם לבין עצמם אין שחיטתם שחיטה. \u0003ומאי שנא סיפא דפליגי\u0004 \u0005[ובמה שונה הסוף,\u0006 לענין אותו ואת בנו, \u0005ש\u0006חכמים \u0005חולקים]\u0006 על ר' מאיר, וסבורים שאם חרש שוטה וקטן שחטו את האם — אסור לשחוט את הבן בו ביום, ומשמע ששחיטתם בינם לבין עצמם נחשבת שחיטה?","ומשיבים: \u0003רישא\u0004 \u0005[בתחילה],\u0006 בענין כיסוי הדם, \u0003אי אמרינן\u0004 \u0005[אם אנו אומרים]\u0006 ש\u0003חייבין לכסות\u0004 אחריהם, \u0003אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 שחיטתם \u0003שחיטה מעלייתא\u0004 \u0005[מעולה,\u0006 כשרה\u0005]\u0006 \u0003היא, ואתי למיכל\u0004 \u0005[ויבואו לאכול]\u0006 \u0003משחיטתן,\u0004 ובאמת נאסר הדבר.","ומקשים, אם כן, \u0003סיפא נמי\u0004 \u0005[בסופה גם כן],\u0006 לענין אותו ואת בנו, מדוע אסרו לשחוט אחריהם? והלא \u0003כיון דקאמרי רבנן\u0004 \u0005[שאומרים חכמים]\u0006 \u0003אסור לשחוט אחריהם\u0004 את הבן, נחשוש שמא \u0003אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003שחיטה מעלייתא\u0004 \u0005[מעולה,\u0006 כשרה\u0005]\u0006 \u0003היא, ואתי למיכל\u0004 \u0005[ויבואו לאכול]\u0006 \u0003משחיטתן!\u0004","ומשיבים: \u0003סיפא\u0004 \u0005[בסוף\u0006\u0005,\u0006 באותו ואת בנו\u0005]\u0006 גם אם נאסור לשחוט אחריהם — אין לחשוש שיבואו אנשים להכשיר את שחיטתם, מפני ש\u0003אמרי\u0004 \u0005[אומרים\u0006 האנשים\u0005]:\u0006 טעם הדבר שלא שחטו את הבן אחריהם הוא מפני ש\u0003בשרא דלא קא מיבעיא ליה\u0004 \u0005[בשר הוא שלא נצרך לו]\u0006 לבעלים. ומקשים: \u0003רישא נמי\u0004 \u0005[בתחילה גם כן],\u0006 בכיסוי הדם, אם נחייב לכסות אחריהם — אין לחשוש, שכן \u0003אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003לנקר\u0004 (לנקות) \u0003חצירו הוא צריך!\u0004","ודוחים: אם חרש שוטה וקטן \u0003שחט באשפה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי כאן לא שייך נימוק זה! וכן במקרה ששחטו והרואה אותם \u0003בא לימלך\u0004 בבית הדין האם צריך לכסות את הדם אחר שחיטתם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אם נצריך אותו לכסות אחריהם, יבוא להכשיר את שחיטתם! וכיון שבמקרים כגון אלו יבואו לטעות — אסרו לכסות אחריהם בכל מקרה, וגם כשהוא שוחט בחצירו.","ומקשים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שחכמים חוששים משום מקרים אלה, \u0003סיפא נמי\u0004 \u0005[בסוף גם כן],\u0006 באותו ואת בנו, אם \u0003בא\u0004 הרואה \u0003לימלך\u0004 אם מותר לשחוט את הבן אחריהם, ואוסרים עליו, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי יכול הוא לטעות ולהכשיר את שחיטתם, ומדוע אסרו חכמים לשחוט אחריהם?","\u0003אלא\u0004 צריך לומר כי \u0003רבנן אכולה מילתא פליגי\u0004 \u0005[חכמים על כל הענין חולקים],\u0006 והם סבורים שחרש שוטה וקטן ששחטו — צריך לכסות אחריהם, כפי שלענין אותו ואת בנו אסרו לשחוט אחריהם. \u0003ונטרי ליה לר' מאיר עד דמסיק לה למילתא, והדר פליגי עילויה\u0004 \u0005[והמתינו לו\u0006 חכמים \u0005לר' מאיר עד שיסיים את דבריו, ואחר כך חלקו עליו].\u0006","ושואלים: ומעתה, \u0003בשלמא רבנן\u0004 \u0005[נניח,\u0006 מובנת דעת \u0005חכמים]\u0006 — משום שהם הולכים \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שלמרות שאסרו לאכול משחיטתם, החמירו לחייב בכיסוי הדם אחריהם, ולענין אותו ואת בנו אסרו לשחוט אחריהם מספק שמא שחטו כראוי. \u0003אלא רבי מאיר,\u0004 שפטר מכיסוי הדם אחריהם, והתיר לשחוט את הבן אחריהם, \u0003מאי טעמא\u0004 \u0005[מה טעמו]?\u0006 מדוע לא יחמיר מספק?","\u0003אמר רבי יעקב אמר רבי יוחנן: מחייב היה רבי מאיר\u0004 מלקות \u0003על\u0004 האוכל מ\u0003שחיטתן משום נבלה.\u0004 כלומר, הוא סבור ששחיטתם אינה קרויה כלל שחיטה, עד שניתן להתרות באוכל משחיטתם התראת ודאי שהוא עומד לאכול נבילה, ולהלקותו אם עשה כן. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]?\u0006 \u0003אמר רבי אמי: הואיל ורוב מעשיהן\u0004 של חרש שוטה וקטן \u0003מקולקלים,\u0004 אינם נעשים כראוי, ויש להניח שלא שחטו כראוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע הוצרך ר' אמי לנימוק של \u0003רוב?\u0004 הרי \u0003אפילו\u0004 אם \u0003מיעוט\u0004 מעשיהם מקולקלים \u0003נמי\u0004 \u0005[גם כן]\u0006 היה ר' מאיר אומר כן! \u0003דהא\u0004 \u0005[שהרי]\u0006 שמענו את \u0003רבי מאיר\u0004 שהוא \u0003חייש למיעוטא\u0004 \u0005[חושש למיעוט],\u0006 מתחשב בו כנגד הרוב, כשיש חזקה המסייעת לו. ואם כן, גם אם רוב מעשיהם של חרש שוטה וקטן מתוקנים, יש לומר: \u0003סמוך מיעוטא\u0004 \u0005[צרף את המיעוט]\u0006 של המקלקלים בשחיטתם, \u0003לחזקה\u0004 של איסור שיש בבהמה, שהרי בהמה שלא נודע לך שנשחטה כראוי עומדת בחזקת איסור, \u0003ואתרע ליה רובא\u0004 \u0005[והורע לו הרוב]!\u0006 ומניין שכך סבור ר' מאיר?","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בענייני טהרות: \u0003תינוק שנמצא בצד העיסה ובצק בידו\u0004 — \u0003רבי מאיר מטהר\u0004 את העיסה כולה, שאינו חושש שטימא אותה התינוק. \u0003וחכמים מטמאין\u0004 את העיסה, \u0003מפני שדרכו של תינוק לטפח,\u0004 לגעת בידיו בעיסה. \u0003ואמרינן\u0004 \u0005[והיינו אומרים,\u0006 שואלים\u0005]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי מאיר?\u0004 \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003רוב תינוקות מטפחין, ומיעוט\u0004 תינוקות \u0003אין מטפחין, ועיסה זו בחזקת טהרה עומדת\u0004 —"],["\u0003סמוך מיעוטא\u0004 \u0005[את המיעוט]\u0006 של התינוקות שאינם מטפחים \u0003לחזקה\u0004 של טהרה שיש לעיסה, \u0003ואיתרע ליה רובא\u0004 \u0005[והורע לו הרוב]\u0006 של התינוקות המטפחים. ואם כן, גם כאן, בשחיטת חרש שוטה וקטן, מדוע הוצרכנו לומר שרוב מעשיהם מקולקלים כדי לחייב על שחיטתם משום נבילה? נסמוך מיעוט מעשים מקולקלים שלהם לחזקת איסור של הבהמה!","ומשיבים: \u0003אם אמרו\u0004 ב\u0003ספק טומאה לטהר\u0004 על ידי חזקת טהרה ומיעוט, \u0003יאמרו\u0004 ב\u0003ספק איסור להתיר,\u0004 לפטור מכיסוי הדם ולהתיר לשחוט אחריהם, כשיש מיעוט שאינו שוחט כראוי? ולכן, רק משום שרוב מעשיהם מקולקלים סומך ר' מאיר על חזקת איסור של הבהמה, לחייב על שחיטתם משום נבילה.","בהוראת ההלכה בענין זה, נאמר: \u0003הורה רבי כרבי מאיר,\u0004 שחרש שוטה וקטן ששחטו פרה בינם לבין עצמם — מותר לשחוט את בנה בו ביום, \u0003ו\u0004מצד אחר נאמר ש\u0003הורה רבי כחכמים\u0004 שהדבר אסור. ושואלים: \u0003הי מינייהו דאחריתא\u0004 \u0005[איזו מהן היא\u0006 ההוראה \u0005האחרונה]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מן המסופר ש\u0003רבי אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבי חייא בר אבא ורבי זירא הוו קיימי בשוקא דקיסרי אפתחא דבי מדרשא\u0004 \u0005[היו עומדים בשוק של קיסרי על פתח בית המדרש],\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רבי אמי\u0004 מבית המדרש \u0003אשכחינהו\u0004 \u0005[מצא אותם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לאו אמינא לכו\u0004 \u0005[האם לא אמרתי לכם]:\u0006 \u0003בעידן בי מדרשא\u0004 — \u0003לא תקימו אבראי\u0004 \u0005[בזמן בית המדרש לא תעמדו בחוץ],\u0006 \u0003דילמא איכא אינש דמיצטרכא ליה שמעתא, ואתי לאיטרודי\u0004 \u0005[שמא יש אדם שמצטרכת לו שמועה,\u0006 שצריך לברר דבר מה, \u0005ויבואו\u0006 הלומדים בבית המדרש \u0005להיטרד],\u0006 ולא יצליחו לברר את הענין, בעוד אתם יכולים לסייע בדבר!","\u0003רבי זירא על\u0004 \u0005[נכנס]\u0006 לבית המדרש, \u0003רבי אבא לא על\u0004 \u0005[לא נכנס].\u0006 \u0003יתבי וקא מיבעיא להו\u0004 \u0005[יושבים היו\u0006 בבית המדרש ו\u0005נשאלה להם]\u0006 השאלה: \u0003הי מינייהו אחריתא\u0004 \u0005[איזו מהן,\u0006 מן ההוראות של רבי \u0005אחרונה],\u0006 האם זו שהורה כר' מאיר, או זו שהורה כחכמים? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבי זירא: לא שבקתון לי דאישייליה לסבא\u0004 \u0005[לא הנחתם לי שאשאל את הזקן,\u0006 ר' אבא בנו של ר' חייא בר אבא\u0005],\u0006 \u0003דילמא שמיע ליה מאבוה, ואבוה מיניה דרבי יוחנן\u0004 \u0005[שמא שמע דבר זה מאביו,\u0006 ר' חייא בר אבא, \u0005ואביו שמע מר' יוחנן].\u0006 ומעירים, והוא כפי המסופר ש\u0003רבי חייא בר אבא כל תלתין יומין קא מהדר תלמודיה קמיה דר' יוחנן\u0004 \u0005[כל שלושים יום היה חוזר על תלמודו לפני ר' יוחנן].\u0006","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו? כיצד נפתרה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע],\u0006 ש\u0003שלח רבי אלעזר לגולה\u0004 (לבבל): \u0003הורה רבי כר' מאיר. והא כרבנן נמי אורי\u0004 \u0005[והרי כחכמים גם כן הורה]\u0006 רבי, ובוודאי הכיר ר' אלעזר מה שנאמר בשמו, שהיה גדול תלמידי ר' יוחנן! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]:\u0006 \u0003הא דאחריתא\u0004 \u0005[זו\u0006 שהורה כר' מאיר \u0005היא האחרונה],\u0006 ולכן רק אותה שלח ר' אלעזר? ומסכמים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003שחט מאה חיות במקום אחד\u0004 — \u0003כסוי אחד ל\u0004דם של \u0003כולן,\u0004 ואינו צריך לכסות דמה של כל אחת בנפרד. וכן שחט \u0003מאה עופות במקום אחד\u0004 — \u0003כסוי אחד לכולן.\u0004 שחט \u0003חיה ועוף במקום אחד\u0004 — \u0003כסוי אחד לכולן. רבי יהודה אומר: שחט חיה\u0004 — \u0003יכסנה, ואחר כך ישחוט את העוף.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בדין כיסוי הדם: \"חיה או עוף\" (ויקרא יז, יג), \u0003\"חיה\"\u0004 — \u0003כל משמע חיה,\u0004 כלומר, חיה היא לשון כללית, \u0003בין מרובה ובין מועטת;\u0004 וכן \u0003\"עוף\"\u0004 — \u0003כל משמע עוף, בין מרובה ובין מועט; מכאן אמרו\u0004 חכמים, כפי ששנינו במשנתנו: \u0003שחט מאה חיות במקום אחד\u0004 — \u0003כסוי אחד לכולן, מאה עופות במקום אחד\u0004 — \u0003כסוי אחד לכולן, חיה ועוף במקום אחד\u0004 — \u0003כסוי אחד לכולן.\u0004","\u0003רבי יהודה אומר: שחט חיה\u0004 — \u0003יכסנה, ואחר כך ישחוט את העוף, שנאמר: \"חיה או עוף\",\u0004 כל אחד מהם בפני עצמו.","\u0003אמרו לו: הרי הוא אומר \"כי נפש כל בשר דמו בנפשו הוא\"\u0004 (שם פסוק יד). ושואלים: \u0003מאי קא מהדרי ליה\u0004 \u0005[מה הם משיבים לו]\u0006 חכמים לר' יהודה? ומסבירים: \u0003הכי קאמרי ליה רבנן\u0004 \u0005[כך אומרים לו חכמים]:\u0006 \u0003האי \"או\"\u0004 \u0005[\"או\" זה]\u0006 שאתה דורש ממנו לחייב כיסוי לחיה וכיסוי נפרד לעוף — \u0003מיבעי ליה לחלק\u0004 \u0005[צריך אותו לחלק],\u0006 לחייב אם שחט רק חיה או רק עוף.","\u0003ו\u0004על כן השיב \u0003ר' יהודה: לחלק\u0004 — \u0003מ\u0004\"ושפך את \u0003דמו\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 כלומר, דמו של כל אחד מהם, של החיה והעוף שהוזכרו בפסוק. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים: לא ניתן ללמוד דין זה מ\"דמו\", מפני ש\u0003\"דמו\"\u0004 — \u0003טובא\u0004 \u0005[הרבה]\u0006 \u0003משמע,\u0004 כלומר, הוא שם כללי לדם, \u0003דכתיב\u0004 \u0005[\u0006כדרך \u0005שנאמר]:\u0006 \u0003\"כי נפש כל בשר דמו בנפשו הוא\",\u0004 ושם בוודאי אין הכוונה לדמו של פרט מסויים.","\u0003אמר רבי חנינא:\u0004 למרות שר' יהודה מחייב לכסות דמה של חיה תחילה ורק אחר כך לשחוט את העוף, \u0003מודה היה רבי יהודה לענין ברכה\u0004 \u0003שאינו מברך\u0004 על שחיטת החיה והעוף \u0003אלא ברכה אחת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מ\u0004המסופר על \u0003תלמידי\u0004","\u0003דרב\u0004 \u0005[תלמידיו של רב]?\u0006 ש\u0003רב ברונא ורב חננאל תלמידי דרב\u0004 \u0005[תלמידיו של רב]\u0006 \u0003הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה],\u0006 \u0003קאי עלייהו\u0004 \u0005[היה עומד עליהם\u0006 ומשמש אותם\u0005]\u0006 \u0003רב ייבא סבא\u0004 \u0005[הזקן],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הב ליבריך\u0004 \u0005[הב\u0006 לנו כוס יין \u0005ונברך]\u0006 ברכת המזון! אחר כך \u0003הדור אמרו ליה\u0004 \u0005[חזרו ואמרו לו]:\u0006 \u0003הב לישתי\u0004 \u0005[הב\u0006 לנו כוס יין \u0005ונשתה]!\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ייבא סבא\u0004 \u0005[הזקן],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: כיון\u0004 ש\u0003אמר\u0004 אדם \u0003\"הב ליבריך\"\u0004 \u0005[הב ונברך]\u0006 — \u0003איתסר ליה למשתי חמרא\u0004 \u0005[נאסר עליו לשתות יין],\u0006 שגילה דעתו שגמר את אכילתו ושתייתו, ואם רצונכם לחזור ולשתות — עליכם לחזור ולברך תחילה. ואם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין שוחט חיה ועוף, \u0003כיון דאיטפל ליה\u0004 \u0005[כיון שנצרך לו\u0006 לכיסוי לאחר ששחט את החיה\u0005]\u0006 הרי הפסיק את השחיטה שעסק בה, ואם כן \u0003איחייב ליה התחייב לו\u0004 מחדש\u0005]\u0006 \u0003לברכה\u0004 נוספת על שחיטת העוף!"],["ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במעשה בתלמידי רב — \u0003משתא וברוכי בהדי הדדי\u0004 \u0005[לשתות ולברך ביחד]\u0006 \u0003לא אפשר,\u0004 ולכן, משעה שזימנו עצמם לברך, נתנו דעתם שלא לשתות יותר. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 כששחט חיה, והוא רוצה לשחוט עוף, כשהוא מכסה את דם החיה אינו מסיח דעתו מן השחיטה, שהרי \u0003אפשר דשחיט בחדא, ומכסי בחדא\u0004 \u0005[שישחוט ב\u0006יד \u0005אחת, ויכסה ב\u0006יד \u0005אחת].\u0006","\u0003שחט\u0004 חיה או עוף \u0003ולא כסה\u0004 את הדם בעפר, \u0003וראהו אחר\u0004 — \u0003חייב\u0004 האחר \u0003לכסות. כסהו ונתגלה\u0004 — \u0003פטור מלכסות. כסהו הרוח\u0004 — \u0003חייב לכסות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"ושפך וכסה\"\u0004 (\"ושפך את דמו וכסהו בעפר\", ויקרא יז, יג), ודברים אלו שנאמרו ברצף אחד מלמדים כי \u0003מי ששפך\u0004 כלומר, שחט את החיה או העוף — מצוה ש\u0003יכסה\u0004 את דמו. \u0003שחט ולא כסה, וראהו אחר, מנין שחייב לכסות? שנאמר\u0004 באותה פרשה: \u0003\"ואומר לבני ישראל\"\u0004 (שם יד) — \u0003אזהרה לכל בני ישראל.\u0004","ומעיהם \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 על כתוב זה: \u0003\"ושפך וכסה\", במה ששפך\u0004 — \u0003בו יכסה,\u0004 כלומר בידו, או בסכין, \u0003שלא יכסנו ברגל,\u0004 כדי \u0003שלא יהיו מצות בזויות עליו.\u0004 וכן \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"ושפך וכסה\", מי ששפך\u0004 — \u0003הוא יכסנו. מעשה באחד ששחט\u0004 חיה או עוף, \u0003וקדם חבירו וכסה, וחייבו רבן גמליאל ליתן לו עשרה זהובים.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 האם עשרה זהובים אלה הם \u0003שכר מצוה\u0004 שגזל ממנו, \u0003או שכר ברכה,\u0004 ברכת המצוות? ומסבירים, \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה]\u0006 משאלה זו למעשה — \u0003לברכת המזון, אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \u0003שכר מצוה\u0004 חייבו רבי — ברכת המזון כולה מצוה \u0003אחת היא, ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 \u0003שכר ברכה\u0004 — ארבע ברכות של ברכת המזון \u0003הויין\u0004 \u0005[הריהן]\u0006 שוות \u0003ארבעים\u0004 זהובים. \u0003מאי\u0004 \u0005[מה]\u0006 התשובה?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שמסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[אותו מין,\u0006 כופר\u0005]\u0006 \u0003לרבי\u0004 בקינטור: \u0003מי שיצר הרים לא ברא רוח,\u0004 \u0003ומי שברא רוח לא יצר הרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי הנה יוצר הרים ובורא רוח\"\u0004 (עמוס ד, יג), הרי שיש יוצר ויש בורא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003שוטה, שפיל לסיפיה דקרא\u0004 \u0005[רד,\u0006 המשך \u0005לסופו של הכתוב],\u0006 שנאמר: \u0003\"ה'\u0004 אלהי \u0003צבאות שמו\",\u0004 שהוא גם היוצר וגם הבורא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו מין: \u0003נקוט לי זימנא תלתא יומי ומהדרנא לך תיובתא\u0004 \u0005[תן לי זמן שלושה ימים ואחזיר לך תשובה].\u0006 \u0003יתיב רבי תלת תעניתא\u0004 \u0005[ישב רבי שלוש תעניות],\u0006 באותם שלושה ימים, כדי שלא ימצא לו אותו מין תשובה, שלא יהיה בכך חילול שם שמים. \u0003כי הוה קא בעי מיברך\u0004 \u0005[כאשר\u0006 עברו אותם שלושה ימים, ו\u0005היה רוצה\u0006 רבי \u0005לסעוד],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לרבי: \u0003מינא קאי אבבא\u0004 \u0005[מין עומד בשער].\u0006 \u0003אמר\u0004 רבי על עצמו את הפסוק: \u0003\"ויתנו בברותי רוש\u0004 (עשב מר) \u0003ולצמאי ישקוני חומץ\"\u0004 (תהלים סט, כב), כלומר, נותנים דבר מר לסעודתי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 המין שעמד בפתח: \u0003רבי, מבשר טובות אני לך, לא מצא תשובה אויבך, ונפל\u0004 (הפיל עצמו) \u0003מן הגג ומת. אמר לו\u0004 רבי: הואיל ובישרת לי בשורה טובה, \u0003רצונך שתסעוד אצלי? אמר לו: הן. לאחר שאכלו ושתו, אמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 רבי: \u0003כוס של ברכה אתה שותה,\u0004 כלומר האם רצונך לברך ברכת מזון על הכוס, \u0003או ארבעים זהובים אתה נוטל,\u0004 ואני אברך? \u0003אמר לו: כוס של ברכה אני שותה. יצתה בת קול ואמרה: כוס של ברכה ישוה ארבעים זהובים.\u0004","\u0003אמר רבי יצחק: עדיין ישנה לאותה משפחה\u0004 של אותו מין שבישר לו את הבשורה, \u0003בין גדולי רומי, וקוראין אותה משפחת בר לויאנוס.\u0004","שנינו במשנה: \u0003כסהו ונתגלה\u0004 — פטור מלכסות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מאי שנא\u0004 \u0005[במה שונה\u0006 הדבר\u0005]\u0006 \u0003מהשבת אבדה,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מה שנאמר \"השב תשיבם\" (דברים כב, א) \u0003\"השב\"\u0004 — \u0003אפילו מאה פעמים?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם לא כתיב מיעוטא\u0004 \u0005[שם לא נאמרה לשון מיעוט],\u0006 \u0003הכא, כתיב מיעוטא\u0004 \u0005[כאן נאמרה לשון מיעוט]\u0006 \u0003\"וכסהו\"\u0004 כלומר, כסה אותו, כיסוי זה ולא יותר.","שנינו במשנה: \u0003כסהו הרוח\u0004 — חייב לכסות. \u0003אמר רבה בר בר חנה אמר רבי יוחנן: לא שנו אלא שחזר ונתגלה\u0004 לאחר שכיסהו הרוח. \u0003אבל לא חזר ונתגלה\u0004 — \u0003פטור מלכסות.\u0004 ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003חזר ונתגלה מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003הא אידחי ליה\u0004 \u0005[הרי\u0006 כבר \u0005נדחה]\u0006 ממצות הכיסוי כשכיסהו הרוח! \u0003אמר רב פפא, זאת אומרת: אין\u0004 מושג \u0003דיחוי\u0004 שייך \u0003אצל מצות,\u0004 וכיון שנתחייב הדם בכיסוי — לא נדחתה ממנו המצוה, ואם נתגלה — עומדת בעינה המצוה לכסותו.","ושואלים: ואם כסהו הרוח ולא נתגלה, מדוע פטור מלכסות? \u0003ומאי שנא מהא דתניא\u0004 \u0005[ובמה שונה\u0006 הדבר \u0005מזו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003השוחט\u0004 חיה או עוף \u0003ונבלע דם בקרקע\u0004 — \u0003חייב לכסות?\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 מדובר\u0005]\u0006 \u0003כשרשומו\u0004 של הדם \u0003ניכר\u0004 בקרקע, שלא נבלע לגמרי.","\u0003דם\u0004 חיה או עוף \u0003שנתערב במים, אם יש בו מראית דם\u0004 בתערובת — \u0003חייב לכסות. נתערב\u0004 הדם \u0003ביין\u0004 שהוא אדום — \u0003רואין אותו\u0004 את היין \u0003כאילו הוא מים,\u0004 ואם בכמות כזו של מים היתה מראית דם — חייב לכסות. \u0003נתערב\u0004 דם החיה או העוף \u0003בדם הבהמה\u0004"],["\u0003או בדם\u0004 אחר של \u0003החיה,\u0004 שאינו דם השחיטה — \u0003רואין אותו,\u0004 את דם הבהמה או את דם החיה האחר, \u0003כאילו הן מים. רבי יהודה אומר: אין דם מבטל דם,\u0004 ואפילו לא היה ניכר בו דם השחיטה — חייב לכסות את התערובת.","\u0003דם הניתז\u0004 מחוץ לגומה ששוחט לתוכה, או על הכותל, \u0003ו\u0004כן הדם \u0003ש\u0004נותר \u0003על הסכין\u0004 ששחט בה — \u0003חייב לכסות. אמר רבי יהודה: אימתי\u0004 חייב לכסות — \u0003בזמן שאין שם דם אלא הוא, אבל יש שם דם שלא הוא,\u0004 שמקיים בו מצות כיסוי — \u0003פטור מלכסות.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת זבחים ביחס לדם הקרבנות: \u0003דם\u0004 קרבן \u0003שנתערב במים, אם יש בו\u0004 בתערובת \u0003מראית דם\u0004 — \u0003כשר\u0004 לזריקה על המזבח ולכפר. \u0003נתערב\u0004 דם הקרבן \u0003ביין\u0004 — \u0003רואין אותו\u0004 את היין \u0003כאילו הוא מים,\u0004 ואם היה ניכר בהם הדם — כשר. \u0003נתערב\u0004 דם הקרבן \u0003בדם בהמה\u0004 של חולין, \u0003או בדם החיה\u0004 — \u0003רואין אותו,\u0004 את דם הבהמה או החיה, \u0003כאילו הוא מים. רבי יהודה אומר: אין דם מבטל דם.\u0004","ועל אותה משנה \u0003אמר רבי חייא בר אבא אמר רבי יוחנן: לא שנו\u0004 שאם יש מראית דם במים הרי זה כשר לזריקה — \u0003אלא שנפלו מים לתוך דם\u0004 הקרבן, \u0003אבל נפל דם\u0004 הקרבן \u0003לתוך מים\u0004 — \u0003ראשון ראשון בטל,\u0004 כל טיפת דם שנפלה למים נתבטלה, וגם אם בסופו של דבר יש שם מראית דם — אינו יכול לזורקו על המזבח, שהדם שנדחה מהקרבה אינו חוזר ונעשה ראוי לכך.","\u0003אמר רב פפא: ולענין כסוי\u0004 דם החיה או העוף \u0003אינו כן,\u0004 אלא אם לאחר שנפלה טיפה ועוד טיפה למים יש בהם מראה דם — צריך לכסות, ואין אומרים שכל טיפה וטיפה נדחתה ממצוותה, לפי ש\u0003אין דחוי אצל מצות,\u0004 שהדם שנתבטל תחילה במים לא נדחה ממצוותו, ולכן כשהוא חוזר ומקבל מראה דם — טעון כיסוי.","ועוד בעניינים אלה, \u0003אמר רב יהודה אמר שמואל: כל\u0004 מים שיש בהם \u0003מראה אדמומית\u0004 של דם — \u0003מכפרין\u0004 על המזבח, \u0003ומכשירין\u0004 אוכל לקבלת טומאה, \u0003וחייבין בכסוי,\u0004 אם מדובר בדם שחיטה של חיה או עוף. ומקשים: \u0003מאי קמשמע לן\u0004 \u0005[מה משמיע לנו]\u0006 ר' יהודה? שהם \u0003מכפרין\u0004 — \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה במסכת זבחים שהובאה לעיל, שהם \u0003חייבין בכסוי\u0004 — \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו!","ומשיבים: לומר שהם \u0003מכשירין איצטריכא ליה\u0004 \u0005[הוצרך לו],\u0006 שלא שנינו דין זה במשנה. ומתקשים: \u0003מכשירין נמי\u0004 \u0005[גם כן]\u0006 לא הוצרך לאומרו, שהרי בין \u0003אי\u0004 \u0005[אם]\u0006 יש לתערובת דין \u0003דם\u0004 — \u0003אכשורי מכשר\u0004 \u0005[הריהו מכשיר],\u0006 ובין \u0003אי מיא\u0004 \u0005[אם הוא מים]\u0006 — \u0003אכשורי מכשרי\u0004 \u0005[הריהם מכשירים]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכו]\u0006 דברי רב יהודה בשם שמואל, אלא למקרה \u0003שתמדו,\u0004 שעירב את הדם \u0003במי גשמים,\u0004 שאינם מכשירים את האוכלים, לפי שמשקים מכשירים לקבל טומאה רק כאשר אדם חשב עליהם, ומי גשמים באים מעצמם.","ומקשים: \u0003מי גשמים\u0004 שנתערב בהם דם \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003כיון דשקיל ורמי\u0004 \u0005[שנטל\u0006 אותם \u0005והטיל\u0006 אותם בכלי\u0005]\u0006 שבו נתערב הדם \u0003אחשבינהו\u0004 \u0005[\u0006הרי \u0005החשיב אותם],\u0006 ומכשירים לקבל טומאה! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 אלא במקרה \u0003שנתמדו מאליהן,\u0004 שמי גשמים ירדו מעצמם לתוך כלי, ונתערב בהם הדם.","\u0003רבי אסי מנהרביל אומר:\u0004 דבריו של רב יהודה בשם שמואל נאמרו \u0003בצללתא דדמא\u0004 \u0005[בנוזל הצלול של הדם],\u0006 שכשהדם נקרש הוא נפרד לעצמו, לומר שאם יש בו מראה אדמומית — דינו כדם, ומכשיר, ואם לא — אינו מכשיר, שאינו מים ולא דם. \u0003רבי ירמיה מדפתי אמר:\u0004 האוכל מנוזל זה כשיש בו מראה אדמומית, \u0003ענוש כרת,\u0004 כדין אוכל דם (ויקרא יז, יד), \u0003והוא דאיכא\u0004 \u0005[שיש]\u0006 בו \u0003כזית\u0004 דם גמור. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 משקים שיש בהם מראית דם, אם היה זה דם המת — \u0003מטמאים באהל, והוא דאיכא\u0004 \u0005[שיש]\u0006 שם \u0003רביעית\u0004 הלוג דם גמור, שדם המת מטמא אם היה בו שיעור רביעית.","ועוד בענין זה, \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003כל משקה המת,\u0004 כל הנוזלים שבגופו, כגון דמעות, או חלב האשה — \u0003טהורין, חוץ מדמו; וכל מראה אדמומית שבו,\u0004 כלומר, נוזל הבא מן המת, אם יש בו מראית דם — \u0003מטמאין באהל.\u0004 ושואלים: \u0003ומשקה המת טהורין? ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: כדין \u0003משקה טבול יום,\u0004 של אדם ביום שטבל לטומאתו, דין \u0003משקין היוצאין ממנו כ\u0004דין \u0003משקין ש\u0004הוא \u0003נוגע בהן,\u0004"],["\u0003ואלו ואלו,\u0004 משקה היוצא מטבול יום ומשקה הנוגע בו — \u0003אין מטמאין\u0004 את מה שנגעו בו. \u0003ושאר כל הטמאין,\u0004 חוץ מטבול יום, \u0003בין קלין בין חמורין\u0004 — דין \u0003משקין היוצאין מהן כ\u0004דין \u0003משקה הנוגע בהן, ואלו ואלו,\u0004 המשקין היוצאים משאר הטמאים, כגון חלב האשה הזבה, והמשקים שנגעו בהם — הריהם \u0003תחלה,\u0004 בדרגת ראשון לטומאה, שהרי נגעו באב הטומאה כשיצאו מגופו. \u0003חוץ מן המשקה שהוא אב הטומאה\u0004 בעצמו, כגון זובו של הזב ושכבת זרעו, ומי רגליו, ורוקו, שנאמר בתורה שהם מטמאים.","ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 טמאים \u0003קלין ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 טמאים \u0003חמורין? מאי לאו\u0004 \u0005[האם לא]:\u0006 \u0003קלין\u0004 — \u0003שרץ וזב, וחמורין\u0004 — \u0003מת?\u0004 הרי שהמשקה היוצא מן המת (חוץ מדמו) הריהו ראשון לטומאה, ואינו טהור כפי ששנינו בברייתא בעמוד הקודם! ומשיבים: \u0003לא, קלין\u0004 — \u0003שרץ,\u0004 כגון מי רגלים שנמצאו בגוף השרץ, \u0003וחמורין\u0004 — \u0003זב.\u0004 אבל מת, המשקים היוצאים ממנו — טהורים.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003זב, דגזרו ביה רבנן\u0004 \u0005[שגזרו בו חכמים]\u0006 טומאה על המשקים (שאינם אב הטומאה) היוצאים ממנו, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003מת דלא גזרו ביה רבנן\u0004 \u0005[שלא גזרו בו חכמים]?\u0006 ומשיבים: \u0003זב דלא בדילי אינשי מיניה\u0004 \u0005[שאין אנשים בדלים ממנו]\u0006 — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 על שאר משקים היוצאים ממנו, כדי שאנשים יזהרו ולא ייטמאו על ידו טומאה שמן התורה. אבל \u0003מת, דבדילי אינשי מיניה\u0004 \u0005[שבדלים אנשים ממנו]\u0006 — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006","שנינו: \u0003דם הניתז ושעל הסכין\u0004 חייב לכסות. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"וכסהו\"\u0004 (ויקרא יז, יג) — \u0003מלמד שדם הניתז ושעל הסכין חייב לכסות. אמר רבי יהודה: אימתי? בזמן שאין שם דם אלא הוא, אבל יש שם דם שלא הוא,\u0004 שנעשתה בו מצות כיסוי — \u0003פטור מלכסות.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"וכסהו\"\u0004 — \u0003מלמד שכל דמו חייב לכסות, מכאן אמרו: דם הניתז ושעל אגפיים,\u0004 צדדי מקום השחיטה — \u0003חייב לכסות. אמר רבן שמעון בן גמליאל; במה דברים אמורים\u0004 — ב\u0003שלא כסה\u0004 את \u0003דם הנפש,\u0004 הדם שהנפש יוצאת בו, \u0003אבל כסה דם הנפש\u0004 — \u0003פטור מלכסות\u0004 את הדם הניתז ושעל האגפיים.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 ומשיבים, \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 מה שנאמר \u0003\"דמו\",\u0004 כוונתו \u0003—\u0004 \u0003כל דמו,\u0004 ולכן גם דם הניתז חייב לכסות. \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003\"דמו\"\u0004 כוונתו — כל חלק מדמו, \u0003ואפילו מקצת דמו\u0004 מתקיימת בו מצות כיסוי, ולכן אם נתכסה חלק מן הדם — פטור מלכסות את השאר. \u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003\"דמו\"\u0004 — \u0003המיוחד,\u0004 דם הנפש, שהוא צריך כיסוי.","\u0003במה מכסין\u0004 את הדם \u0003ובמה אין מכסין? מכסין בזבל הדק\u0004 שעשוי מגרגרים קטנים, \u0003ובחול הדק, בסיד, ובחרסית, ובלבנה ובמגופה\u0004 (כיסוי של חבית) \u0003שכתשן. אבל אין מכסין לא בזבל הגס\u0004 (עבה, גדול), \u0003ולא בחול הגס\u0004 שעשוי גושים, \u0003ולא בלבנה ובמגופה שלא כתשן, ולא יכפה עליו את הכלי. כלל אמר רבן שמעון בן גמליאל: דבר שמגדל בו צמחים\u0004 — \u0003מכסין בו, ושאינו מגדל צמחים\u0004 — \u0003אין מכסין בו.\u0004","שנינו במשנה: מכסים בחול הדק. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003חול הדק?\u0004 מהי הגדרתו? \u0003אמר רבה בר בר חנה אמר רבי יוחנן: כל שאין היוצר\u0004 (עושה כלי החרס) \u0003צריך לכתשו\u0004 כדי ליצור ממנו את כלי החרס. \u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששונה אותה,\u0006 בשינוי, \u0005על סופה\u0006 של המשנה\u0005]:\u0006 \u0003אבל אין מכסין לא בזבל הגס ולא בחול הגס.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003חול הגס\u0004 שאין מכסים בו? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל שהיוצר צריך לכתשו\u0004 כדי לעשות בו מלאכתו.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם,\u0006 בין שתי הלשונות\u0005]? ומשיבים:\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 חול ש\u0003צריך ולא צריך\u0004 כתישה, \u0003דמיפריך איפרוכי\u0004 \u0005[שנפרך\u0006 ביד\u0005];\u0006 ללשון הראשונה, שכל שאינו צריך כתישה הוא חול הדק — חול שצריך פריכה גם הוא אינו צריך כתישה, והוא כשר לכיסוי. לפי הלשון השניה, שכל שצריך כתישה הוא חול הגס שאין מכסים בו — גם מה שצריך פריכה בכלל זה, ואין מכסים בו.","ובענין ששנינו במשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר במצות כיסוי הדם \u0003\"וכסהו\"\u0004 (ויקרא יז, יג), \u0003יכול יכסנו באבנים או יכפה עליו את הכלי? תלמוד לומר: \"בעפר\"\u0004 (שם). \u0003ואין לי אלא עפר, מנין לרבות זבל הדק, וחול הדק, ושחיקת אבנים, ושחיקת חרסית, ונעורת פשתן דקה\u0004 סיבים קטנים שמנערים מן הפשתן,"],["\u0003ונסורת של חרשין\u0004 (נגרים) \u0003דקה, וסיד, וחרסית,\u0004 וכן \u0003לבנה ומגופה\u0004 (כיסוי של חבית) \u0003שכתשן? תלמוד לומר: \"וכסהו\"\u0004 (ויקרא יז, יג), ומשמע — בכל דבר. \u0003יכול שאני מרבה אף זבל הגס, וחול הגס, ושחיקת כלי מתכות, ולבנה ומגופה שלא כתשן, וקמח, וסובין,\u0004 שנשאר בנפה לאחר סינון הקמח, \u0003ומורסן,\u0004 שאריות של קליפות החיטה שנכתשה? \u0003תלמוד לומר:\u0004 \"וכסהו \u0003בעפר\",\u0004 ומכאן אתה למד שהציווי \"וכסהו\" אינו כולל כל דבר.","ויש לשאול: \u0003ומה ראית לרבות את אלו ולהוציא את אלו?\u0004 על כך יש להשיב: \u0003אחר שריבה הכתוב\u0004 (\"וכסהו\") \u0003ומיעט\u0004 (\"בעפר\"), \u0003מרבה אני את אלו,\u0004 חול הדק וכו' — \u0003שהן מין עפר,\u0004 שמגדל צמחים, \u0003ומוציא אני את אלו,\u0004 חול הגס וכו' — \u0003שאין מין עפר,\u0004 שאינם מגדלים צמחים.","ושואלים: ומדוע אתה דורש כך את הכתוב? \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003\"וכסהו\"\u0004 — \u0003כלל, \"עפר\"\u0004 — \u0003פרט,\u0004 ולפי כללי מדרש ההלכה, \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ואם כן, \u0003עפר\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[\u0006כל \u0005דבר אחר]\u0006 — \u0003לא!\u0004","\u0003אמר רב מרי: משום דהוה\u0004 \u0005[ש\u0006\"וכסהו\" \u0005הוא]\u0006 \u0003כלל הצריך לפרט,\u0004 ש\"בעפר\" מפרש מהי מהות הכיסוי, שהוא נעשה בדבר שהדם נבלע ומתערב בו. \u0003וכל כלל הצריך לפרט\u0004 — \u0003אין דנין אותו בכלל ופרט.\u0004","מסופר, \u0003דרש רב נחמן בר רב חסדא\u0004 בפני הרבים: \u0003אין מכסים\u0004 דם חיה או עוף \u0003אלא בדבר שזורעין בו ומצמיח.\u0004 \u0003אמר רבא: האי בורכא\u0004 \u0005[זו היא בורות,\u0006 שטות\u0005],\u0006 שהרי במשנה ובברייתא שנינו שמכסים בדברים שאם זורעים בהם אינם מצמיחים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: מאי בורכתיה\u0004 \u0005[מה היא בורותו]?\u0006 \u0003אנא אמריתה ניהליה\u0004 \u0005[אני אמרתי\u0006 אותה \u0005לו]\u0006 לרב נחמן בר רב חסדא, \u0003ומהא מתניתא אמריתה ניהליה\u0004 \u0005[ומברייתא זו אמרתי\u0006 אותה \u0005לו],\u0006 ששנינו: \u0003היה מהלך במדבר,\u0004 שהעפר שם אינו מצמיח מה שזורעים בו, ורוצה לשחוט חיה או עוף, \u0003ואין לו אפר לכסות\u0004 את דמו — \u0003שוחק דינר זהב ומכסה\u0004 בו. וכן \u0003היה מהלך בספינה ואין לו עפר לכסות\u0004 — \u0003שורף טליתו ומכסה\u0004 באפרה. הרי שאין מכסים בעפר המדבר, שאינו מצמיח.","ושואלים לגופה של הברייתא: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 ש\u0003שורף טליתו ומכסה,\u0004 שכן \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003אפר דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"עפר\",\u0004 כאשר יבואר להלן, ואם כן מתקיים בו \"וכיסהו בעפר\". \u0003אלא דינר זהב מנלן\u0004 \u0005[מנין לנו]\u0006 שאפשר לשחוק אותו ולכסות בו? \u0003אמר רבי זירא,\u0004 שנאמר: \u0003\"ועפרות זהב לו\"\u0004 (איוב כח, ו), הרי שזהב קרוי עפר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מכסין אלא בעפר, דברי בית שמאי. ובית הלל אומרים: מצינו אפר שקרוי \"עפר\", שנאמר \"ולקחו לטמא מעפר שריפת\u0004 החטאת\" (במדבר יט, יז). \u0003ובית שמאי\u0004 משיבים: \u0003עפר שריפה איקרי\u0004 \u0005[\u0006הוא \u0005נקרא],\u0006 \u0003עפר סתמא לא איקרי\u0004 \u0005[עפר סתם אינו נקרא].\u0006","ביחס לרשימת הדברים ששנינו במשנתנו שמכסים בהם, \u0003תנא\u0004 \u0005[שנה]:\u0006 \u0003הוסיפו עליהן השחור\u0004 (פחם כתוש), \u0003והכחול\u0004 (צבע המשמש לכחול עינים), \u0003ונקרת פיסולין,\u0004 עפר של פיסול וחציבה באבנים, \u0003ויש אומרים: אף הזרניך,\u0004 אחד ממיני המחצבים.","ומביאים דברי אגדה בענין מצות כיסוי הדם. \u0003אמר רבא: בשכר שאמר אברהם אבינו: \"ואנכי עפר ואפר\"\u0004 (בראשית יח, כז) — \u0003זכו בניו לשתי מצות: אפר פרה\u0004 אדומה, שמטהרים בו מטומאת מת (במדבר יט, ט), \u0003ועפר סוטה,\u0004 עפר מקרקע המשכן שנותן הכהן במים שבודקים בהם את הסוטה לבודקה אם זינתה (שם ה, יז).","ושואלים: \u0003וליחשוב נמי\u0004 \u0005[ושיחשיב גם כן]\u0006 \u0003עפר כסוי הדם!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בכיסוי הדם — \u0003הכשר מצוה איכא\u0004 \u0005[יש],\u0006 שמשתמש בעפר לצורך קיום מצוה, אבל \u0003הנאה ליכא\u0004 \u0005[אין],\u0006 כמו שיש בשתי מצוות אלו, שיש בהן טהרתם וחשיבותם של ישראל.","\u0003ואמר רבא: בשכר שאמר אברהם אבינו\u0004"],["\u0003\"אם מחוט ועד שרוך נעל\u0004 ואם אקח מכל אשר לך\" (בראשית יד, כג), שלא רצה ליהנות ממה שאינו שלו, וקידש שם שמים — \u0003זכו בניו לשתי מצות, לחוט של תכלת\u0004 בציצית, שנאמר \"ונתנו על ציצית הכנף פתיל תכלת\" (במדבר טו, לח), \u0003ורצועה של תפילין,\u0004 שהיא עשויה עור, כמו שרגיל היה להיות שרוך של נעל.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 מה זכות מיוחדת ב\u0003רצועה של תפילין,\u0004 שהרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וראו כל עמי הארץ כי שם ה' נקרא עליך\u0004 ויראו ממך\" (דברים כח, ו), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: אלו תפילין שבראש,\u0004 שניכר בהם ששם השם נקרא על ישראל. \u0003אלא חוט של תכלת מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 הזכות המיוחדת שיש בו?","ומשיבים: \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי מאיר אומר: מה נשתנה תכלת מכל\u0004 מיני \u0003הצבעונין,\u0004 שנותנים אותו על ציצית הכנף? \u0003מפני שתכלת דומה\u0004 בצבעה \u0003לים, וים דומה\u0004 בצבעו \u0003לרקיע\u0004 \u0003ורקיע דומה לאבן ספיר, ואבן ספיר דומה לכסא הכבוד,\u0004 וזכות מיוחדת היא לישראל שזכר כסא הכבוד נמצא על בגדיהם. ומנין שרקיע דומה לאבן ספיר, ואבן הספיר דומה לכסא הכבוד? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויראו את אלהי ישראל ותחת רגליו\u0004 כמעשה לבנת הספיר וכעצם השמים לטוהר\" (שמות כ״ד:י׳), הרי שמראה אבן הספיר הוא כעצם השמים, כלומר כמראה הרקיע. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בחזון יחזקאל: \u0003\"כמראה אבן ספיר דמות כסא\"\u0004 (יחזקאל א, כו), הרי שכסא הכבוד הוא כמראה אבן ספיר.","אגב שנזכרו דברי אברהם למלך סדום, מביאים מה ש\u0003אמר ר' אבא: קשה\u0004 השבת \u0003גזל\u0004 של הדבר שכבר \u0003נאכל\u0004 יותר מגזל רגיל, \u0003שאפילו צדיקים גמורים אינן יכולין להחזירו, שנאמר:\u0004 \"ואם אקח מכל אשר לך \u0003בלעדי רק אשר אכלו הנערים\"\u0004 (בראשית יד, כד), הרי שחוט ושרוך נעל החזיר, ולא יכול היה להחזיר מה שאכלו הנערים.","מתוך שהוזכרו דברי אברהם \"ואנכי עפר ואפר\", מביאים מה ש\u0003אמר\u0004 בענין זה \u0003ר' יוחנן משום ר' אלעזר בר' שמעון: כל מקום שאתה מוצא דבריו של ר' אליעזר בנו של ר' יוסי הגלילי בהגדה\u0004 — \u0003עשה אזניך כאפרכסת,\u0004 כמשפך, לקלוט את דבריו. שכך אמר על הפסוק \u0003\"לא מרבכם מכל העמים חשק ה' בכם\u0004 ויבחר בכם כי אתם המעט מכל העמים\" (דברים ז, ז) — \u0003אמר להם הקדוש ברוך הוא לישראל: חושקני\u0004 (חושק אני) \u0003בכם, שאפילו בשעה שאני משפיע לכם גדולה\u0004 — \u0003אתם ממעטין עצמכם לפני;\u0004","\u0003נתתי גדולה לאברהם\u0004 — \u0003אמר לפני: \"ואנכי עפר ואפר\"\u0004 (בראשית יח, כז), נתתי גדולה \u0003למשה ואהרן\u0004 — \u0003אמר\u0004 משה: \u0003\"ונחנו מה\"\u0004 (שמות טז, ז), נתתי גדולה \u0003לדוד\u0004 — \u0003אמר: \"ואנכי תולעת ולא איש\"\u0004 (תהלים כב, ז).","\u0003אבל אומות העולם אינן כן, נתתי גדולה לנמרוד\u0004 — \u0003אמר: \"הבה נבנה לנו עיר\u0004 ומגדל וראשו בשמים ונעשה לנו שם\" (בראשית יא, ד), נתתי גדולה \u0003לפרעה\u0004 — \u0003אמר: \"מי ה' \"\u0004(שמות ה, כ), נתתי גדולה \u0003לסנחריב\u0004 — \u0003אמר: \"מי בכל אלהי הארצות\u0004 אשר הצילו את ארצם מידי, כי יציל ה' את ירושלים מידי\" (מלכים ב יח, לה), נתתי גדולה \u0003לנבוכדנצר\u0004 — \u0003אמר: \"אעלה על במתי עב\"\u0004 (ישעיהו יד, ד), נתתי גדולה \u0003לחירם מלך צור\u0004 — \u0003אמר: \"מושב אלהים ישבתי בלב ימים\"\u0004 (יחזקאל כח, ב).","אגב כך מביאים מה ש\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוחנן: גדול\u0004 מה \u0003שנאמר במשה ואהרן יותר ממה שנאמר באברהם,\u0004 ש\u0003אילו באברהם כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואנכי עפר ואפר\", ואילו במשה ואהרן כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ונחנו מה\",\u0004 כלומר, איננו כלום, אפילו לא עפר ואפר. \u0003ואמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוחנן: אין העולם מתקיים אלא בשביל\u0004 (בגלל, בזכות) \u0003משה ואהרן, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ונחנו מה\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"תולה ארץ על בלימה\"\u0004 (איוב כו, ז), כלומר, הארץ תלויה על מי שאמר \"ונחנו מה\", שאינו כלום.","ודרשה אחרת בענין \"בלימה\" \u0003אמר רבי אילעא: אין העולם מתקיים אלא בשביל מי שבולם את עצמו בשעת מריבה, שנאמר \"תולה ארץ על בלימה\". רבי אבהו אמר:\u0004 אין העולם מתקיים אלא בשביל \u0003מי שמשים עצמו כמי שאינו, שנאמר \"ומתחת זרועות עולם\"\u0004 (דברים ל, כז), כלומר, מי שמשים עצמו מתחת — הריהו כזרועות המחזיקות את העולם.","\u0003אמר רבי יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"האמנם אלם צדק תדברון מישרים תשפטו בני אדם\"\u0004 (תהלים נח, ב)? \u0003מה אומנותו\u0004 (\"האמנם\") \u0003של אדם בעולם הזה\u0004 — \u0003ישים עצמו כאלם,\u0004 ישתוק. \u0003יכול אף לדברי תורה\u0004 ישים עצמו כאלם? \u0003תלמוד לומר: \"צדק תדברון\",\u0004 שמצוה לדבר בדברי תורה. ושמא תעלה על דעתך: הואיל ומותר ואף מצוה להרבות בדברי תורה, \u0003יכול יגיס דעתו,\u0004 שהעוסק יתגאה? \u0003תלמוד לומר: \"מישרים תשפטו בני אדם\",\u0004 שצריך לנהוג במישור, בדרך ענוה.","ושבים לדין כיסוי הדם. \u0003אמר רבי זעירא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רבה בר ירמיה: מכסין\u0004 דם חיה או עוף \u0003בעפר עיר הנדחת,\u0004 שהדיחו אנשיה את יושבי עירם לעבוד עבודה זרה, ודין העיר וכל אשר בה לשריפה (דברים יד, יז). ומתחילה הבינו כי הכוונה היא לאפר השריפה, ושאלו: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 מכסים? והרי אפר זה \u0003איסורי הנאה הוא,\u0004 שנאמר שם: \"ולא ידבק בידך מאומה מן החרם\" (דברים יג, יח), ממה שהוחרם ונשרף!","\u0003אמר זעירי: לא נצרכה\u0004 הלכה זו \u0003אלא לעפר עפרה,\u0004 כלומר, לעפר הקרקע של עיר הנידחת, שהוא איננו אסור בהנאה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת כל שללה תקבוץ אל תוך רחובה ושרפת\"\u0004 (שם יז) — \u0003מי שאינו מחוסר אלא קביצה ושרפה\u0004 נאמר בו דין זה, \u0003יצא זה,\u0004 עפר עפרה — \u0003שמחוסר\u0004 גם \u0003תלישה\u0004 מן הקרקע, וגם \u0003קביצה ושרפה.\u0004","\u0003ורבא אמר:\u0004 גם באפר השריפה שאסור בהנאה ניתן לקיים כיסוי הדם, מפני ש\u0003מצות לאו\u0004 \u0005[לא]\u0006 \u0003ליהנות ניתנו,\u0004 שאין מתייחסים לקיום מצוה כאל הנאה, אלא כקיום גזירת ה'.","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבינא וקאמר לה להא שמעתא\u0004 \u0005[ואומר שמועה זו]\u0006 של רבא, שניתן לקיים מצות כיסוי הדם באיסורי הנאה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב רחומי לרבינא\u0004 ממה ששנינו בברייתא: \u0003שופר של עבודה זרה,\u0004 שאסור בהנאה — \u0003לא יתקע בו; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003אם תקע\u0004 — \u0003לא יצא?\u0004 השיב לו: \u0003לא,\u0004 לכתחילה לא יתקע, אבל \u0003אם תקע\u0004 — \u0003יצא.\u0004","עוד הקשה לו ממה ששנינו: \u0003לולב של עבודה זרה לא יטול\u0004 בסוכות, \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003אם נטל\u0004 — \u0003לא יצא?\u0004 השיב לו: \u0003לא, אם נטל\u0004 — \u0003יצא.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 מפורשת: \u0003תקע\u0004 בשופר — \u0003לא יצא, נטל\u0004 לולב — \u0003לא יצא!\u0004","\u0003אמר רב אשי: הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 מתחילה אין להקשות מדין שופר ולולב של עבודה זרה על מצוות כיסוי הדם, שכן \u0003התם\u0004 \u0005[שם]\u0006 בשופר ולולב של עבודה זרה, טעם הדבר שלא יצא אינו משום שהוא אסור בהנאה, שהרי מצוות לא ליהנות ניתנו, אלא"],["\u0003שיעורא בעינן\u0004 \u0005[שיעור\u0006 מינימאלי \u0005אנו צריכים]\u0006 לקיום המצוה, בשופר — כדי שיוכל לאוחזו בידו וייראה מכאן ומכאן, ובלולב — שיעורו ארבעה טפחים. \u0003ועבודה זרה\u0004 ומשמשיה, כיון שהם עומדים לשריפה — הרי זה כאילו נשרפו, ו\u0003כתותי מכתת שיעורא\u0004 \u0005[כתות ושבור שיעורו],\u0006 וכאילו אין לשופר או ללולב שיעור. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בכיסוי הדם, אין צורך בשיעור, ואדרבה — \u0003כל מה דמכתת מעלי\u0004 \u0005[כל מה שהוא כתות\u0006 יותר \u0005הרי זה טוב יותר]\u0006 \u0003ל\u0004מצות ה\u0003כיסוי.\u0004","","איסור אכילתו של \u0003גיד הנשה נוהג\u0004 (קיים) בין \u0003בארץ ו\u0004בין \u0003בחוצה לארץ;\u0004 בין \u0003בפני הבית\u0004 (בזמן שבית המקדש היה קיים), \u0003ו\u0004בין \u0003שלא בפני הבית;\u0004 בין \u0003ב\u0004בעלי חיים שהם \u0003חולין, ו\u0004בין \u0003ב\u0004אלה שהם \u0003מוקדשין. ונוהג\u0004 איסור זה \u0003בבהמה ובחיה, בירך של\u0004 צד \u0003ימין\u0004 שבהן \u0003ובירך של\u0004 צד \u0003שמאל\u0004 שבהן. \u0003ו\u0004אולם איסור זה \u0003אינו נוהג בעוף\u0004 — \u0003מפני ש\u0004באיסור גיד הנשה נאמר \"אשר על כף הירך\" (בראשית לב, לב), ואילו העוף \u0003אין לו כף\u0004 (בליטה של בשר שעל עצם הירך, שצורתה עגולה). \u0003ונוהג\u0004 איסור זה אף \u0003בשליל\u0004 (עובר בסמוך ללידתו הנתון בשליה במעי אמו). \u0003ר' יהודה אומר: אינו נוהג בשליל, ו\u0004בדומה לכך, גם \u0003חלבו\u0004 של השליל \u0003מותר.\u0004","","\u0003ואין הטבחין\u0004 (קצבים) \u0003נאמנין\u0004 לומר \u0003על\u0004 הבשר שהם מוכרים כי הוציאו ממנו את \u0003גיד הנשה,\u0004 אלו \u0003דברי ר' מאיר. ו\u0004אילו \u0003חכמים אומרים\u0004 כי הקצבים \u0003נאמנין\u0004 בדבריהם הן \u0003עליו,\u0004 על גיד הנשה שהוציאוהו, \u0003ו\u0004הן \u0003על החלב\u0004 שהוציאוהו.","שנינו במשנתנו כי איסור אכילת גיד הנשה הריהו נוהג בין בבהמות וחיות שהן חולין ובין באלה שהן \u0003מוקדשין,\u0004 ותוהים: מה טעם יש לשנות כן, והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שכך הדין? וסברה היא: הרי בתחילה בעל חיים זה המוקדש היה של חולין, ואז חל עליו איסור גיד הנשה, ומעתה יש לומר, וכי \u0003משום דאקדשיה\u0004 \u0005[שהקדישו]\u0006 בעליו, \u0003פקע ליה\u0004 \u0005[לו]\u0006 בכך \u0003איסור גיד\u0004 הנשה \u0003מיניה\u0004 \u0005[ממנו]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בטעם הדבר שנצרך הדבר להישנות במפורש, שכן איסור גיד הנשה אינו מותנה בטעם שיש בגיד, ואף אם הגיד לא היה מכיל כל טעם (ונמצא שבאכילתו לא היתה כל הנאה), הריהו בכלל איסור זה. ואולם מעתה ש\u0003יש בגידין בנותן טעם, ואתי\u0004 \u0005[ובא]\u0006 \u0003איסור\u0004 אכילת \u0003מוקדשין וחייל אאיסור\u0004 \u0005[וחל על איסור]\u0006 \u0003גיד\u0004 הנשה. ומעתה יש בו אף איסור אכילת קדשים — אין לומר כן, שהרי \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"מוקדשין נוהג בגיד\" מיבעי ליה\u0004 \u0005[נצרך לו,\u0006 לתנא\u0005]\u0006 לומר. שכן עיקר חידושו הוא שאיסור מוקדשים חל עליו! וחוזרים ומתרצים: \u0003אלא קסבר\u0004 \u0005[סבור הוא,\u0006 התנא במשנתנו\u0005]\u0006 כי \u0003אין בגידין בנותן טעם, ו\u0004לכך \u0003ב\u0004בהמות \u0003מוקדשין, איסור גיד\u0004 — \u0003איכא\u0004 \u0005[יש],\u0006 שכן אין איסור זה מותנה באכילה שיש בה טעם. ואילו \u0003איסור\u0004 אכילת \u0003מוקדשין\u0004 — \u0003ליכא\u0004 \u0005[אין]\u0006 בו, מאחר שאין זו אכילה בדבר שיש בו טעם. ומקשים על הסבר זה: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003תנא דידן\u0004 \u0005[שלנו,\u0006 במשנתנו\u0005]\u0006 כי \u0003אין בגידין בנותן טעם? והתנן\u0004 \u0005[והרי שנינו]\u0006 בפרקנו (להלן צו,ב): \u0003ירך ש\u0004לא הוצא גיד הנשה מתוכה, ו\u0003נתבשל בה\u0004 (יחד עם הירך) בקדירה, \u0003גיד הנשה, אם יש בה\u0004 שיעור \u0003ב\u0004כדי שיהא גיד הנשה \u0003נותן טעם\u0004 בירך — \u0003הרי זו\u0004 הירך כולה \u0003אסורה\u0004 באכילה. הרי שסבור התנא כי יש בגיד הנשה נתינת טעם! ומציעים הסבר אחר:","","\u0003אלא, הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005]\u0006 לא בבהמות קדשים מדובר, אלא \u0003בולדות\u0004 בהמות \u0003קדשים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וקסבר\u0004 \u0005[וסבור הוא,\u0006 התנא\u0005]\u0006 כי איסור גיד הנשה \u0003נוהג\u0004 אף \u0003בשליל, ו\u0004כן \u0003קסבר\u0004 \u0005[סבור הוא,\u0006 התנא\u0005]\u0006 כי \u0003ולדות קדשים\u0004 הנמצאים עדיין \u0003במעי אמן הן קדושים.\u0004 ומעתה נמצא כי לא קדם איסור אכילת גיד הנשה לאיסור אכילת מוקדשים, אלא \u0003איסור גיד\u0004 הנשה \u0003ואיסור מוקדשין בהדי הדדי קאתי\u0004 \u0005[ביחד הם באים].\u0006","ומקשים על כך: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם אתה יכול להעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003בשליל, והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 \u0003\"נוהג בשליל\", מכלל דרישא לאו\u0004 \u0005[מכאן\u0006 נלמד \u0005שבתחילת\u0006 המשנה \u0005לא]\u0006 \u0003בשליל עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 ומשיבים: אף בתחילת המשנה מדובר בשליל, ו\u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא בסוף המשנה \u0005אומר]:\u0006 \u0003דבר זה\u0004 ששנינו בדין גיד הנשה בשליל, אין הוא כדברי הכל, אלא שנוי \u0003ב\u0004\u0003מחלוקת\u0004 של \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים].\u0006","וחוזרים ומקשים על העמדת משנתנו בשליל, וכשיטה הסבורה שוולדות קדשים הריהם קדושים במעי אמם: \u0003ומי מצית אמרת דתרוייהו בהדי הדדי קאתו\u0004 \u0005[והאם אתה יכול לומר ששניהם,\u0006 איסור גיד הנשה ואיסור מוקדשים, \u0005באים ביחד]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003על אלו טומאות הנזיר\u0004 סותר את מנין ימי נזירותו ו\u0003מגלח\u0004 את שערו, ופותח במנין חדש של ימי נזירות? \u0003על\u0004 הנטמא מן \u0003המת ועל\u0004 הנטמא מן \u0003כזית מן המת, וקשיא לן\u0004 \u0005[והיה קשה לנו]\u0006 בדברי המשנה הללו: אם \u0003על כזית מן המת\u0004 בלבד הנזיר \u0003מגלח, על\u0004 המת \u0003כולו לא כל שכן\u0004 שהוא מגלח, ומדוע שנה זאת התנא? \u0003ואמר ר' יוחנן\u0004 בהסבר הדברים: \u0003לא נצרכה\u0004 משנה זו להשמיענו דינו של הנטמא במת כולו, \u0003אלא ל\u0004זה שנטמא בגופו של \u0003נפל ש\u0004מת, שאמנם השלד הריהו שלם, והריהו נחשב כמת כולו, ואולם עדיין \u0003לא נקשרו אבריו בגידין,\u0004 ואין בו כזית בשר. וללמדנו שאף באופן זה הנזיר מגלח.",""],["\u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 שיצירת איברי הגוף קודמת ליצירת הגידים, ומכאן ש\u0003איסור מוקדשין\u0004 החל על גוף ולד הבהמה משעה שנוצר הריהו \u0003קדים\u0004 \u0005[קודם]\u0006 לאיסור גיד הנשה, ואין שני איסורים אלה באים כאחד! ומשיבים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003איסור מוקדשין\u0004 אמנם \u0003קדים\u0004 \u0005[קודם]\u0006 לאיסור גיד הנשה, מכל מקום","\u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור גיד\u0004 ו\u0003חייל עלייהו\u0004 \u0005[וחל עליהם,\u0006 על ולדות המוקדשים\u0005],\u0006 וטעם הדבר: משום שהריהו איסור חמור, \u0003שכן איסורו נוהג\u0004 אף \u0003בבני נח\u0004 (בנכרים, בשאינם יהודים). שהרי חל איסור זה על בני ישראל עוד קודם למתן תורה, ובאותה עת היו בני ישראל בכלל \"בני נח\". ומקשים על הסבר זה: אי אפשר להעמיד את דברי משנתנו כשיטה זו, שהרי","\u0003מאן\u0004 \u0005[מי]\u0006 החכם ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 אומר \u0003האי סברא\u0004 \u0005[סברה זו],\u0006 שאיסור גיד הנשה נוהג אף בבני נח? — הלא הוא \u0003ר' יהודה\u0004 (להלן במשנה ק,ב), \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 היא ש\u0003לא\u0004 כשיטת \u0003ר' יהודה, דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו במשנתנו]\u0006 כי איסור גיד הנשה \u0003נוהג בבהמה ובחיה, בירך של ימין ובירך של שמאל,\u0004 ואילו שיטת ר' יהודה (בברייתא המובאת בעמוד הבא) היא שאיסור גיד הנשה נוהג בירך אחת בלבד! ודוחים:","\u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 של משנתנו \u0003סבר לה כוותיה בחדא\u0004 \u0005[הריהו סבור כמותו,\u0006 כדעת ר' יהודה, \u0005ב\u0006ענין \u0005אחד],\u0006 שאיסור גיד הנשה נוהג אף בבני נח, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו\u0006 בענין \u0005אחד],\u0006 ולדעתו נוהג איסור זה בשתי הירכיים.","ושואלים עוד על העמדת משנתנו כשיטת ר' יהודה: \u0003אימר\u0004 \u0005[אמור,\u0006 יש מקום לומר\u0005]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' יהודה\u0004 שסבור כי משום שאיסור גיד הנשה הוא איסור חמור (שכן הוא אסור אף לבני נח), ולכך הריהו חל על איסור קודם. ואולם אין זה אלא \u0003ב\u0004בהמה האסורה באכילה משום שהיא \u0003טמאה,\u0004 שכן איסור אכילת בהמה טמאה אינו אלא \u0003איסור לאו,\u0004 שאיסור קל הוא, שעונשו מלקות. מה שאין כן איסור אכילת \u0003קדשים,\u0004 שהריהו \u0003איסור\u0004 חמור, שעונשו \u0003כרת, מי\u0004 \u0005[האם]\u0006 גם כן \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שחל איסור","גיד הנשה על בהמת המוקדשים? ומציעים הסבר אחר: \u0003אלא, הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005]\u0006 אין אנו עוסקים בבהמה שהיא מוקדשת, \u0003אלא\u0004 \u0003ב\u0004\u0003בהמת חולין, ואולם בזו ה\u0004\u0003מבכרת\u0004 (הממליטה לראשונה) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולענין דין איסור גיד הנשה בעובר שיצא ממנה, שכן רק \u0003ב\u0004\u0003יציאתו מ\u0004\u0003רחם\u0004 אמו הריהו \u0003קדוש\u0004 בקדושת בכור. והשמיעתנו משנתנו שאף שאין איסור גיד הנשה נוהג בשאר המוקדשים, מכל מקום יש מוקדשים שנוהג בהם איסור גיד הנשה, כבכור. ומוסיפים:","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 הסבר אחר\u0005]:\u0006 משנתנו אמנם עוסקת \u0003ב\u0004\u0003ולדות קדשים,\u0004 ובאשר לשאלה שנשאלה כי איסור מוקדשים קודם לאיסור גיד הנשה, ולכך אין מקום לאיסור גיד הנשה לחול — סבור התנא של משנתנו בדינם של ולדות קדשים כי הם מתקדשים \u0003בהווייתן\u0004 (בהתהוותם), בעת שהם יצורים לעצמם, שרק בשעת יציאתם ממעי אמם \u0003הן\u0004 נעשים \u0003קדושים.\u0004 ולכך נוהג בהם איסור גיד \u0003הנשה שכן הוא קודם לאיסור קדושתם, שכן חל עוד בהיותם במעי אמם (ולשיטה הסבורה כי אין איסור גיד הנשה נוהג בשליל\u0004 — הרי \u0003שני האיסורים באים כאחד).\u0004","אחר שנתברר טעם הדין השנוי במשנתנו באיסור גיד הנשה במוקדשים, דנים באלו קדשים אמורים הדברים. \u0003אמר ר' חייא בר יוסף: לא שנו\u0004 במשנתנו שנוהג איסור גיד הנשה \u0003אלא\u0004 דווקא ב\u0003קדשים הנאכלין\u0004 (כחטאת, ואשם, ושלמים), \u0003אבל קדשים שאינן נאכלין\u0004 (כקרבן עולה) — \u0003אין איסור גיד נוהג בהן. ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003אחד\u0004 (בין) \u0003קדשים הנאכלין, ואחד\u0004 (ובין) \u0003קדשים שאין נאכלין\u0004 — \u0003איסור גיד\u0004 \u0003נוהג בהן.\u0004","\u0003אמר רב פפא\u0004 בהסבר דברי חכמים אלה: \u0003ולא פליגי\u0004 \u0005[ולא נחלקו],\u0006 ר' חייא בר יוסף ור' יוחנן בעיקר הדין, שהכל סבורים כי נוהג איסור אכילת גיד הנשה אף בקדשים שאינם נאכלים. ולכך \u0003כאן\u0004 שאמר ר' יוחנן את דבריו, בא רק להוסיף ולומר כי נוהג איסור זה אף לענין \u0003להלקותו\u0004 את האוכל גיד הנשה של קרבן עולה. וכמו כן, \u0003כאן\u0004 שאמר ר' חייא בר יוסף שאין איסור גיד הנשה נוהג בקדשים שאינם נאכלים, בא רק להשמיענו שאין איסור גיד הנשה נוהג לענין \u0003להעלותו\u0004 (להקריבו) על המזבח. שאין אכילת מזבח נחשבת כאיסור אכילת גיד הנשה, והריהו מוקרב על גבי המזבח.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0005שכך\u0006 \u0003אמר רב פפא\u0004 בלשון אחרת: \u0003ולא פליגי\u0004 \u0005[ולא נחלקו]\u0006 ר' חייא בר יוסף ור' יוחנן בעיקר הדין, שהכל סבורים כי נוהג איסור אכילת גיד הנשה אף בקדשים שאינם נאכלים. ולכך \u0003כאן\u0004 שאמר \u0003ר' חייא בר יוסף שאין איסור גיד הנשה נוהג בקדשים שאינם נאכלים\u0004 — הרי זה לענין \u0003לחלצו\u0004 (להוציאו) את גיד הנשה מירך בהמת הקרבן, לפני הקרבתה על גבי המזבח. והשמיענו שאין איסור גיד הנשה נוהג בקדשים שאינם נאכלים, ולכך אין נדרשים להוציא את גיד הנשה לפני ההקרבה. \u0003ו\u0004כן \u0003כאן\u0004 שאמר ר' יוחנן שנוהג \u0003גיד הנשה אף בקדשים שאינם נאכלים\u0004 — הרי זה לענין \u0003להעלותו\u0004 על גבי המזבח את גיד הנשה כשלעצמו (אם הוצא מן הירך). והשמיענו שלענין זה נוהג איסור גיד הנשה, ואין להקריבו על גבי המזבח כשלעצמו. ואילו","\u0003רב נחמן בר יצחק אמר\u0004 כי ר' חייא בר יוסף ור' יוחנן בדין \u0003להעלותו\u0004 על גבי המזבח את גיד הנשה הנמצא בתוך הירך \u0003פליגי\u0004 \u0005[חלוקים].\u0006 ומנמק רב נחמן בר יצחק את דבריו: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב בדין העולה \u0003\"והקטיר הכהן את הכל המזבחה\"\u0004 (ויקרא א, ט), ובאה הלשון המכלילה \"הכל\" \u0003לרבות\u0004 להקרבה על גבי המזבח אף את \u0003העצמות והגידין והקרנים והטלפים\u0004 שבקרבן.","\u0003יכול\u0004 כך הוא הדין \u0003אפילו\u0004 בעצמות וגידים וקרניים וטלפיים שכבר \u0003פרשו\u0004 מגוף הקרבן, שיעלו על המזבח כשלעצמם? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"ועשית עולותיך הבשר והדם\u0004 על מזבח ה' אלהיך\" (דברים יב, כז) — שאין מקריבים על המזבח אלא את בשר הקרבן ודמו. וממשיכים לדון:","\u0003אי\u0004 \u0005[אם]\u0006 כדברי דרשה זו שאין מקריבים אלא את \u0003בשר\u0004 הקרבן \u0003ודם,\u0004 מעתה \u0003יכול\u0004 יהא הדין שהמקריב צריך \u0003ש\u0004\u0003יחלוץ\u0004 (יוציא) מגוף הקרבן \u0003גידים ועצמות\u0004 שיש בו, \u0003ו\u0004לא \u0003יעלה\u0004 אלא \u0003בשר\u0004 ודם בלבד \u0003לגבי מזבח?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"והקטיר הכהן את הכל המזבחה\"\u0004 כי מקריבים אף את העצמות והגידים והקרניים והטלפיים שבגוף הקרבן. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב שתי דרשות אלה, הנראות כסותרות זו את זו? כל דרשה עניינה באופן אחר: אם העצמות וגידים וקרניים וטלפיים עדיין \u0003מחוברין\u0004 לגוף הקרבן — \u0003יעלו\u0004 על גבי המזבח. ואם \u0003פרשו\u0004 מגוף הקרבן, \u0003אפילו\u0004 כשהו עלו למזבח והינם עתה \u0003בראשו של מזבח\u0004 — \u0003ירדו\u0004 מן המזבח, ולא יוקרבו עליו.","עד כאן דברי הברייתא, \u0003ו\u0004יש לברר: \u0003מאן\u0004 \u0005[מי]\u0006 הוא ה\u0003תנא\u0004 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 דין זה בעצמות וגידים וקרניים וטלפיים ש\u0003פרשו\u0004 מגוף הקרבן, שאף אם עלו למזבח דינם ש\u0003ירדו?\u0004 הלא שיטת \u0003רבי היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב בקרבן העולה \u0003\"והקטיר הכהן את הכל\u0004 המזבחה\" — באה לשון \"הכל\" \u0003לרבות\u0004 להקרבה אף את \u0003העצמות והגידים והקרנים והטלפים, ואפילו פרשו\u0004 מגוף הקרבן, הריהם קרבים כשלעצמם.","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003מה אני מקיים\u0004 (באיזה אופן יש להעמיד) את הכתוב \u0003\"ועשית עולותיך הבשר והדם\"? ב\u0004חלקי הקרבן ה\u0003פוקעין\u0004 (מתפקעים על ידי האש) ונושרים אל מחוץ למזבח. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את דרשות הכתובים הנראות כסותרות זו את זו? אם היו אלה \u0003עיכולי בשר\u0004 הקרבן שפקעו מעל המזבח — \u0003אתה מחזיר\u0004 אותם אל המזבח. \u0003ואי\u0004 (ואין) \u0003אתה מחזיר עיכולי גידים ועצמות\u0004 קרניים וטלפיים שפקעו ונשרו מעל המזבח. אלה דברי חכמים.","ואילו \u0003רבי אומר: כתוב אחד אומר \"והקטיר הכהן את הכל\u0004 המזבחה\" — הרי זה הכתוב \u0003ריבה, וכתוב אחד אומר ועשית \"עולותיך הבשר והדם\"\u0004 — הרי זה הכתוב \u0003מיעט, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את דרשות הכתובים הנראות כסותרות זו את זו? אם היו אלה \u0003מחוברין\u0004 עדיין לגוף הקרבן — \u0003יעלו,\u0004 ואולם אם \u0003פרשו\u0004 מגוף הקרבן — \u0003אפילו\u0004 קרה והם הינם עתה \u0003בראשו של מזבח, ירדו. ו\u0004בבירור שיטותיהם של חכמים ורבי","יש לומר כי \u0003רבנן\u0004 \u0005[חכמים]\u0006 אינם מיישבים כ\u0003רבי\u0004 — שכן לגבי גידים ועצמות וקרניים וטלפיים \u0003ה\u0004\u0003מחוברין לא איצטריך קרא לרבויי\u0004 \u0005[לא נצרך הכתוב לרבות],\u0006 שהריהם קרבים למזבח, \u0003מידי דהוה\u0004 \u0005[כדבר שהוא]\u0006 \u0003ראשה של העולה,\u0004 שהריהו קרב בשלמותו (כנאמר וערכו בני אהרן הכהנים את הנתחים את הראש ואת הפדר על העצים אשר על המזבח\". ויקרא א, ח), אף שיש בו עצמות רבות. ואולם \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006 לרבות — הרי זה \u0003ל\u0004מקרה שבו \u0003פרשו\u0004 מגוף הקרבן.","\u0003ו\u0004אילו \u0003רבי\u0004 שלדעתו בא הכתוב לרבות את המחוברים, סבור כי אכן ל\u0003מחוברין דהיתירא\u0004 \u0005[של היתר],\u0006"],["אכן \u0003לא איצטריך קרא לרבויי\u0004 \u0005[לא נצרך הכתוב לרבות],\u0006 וכדברי חכמים. ואולם \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006 לרבות, הרי זה \u0003ל\u0004ענין הקרבתו של \u0003גיד הנשה במחובר,\u0004 שקרב על המזבח. ואולם אם פרש, אין הוא קרב.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים על דבריו אלה של רבי, כי אין מקום לרבות את גיד הנשה (אף שהוא מחובר לגוף ירך הבהמה) להקרבה. שכן נאמר בדינם של הקרבנות \u0003\"ממשקה ישראל\"\u0004 (יחזקאל מה, טו) — שאין דבר ראוי להיות קרב על המזבח אלא \u0003מן המותר\u0004 באכילה \u0003לישראל.\u0004 וכיון שגיד הנשה אסור באכילה לישראל, מעתה אף להקרבה על המזבח הריהו פסול.","\u0003ורבי\u0004 משיב על דברי חכמים אלה, שאין גיד הנשה (המחובר לירך) נפסל להקרבה משום \"ממשקה ישראל\", \u0003מידי דהוה\u0004 \u0005[כדבר שהוא]\u0006 בדינם של ה\u0003חלב ודם,\u0004 שאסורים למאכל ישראל, ובכל זאת הריהם קרבים על המזבח. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים על דברי רבי, שאין להשוות את הדברים — שכן דברים ש\u0003מצותן בכך,\u0004 כחלב ודם, שהתורה ציותה שיש להקריבם \u0003שאני\u0004 \u0005[שונה].\u0006 הוא מדינו של גיד הנשה, שלא נאמר ציווי להקריבו. ונמצא איפוא כי ר' חייא בר יוסף ור' יוחנן אכן חלוקים ביניהם (ושלא כדעת רב פפא), ומחלוקתם היא כמחלוקתם של תנאים אלה. שדעת ר' חייא בר יוסף כדעת רבי, ודעת ר' יוחנן כדעת חכמים.","ועוד בדין הקרבת גיד הנשה בקרבנות שאינם נאכלים (עולה), \u0003אמר רב הונא:\u0004 אין \u0003גיד הנשה של עולה\u0004 (קרב) על המזבח, אלא המקריב את העולה \u0003חולצו\u0004 לגיד הנשה מן הירך לפני ההקרבה, ומטילו \u0003לתפוח\u0004 (ערימה עגולה של אפר הנתונה בראש המזבח). \u0003אמר רב חסדא\u0004 לרב הונא בתמיהה על דבריו: \u0003מרי דיכי\u0004 \u0005[אדון\u0006 הלכה \u0005זו,\u0006 בעל שמועה זו\u0005],\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בתורה באיסור גיד הנשה \u0003\"על כן לא יאכל המזבח\u0004 את גיד הנשה\"? שנלמד מכאן איסור זה אף בקרבנות העולים על המזבח, והרי \u0003\"על כן לא יאכלו בני ישראל\u0004 את גיד הנשה אשר על כף הירך עד היום הזה\" (בראשית לב, לב) \u0003כתיב\u0004 \u0005[נאמר].\u0006 הרי שלא נאמר איסור זה אלא לענין אכילת אדם ולא לענין אכילת מזבח.","\u0003ורב הונא\u0004 הסבור שאף מזבח אסור באכילת גיד הנשה, מה טעם אמר כן? שכן נאמר בדין הקרבנות שיהיו \u0003\"ממשקה ישראל\"\u0004 (יחזקאל מה, טו) — שאין הם באים אלא \u0003מן\u0004 הדבר \u0003המותר\u0004 באכילה \u0003לישראל,\u0004 וגיד הנשה מאחר שאסור לישראל, אף למזבח הריהו פסול.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב הונא ממה ששנינו בברייתא כי \u0003גיד הנשה\u0004 (האסור באכילה) \u0003של\u0004 קרבן \u0003שלמים\u0004 (שמצוותו באכילה), מה יעשה בו? מוציאו מן הירך, ו\u0003מכבדו\u0004 (מטאטא אותו) \u0003לאמה\u0004 (תעלת מים העוברת בעזרה שבמקדש, ודרכה היו מתפנות הפסולת ושאריות אל מחוץ למקדש), \u0003ו\u0004אילו גיד הנשה \u0003של\u0004 קרבן \u0003עולה\u0004 — \u0003מעלהו\u0004 להקרבה על גבי המזבח. ובפירוש דברי הברייתא האומרת בגיד הנשה של עולה \"מעלהו\", \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003מעלהו ומקטירו,\u0004 שלא כדברי רב הונא! ודוחים:","\u0003לא,\u0004 כוונת הדברים היא ש\u0003מעלהו\u0004 את קרבן העולה כפי שהוא, \u0003ו\u0004לאחר מכן הריהו \u0003חולצו\u0004 לגיד הנשה מתוך הירך, בראש המזבח. ותוהים על הסבר זה: \u0003ומאחר ש\u0004לאחר מכן הריהו \u0003חולצו\u0004 לגיד הנשה, ואינו מקריבו, אם כן \u0003למה\u0004 הריהו \u0003מעלהו\u0004 בתחילה, ומדוע לא יחתוך את הירך ויוציא את הגיד מתוכה לפני העלאתה למזבח? ומשיבים: הטעם שמעלים בתחילה את הירך בשלמותה, \u0003משום שנאמר\u0004 כנגד המביאים למקדש קרבנות פגומים ופחותים: \u0003\"הקריבהו נא לפחתך\u0004 הירצך או הישא פניך\" (מלאכי א, ח). ואף ירך חתוכה הריהי כדבר הפחות ופגום, שאין זו כדרך כבוד הראויה להביאה לפני מלכים.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמותו],\u0006 כשיטתו של \u0003רב הונא: גיד הנשה של\u0004 קרבן \u0003שלמים\u0004 — \u0003מכבדו לאמה\u0004 העוברת בעזרה, \u0003ו\u0004גיד הנשה \u0003של\u0004 קרבן \u0003עולה\u0004 — \u0003חולצו\u0004 מתוך הירך של הקרבן, ונותנו \u0003לתפוח.\u0004","מתוך שהוזכר למעלה התפוח שבראש המזבח, מביאים עוד בעניינו, שכן \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה במסכת תמיד\u0005]:\u0006 \u0003תפוח היה באמצע המזבח, פעמים היה עליו\u0004 אפר ששיעורו \u0003כשלש מאות כור. אמר\u0004 על כך \u0003רבא:\u0004 לשון זו הריהי לשון \u0003גוזמא\u0004 (הפלגה מרובה). ועניינה לומר שהיתה גדולה ביותר, ואולם מעולם לא היה בתפוח שיעור שכזה.","וכן על זו ששנינו עוד במסכת תמיד כי לפני שחיטתו, \u0003השקו את\u0004 קרבן \u0003התמיד\u0004 מים \u0003בכוס של זהב,\u0004 כדי להקל בכך על פשיטת עורו לאחר השחיטה, \u0003אמר רבא:\u0004 הרי זו לשון \u0003גוזמא,\u0004 שלא היתה זו כוס של זהב.","ועוד בענין שימוש לשון שאינו מכוון כדיוקו, \u0003אמר ר' אמי:\u0004 יש ו\u0003דברה תורה לשון הואי\u0004 (גוזמה), וכמו כן יש ו\u0003דברו נביאים לשון הואי,\u0004 וכיוצא בזה יש ו\u0003דברו חכמים לשון הואי.\u0004 ומפרטים: \u0003דברו חכמים לשון הואי\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו\u0006 מקודם, בתפוח ובכוס של זהב\u0005],\u0006","\u0003דברה תורה לשון הואי\u0004 — שכן נאמר (\"שמע ישראל אתה עובר היום את הירדן לבוא לרשת גוים גדולים ועצומים ממך \u0003ערים גדולות ובצורות בשמים\"\u0004 (דברים ט, א). והרי זו לשון גוזמה. וכן \u0003דברו נביאים לשון הואי\u0004 — כגון זה שנאמר בתיאור המלכת שלמה המלך \"ויעלו כל העם אחריו והעם מחללים בחלילים ושמחים שמחה גדולה \u0003ותבקע הארץ לקולם\"\u0004 (מלכים א א, מ). וודאי לא נבקעה הארץ למשמע קול זה.","ועוד בענין זה, \u0003אמר ר' יצחק בר נחמני אמר שמואל: בשלשה מקומות דברו חכמים לשון הואי, אלו הן: תפוח, גפן, ופרוכת.\u0004 ומפרטים: \u0003תפוח\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו\u0006 מקודם\u0005],\u0006","\u0003גפן\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 כי צורה כעין \u0003גפן של זהב היתה עומדת\u0004 באולם המקדש \u0003על פתחו של היכל, ומודלה\u0004 (מורמת) היתה \u0003על גבי כלונסות\u0004 (מוטות), \u0003וכל מי שהיה מתנדב\u0004 (נודב) למקדש זהב בצורת עלה או בשיעור גדול יותר של \u0003גרגיר\u0004 (ענבה יחידה), \u0003או\u0004 שיעור גדול יותר כעין \u0003אשכול\u0004 ענבים, היה \u0003מביא\u0004 למקדש \u0003ו\u0004היה \u0003תולה\u0004 אותה תרומה \u0003בה,\u0004 בצורת גפן זו. ועל כך \u0003אמר ר' אלעזר בר' צדוק: מעשה היה\u0004 במקדש, שכה גדולה היתה גפן זו, עד שהיה צורך ש\u0003נמנו עליה שלש מאות כהנים\u0004 כדי \u0003לפנותה\u0004 ממקומה למקום אחר, והרי זו לשון גוזמה.","\u0003פרוכת\u0004 מה עניינה? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו],\u0006 \u0003רבן שמעון בן גמליאל אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון הסגן\u0004 (סגן הכהנים): ה\u0003פרוכת\u0004 שבמקדש היה \u0003עוביה\u0004 כשיעור \u0003טפח, ועל שבעים ושנים נירים\u0004 (נימים, חוטי שתי) היתה \u0003נארגת, ועל כל נימה ונימה\u0004 מאותן שבעים ושנים נימים היו \u0003עשרים וארבעה חוטין\u0004 לעשותה. שכן היתה הפרוכת עשויה מארבעה מינים: תכלת, ארגמן, תולעת שני, ושש, וחוטו של כל אחד מארבעת אלה היה כפול ששה חוטים. ומידותיה של הפרוכת: \u0003ארכה\u0004 — \u0003ארבעים באמה,\u0004 כגובהו של פתח האולם. \u0003ורחבה\u0004 — \u0003עשרים באמה,\u0004 כרוחבו של פתח האולם. \u0003ומשמונים ושתי רבוא\u0004 (שמונה מאות ועשרים אלף) דינרים היתה הפרוכת \u0003נעשת, ושתים\u0004 פרוכות חדשות היו \u0003עושים ב\u0004כל \u0003שנה\u0004 ושנה. \u0003ו\u0004כה כבדה היתה הפרוכת עד שהוצרכו ל\u0003שלש מאות כהנים\u0004 לשאת אותה כשהיו \u0003מטבילין אותה.\u0004 ואף זו לשון גוזמה הבאה להורות שהיתה כבדה מאד.","שנינו במשנתנו כי נוהג דין גיד הנשה \u0003בירך של ימין ובירך של שמאל.\u0004 ומסבירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004דעת \u0003ר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 איסור \u0003גיד הנשה\u0004 \u0003אינו נוהג אלא ב\u0004ירך \u0003אחת\u0004 בלבד משתי ירכותיה של הבהמה, \u0003והדעת מכרעת\u0004 כי \u0003את\u0004 גיד הנשה \u0003של\u0004 ירך צד \u0003ימין\u0004 הוא שאסרה התורה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 מה כוונתו: האם \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 \u0003לר' יהודה\u0004 שכך הוא הדין, \u0003ומאי\u0004 \u0005[ומה]\u0006 היא \u0003דעת\u0004 זו המכרעת? \u0003דעת תורה, או דלמא ספוקי מספקא ליה\u0004 \u0005[או שמא מסופק לו]\u0006 ר' יהודה בדבר, \u0003ומאי\u0004 \u0005[ומה]\u0006 היא \u0003דעת\u0004 זו המכרעת? \u0003דעת נוטה\u0004 מן הסברה?","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו כי \u0003העצמות והגידים ו\u0004הבשר \u0003הנותר\u0004 מקרבן פסח \u0003ישרפו ל\u0004יום \u0003ששה עשר\u0004 בניסן (למחרת יום טוב ראשון של פסח), \u0003והוינן\u0004 \u0005[והתקשינו]\u0006 \u0003בה,\u0004 בלשונה של ברייתא זו: \u0003הני גידי מאי עבידתייהו\u0004 \u0005[אלה הגידים\u0006 הנזכרים בה, \u0005מה עניינם],\u0006 שהרי \u0003אי\u0004 \u0005[אם]\u0006 המדובר ב\u0003גידי בשר,\u0004 הגידים הרכים המצויים בבשר הבהמה — \u0003ליכלינהו\u0004 \u0005[שיאכלם],\u0006 שהרי הם בני אכילה, ובכלל מצות אכילת קרבן הפסח הם. \u0003ואי דאייתור\u0004 \u0005[ואם\u0006 המדובר שקרה ולא אכלם \u0005והם נותרו]\u0006 — \u0003היינו\u0004 \u0005[זהו]\u0006 השנוי בברייתא זו \u0003\"נותר\"! אלא\u0004 יש לומר כי המדובר ב\u0003גידי צואר\u0004 הקשים כעצמות, ודרכם של בני אדם שלא לאוכלם בכלל. ויש להקשות: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003בשר נינהו\u0004 \u0005[הם]\u0006 — \u0003לישדינהו\u0004 \u0005[שיזרקם]\u0006 לאשפה, ואין צורך להמתין ליום ט\"ז בניסן ולשורפם אז!","\u0003ואמר רב חסדא: לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 זו להישנות \u0003אלא ל\u0004ענין \u0003גיד הנשה, ואליבא\u0004 \u0005[ולשיטתו]\u0006 של \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 שאיסור גיד הנשה \u0003אינו נוהג אלא ב\u0004ירך \u0003אחת\u0004 בלבד.","ומכאן נאמר: \u0003אי אמרת בשלמא ספוקי מספקא ליה\u0004 \u0005[נוח הוא אם אומר אתה\u0006 כי \u0005מסופק לו]\u0006 לר' יהודה אם איסור גיד הנשה נוהג בירך ימין או בירך שמאל — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן\u0005]\u0006 מדוע הגידים של ירך ימין ושל ירך שמאל, אינם נאכלים (מפני הספק שמדין התורה), ונשרפים שניהם למחרת יום ראשון של פסח (מפני הספק איזהו הגיד הנאכל, ולכן עתה הוא נותר החייב בשריפה). \u0003ואלא אי אמרת מיפשט פשיטא ליה\u0004 \u0005[אם אומר אתה\u0006 כי \u0005פשוט לו,\u0006 לר' יהודה שאיסור גיד הנשה נוהג בירך של ימין\u0005],\u0006 אם כך את הגיד \u0003דהיתירא\u0004 \u0005[של היתר],\u0006 שאין בו איסור גיד הנשה, זה שבירך שמאל — \u0003ליכליה\u0004 \u0005[שיאכלנו],\u0006 כשאר קרבן הפסח, ואילו הגיד שבירך ימין שהוא \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 — אין צורך לשרפו למחרת היום, אלא \u0003לשדייה\u0004 \u0005[שיזרקנו]!\u0006","\u0003אמר רב איקא בר חנינא\u0004 בדחיית הראיה: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי אכן \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו,\u0006 לר' יהודה\u0005]\u0006 שאיסור גיד הנשה נוהג בירך של ימין, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן\u0006 בברייתא זו ששנינו בה ששני הגידים נשרפים, \u0005במה אנו עוסקים]\u0006 — \u0003כשהוכרו\u0004 בתחילה שני הגידים, של ירך ימין ושל ירך שמאל, והאחד נועד לאכילה והשני נועד להיזרק, \u0003ו\u0004אולם \u0003לבסוף\u0004 (לאחר מכן) \u0003נתערבו\u0004 זה עם זה, ואין יודעים מיהו הנאכל ומיהו הנזרק. ומפני הספק שניהם אינם נאכלים ו\u0003נשרפים למחרת היום.\u0004"],["וכן \u0003רב אשי אמר\u0004 כי אין להביא מברייתא זו ראיה ביחס לדעת ר' יהודה באיסור גיד הנשה, שכן \u0003לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 הברייתא להשמיענו \u0003אלא ל\u0004ענין \u0003שמנו\u0004 של גיד הנשה, שנשרף למחרת יום ראשון של פסח. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שמנו\u0004 של גיד הנשה \u0003מותר\u0004 מן התורה, \u0003ו\u0004אולם \u0003ישראל קדושים נהגו בו איסור.\u0004 ולכך אין אוכלים אותו בכלל קרבן פסח, אבל שורפים אותו למחרת היום כדין חלקי קרבן פסח שדינם באכילה ולא נאכלו. וכן","\u0003רבינא אמר\u0004 כי אין להביא מברייתא זו ראיה באשר לדעת ר' יהודה באיסור גיד הנשה, שכן אין השנוי בברייתא \"והגידים\" אמור בגיד הנשה עצמו, ו\u0003לא נצרכא\u0004 \u0005[ולא נצרכה]\u0006 הברייתא להשמיענו \u0003אלא ל\u0004ענין זה שאמר \u0003רב יהודה אמר שמואל,\u0004 שכן \u0003אמר רב יהודה אמר שמואל\u0004 כי \u0003שני גידין הן\u0004 הכלולים בגיד הנשה, ודינם של אלה שונה זה מזה. שכן הגיד \u0003ה\u0004\u0003פנימי\u0004 ה\u0003סמוך לעצם\u0004 — הריהו \u0003אסור\u0004 מן התורה, \u0003וחייבין\u0004 מלקות \u0003עליו\u0004 (על אכילתו). ואילו הגיד ה\u0003חיצון\u0004 ה\u0003סמוך לבשר\u0004 — אמנם \u0003אסור\u0004 באכילה, ואולם אין איסורו אלא מדברי חכמים, \u0003ו\u0004לכך \u0003אין חייבין עליו\u0004 מלקות. ובאותו גיד חיצון עוסקת הברייתא, ללמדנו שאינו נאכל עם הפסח, אלא נשרף למחרת היום כשאר חלקי הקרבן שהיו אמורים להיאכל ולא נאכלו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה שהועלתה באשר לדעת ר' יהודה, ממה ששנינו: מי ש\u0003אכל מ\u0004גיד הנשה ה\u0003זה\u0004 שבירך שבצד ימין כשיעור אכילה שהוא \u0003כזית, ו\u0004כן אכל אף \u0003מ\u0004גיד הנשה ה\u0003זה\u0004 שבירך שמאל גם כן כשיעור \u0003כזית\u0004 — הריהו \u0003סופג\u0004 (לוקה מלקות) שמניינן \u0003שמונים,\u0004 שכן \u0003העובר על מצות לא תעשה שמן התורה לוקים ארבעים מלקות. וזה\u0004 עבר שתי פעמים על הדבר האסור מן התורה, באכילת גיד הנשה של ירך ימין ובאכילת גיד הנשה של ירך שמאל. ואילו \u0003ר' יהודה אומר: אינו סופג אלא ארבעים\u0004 מלקות בלבד. ויש לדון בדברי ר' יהודה אלה:","\u0003אי אמרת בשלמא מיפשט פשיטא ליה\u0004 \u0005[זה נוח, אם אתה אומר\u0006 ש\u0005פשוט לו]\u0006 לר' יהודה שאיסור גיד הנשה מן \u0003התורה הוא דווקא בזה של ירך ימין\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן\u0005]\u0006 מדוע לוקה ארבעים מלקות בלבד (רק על אכילת גיד הנשה של ירך ימין). \u0003אלא אי אמרת ספוקי מספקא ליה\u0004 \u0005[אם אתה אומר\u0006 ש\u0005מסופק לו\u0006 לר' יהודה אם איסור גיד הנשה מן \u0003התורה הוא דווקא בזה של ירך ימין\u0004 — מדוע בכלל לוקה? והרי ההתראה שמתרים בו העדים בעובר עבירה (שבלעדיה אין הוא לוקה על עבירתו) \u0003הויא לה\u0004 \u0005[הריהי]\u0006 \u0003התראת ספק,\u0004 שכן אין העדים המתרים יכולים לומר לו בוודאות על כל גיד וגיד שאכילתו של זה אסורה מן התורה, \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003התראת ספק לא שמה\u0004 (אינה נחשבת) \u0003התראה! דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של מי שספק הוא מיהו אביו (כגון שהתגרשה אמו מבעלה הראשון וחזרה ונישאה לאחר בתוך חדשיים, ונולד לה בן לאחר שבעה חדשים מנישואיה השניים. ואין זה ברור אם הילד שנולד הוא בנו של בעלה הראשון ונולד לאחר תשעה חדשי הריון. או שמא הוא בנו של בעלה השני, ונולד לאחר שבעה חדשי הריון). ועמד בן זה ו","\u0003הכה את זה\u0004 (בעלה הראשון של אמו) \u0003וחזר והכה את זה\u0004 (בעלה השני של אמו). או שעמד ו\u0003קלל את זה, וחזר וקלל את זה.\u0004 וכן אם \u0003הכה\u0004 את \u0003שניהם בבת אחת, או שקלל\u0004 את \u0003שניהם בבת אחת\u0004 — בכל המקרים הללו הריהו \u0003חייב\u0004 מיתה, שהרי ברור שהיכה או קילל את אביו (שהוא אחד מבין שני האנשים שהוכו או קוללו על ידו). ואילו \u0003ר' יהודה אומר\u0004 כי בהכאה או בקללה של שניהם \u0003בבת אחת\u0004 — הריהו \u0003חייב\u0004 מיתה, ומשום שההתראה שהתרו בו העדים לבל יכה או יקלל את אביו הריהי התראת ודאי (כי בוודאי אחד משני האנשים הללו שהוכו הינו אביו). ואולם אם היכה או קילל את שניהם \u0003בזה אחר זה\u0004 — הריהו \u0003פטור.\u0004 משום שבכל פעם שהתרו בו העדים לבל יכה או יקלל את אביו, לא היתה זו התראת ודאי אלא מן הספק בלבד. הרי איפוא שלדעת ר' יהודה אין התראת ספק נחשבת כהתראה להעניש על ידה!","ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא סבר לה כאידך תנא\u0004 \u0005[הריהו סבור כ\u0006דעתו של \u0005תנא\u0006 אחר\u0005]\u0006 בשיטתו של \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 כי \u0003התראת ספק\u0004 — \u0003שמה התראה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב בקרבן פסח \"ו \u0003לא תותירו ממנו עד בקר\u0004 והנותר ממנו עד בקר באש תשרופו\" (שמות יב, י) — \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 (\"באש תשרופו\") \u0003אחר\u0004 מצות \u0003לא תעשה\u0004 (\"ולא תותירו\"), \u0003לומר שאין לוקין עליו,\u0004 על איסור \"ולא תותירו\" שעברו עליו, אלו \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' יעקב אומר: לא מן השם\u0004 (הענין, הטעם) של מצות עשה הבאה לאחר מצות לא תעשה (\"לאו הניתק לעשה\") \u0003הוא זה\u0004 שאין לוקים על \"ולא תותירו\", \u0003אלא משום דהוה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה, ו\u0004כלל הוא \u0003ש\u0004\u0003כל לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו.\u0004 והעולה מדברי ברייתא זו כי אילו לאו \"ולא תותירו\" לא היה לאו הניתק לעשה, היו לוקים עליו, אף שבשעה שעבר על לאו זה היתה ההתראה שהתרו בו העדים, התראת ספק, שכן אין העדים יודעים בוודאות שהוא יעבור על איסור זה, שכן אפשר שיאכל את קרבן הפסח אחר כך ולפני עלות השחר. משמע שיש דעה הסבורה כי שיטת ר' יהודה היא שהתראת ספק שמה התראה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה שהועלתה ביחס לדעת ר' יהודה, ממה ששנינו בדינו של זה ש\u0003אכל שני גידין\u0004 (גידי הנשה) \u0003משתי ירכות\u0004 הבאות \u0003משתי בהמות\u0004 שונות — הרי זה \u0003סופג\u0004 (לוקה) \u0003שמונים\u0004 מלקות, שהן ארבעים מלקות על אכילת גיד זה וארבעים מלקות על אכילת גיד זה. ואילו \u0003ר' יהודה אומר\u0004 ש\u0003אינו סופג אלא ארבעים\u0004 מלקות בלבד.","ומדייקים בדבריו: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שהוא\u0006 התנא הראשון בברייתא \u0005אומר]\u0006 שמדובר במי שאוכל שני גידי הנשה \u0003\"משתי ירכות משתי בהמות\",\u0004 משמע שמדובר בשני גידי הנשה הבאים מירך ימנית דווקא. שהרי אם בגידים הבאים מירך ימין ושמאל, אין זה משנה אם הם באים מבהמה אחת או משתי בהמות. ומעתה נוכל איפוא לסכם כי \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 כי איסור גיד הנשה מן התורה הוא דווקא בשל ירך ימין, וכאן שמדובר בגידים הבאים משתי ירכות של ימין, \u0003דתרוייהו לאיסורא\u0004 \u0005[ששתיהן לאיסור],\u0006 ולכך לדעת התנא הראשון בברייתא לוקים על אכילתם שמונים מלקות. \u0003ו\u0004אילו \u0003לר' יהודה איצטריך\u0004 \u0005[הוצרך]\u0006 להשמיענו, שאף על פי ששניהם גידים האסורים מן התורה, מכל מקום אין הוא לוקה אלא ארבעים, ומטעם שיוסבר הלאה. ומעתה נאמר כי \u0003שמע מינה\u0004 \u0005[נסיק מכאן]\u0006 כי \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו,\u0006 לר' יהודה\u0005]\u0006 שאיסור גיד הנשה מן התורה הוא דווקא בשל ימין. ומסכמים: אכן \u0003כך\u0004 \u0003שמע מינה\u0004 \u0005[נסיק מכאן].\u0006","\u0003ו\u0004עתה מבררים את הברייתא שהבאנו: \u0003אי פשיטא ליה\u0004 \u0005[אם פשוט לו,\u0006 לר' יהודה\u0005]\u0006 שאיסור גיד הנשה מן התורה הוא דווקא בשל ימין, וכאן שמדובר בשני גידים הבאים כל אחד מירך ימין, \u0003אמאי\u0004 \u0005[מדוע]\u0006 האוכלם אינו \u0003סופג\u0004 אלא \u0003ארבעים\u0004 מלקות, \u0003ותו\u0004 \u0005[ויותר]\u0006 \u0003לא? לילקי\u0004 \u0005[שילקה]\u0006 \u0003שמונים\u0004 מלקות! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בברייתא, \u0005במה אנו עוסקים],\u0006 \u0003כגון\u0004 שבאחד הגידים שאכל יש שיעור כזית, ואילו בגיד השני מדובר \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בו\u0004 שיעור \u0003כזית. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אכלו\u0004 לגיד הנשה, \u0003ואין בו\u0004 שיעור \u0003כזית\u0004 — הרי זה \u0003חייב.\u0004 שאף שאין בו כשיעור אכילה, שהוא כזית, מכל מקום כיון שאכל דבר שלם, הרי זה כאוכל בריה שלימה כל שהיא שחייב באכילה זו. ואילו \u0003ר' יהודה אומר\u0004 שאין חייבים על אכילת גיד הנשה אלא \u0003עד שיהא בו\u0004 שיעור \u0003כזית.\u0004","\u0003וטעמא מאי\u0004 \u0005[וטעם,\u0006 מקור שיטת ר' יהודה שאיסור תורה הוא דווקא בגיד הנשה של ירך ימין \u0005מה\u0006 הוא\u0005]?\u0006 \u0003אמר רבא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באיסור גיד הנשה \u0003\"הירך\"\u0004 (בראשית לב, לב) — \u0003המיומנת שבירך. ו\u0004אילו לדעת","\u0003רבנן\u0004 \u0005[חכמים],\u0006 החולקים על ר' יהודה וסבורים שאיסור גיד הנשה מן התורה הוא בשני הגידים שבשתי הירכות — כתוב זה בא להורות כי אין איסור גיד הנשה מן התורה אלא בגיד \u0003ההוא\u0004 \u0003דפשיט איסוריה בכוליה\u0004 \u0005[שמתפשט איסורו בכל]\u0006 ה\u0003ירך,\u0004 הוא הגיד הפנימי, הגדול ומסתעף עם על שלוחותיו בכל הירך. ו\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט מכלל איסור\u0005]\u0006 את הגיד ה\u0003חיצון\u0004 ש\u0003לא,\u0004 שאין בו איסור מן התורה.","\u0003ו\u0004מביאים עוד הסברים למקור שיטותיהם של ר' יהודה וחכמים בדין איסור גיד הנשה. ש\u0003ר' יהושע בן לוי אמר\u0004 כי מקור שיטתו של ר' יהודה הוא מה ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 בתיאור מאבקו של יעקב במלאך \"ותקע כף ירך יעקב \u0003בהאבקו עמו\"\u0004 (שם כה) — \u0003כאדם\u0004 הנאבק עם חבירו על מנת להפילו ארצה, \u0003ש\u0004עומד כנגדו, ושולח את ידו הימנית ו\u0003חובק את חבירו, וידו מגעת\u0004 עד \u0003לכף ימינו של חבירו.\u0004 ומכאן שאיסור גיד הנשה שנקבע בעקבות מאבק זה, אף הוא אמור בגיד הנשה של ירך ימין.","\u0003ר' שמואל בר נחמני אמר: כגוי נדמה לו,\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישראל שנטפל\u0004 (הצטרף) \u0003לו גוי\u0004 כשהוא מהלך לו \u0003בדרך\u0004 — צריך לחשוש מפניו, ולכן יהא \u0003טופלו\u0004 (יצרף אותו) \u0003ל\u0004צד \u0003ימינו,\u0004 שהוא צד שמאלו של הגוי. כדי שיוכל הישראל להגן על עצמו ביתר יעילות אם הגוי יתקפנו. וכן נהג יעקב אבינו במלאך זה, שנראה לו כגוי, ולכך ירכו הימנית של יעקב היא זו שנפגעה במאבקו עם המלאך. ומכאן לאיסור גיד הנשה מן התורה שהוא דווקא בירך ימין.","ואילו \u0003רב שמואל בר אחא\u0004 ביושבו כתלמיד \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא בר עולא אמר: כתלמיד חכם נדמה לו\u0004 מלאך זה ליעקב. ולכך היה יעקב מהלך לשמאלו של מלאך זה, שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003המהלך לימין רבו\u0004 — \u0003הרי זה בור.\u0004 ולכך דווקא ירך ימין של יעקב היא שנפגעה. ומכאן לאיסור גיד הנשה מן התורה שהוא בירך ימין.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' יהודה וסבורים שאף גיד הנשה של ירך שמאל אסור מן התורה, לדעתם המלאך שפגע ביעקב לא היה לצידו, אלא \u0003מאחוריה אתא\u0004 \u0005[מאחוריו בא],\u0006 \u0003ונשייה בתרוייהו\u0004 \u0005[ופגע בו בשניהם,\u0006 בשתי הירכות\u0005].\u0006","\u0005ושואלים:\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים כי המלאך תקף את יעקב מאחוריו, לפי זה \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"בהאבקו עמו\" מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]?\u0006 ומשיבים: \u0003מבעי ליה לכאידך\u0004 \u0005[נצרך לו\u0006 כתוב זה \u0005לכמו\u0006 השמועה \u0005האחרת]\u0006 של \u0003ר' יהושע בן לוי\u0004 בפירוש הכתוב הזה, שכן \u0003אמר ר' יהושע בן לוי: מלמד שהעלו\u0004 יעקב והמלאך תוך כדי מאבקם, \u0003אבק מרגלותם עד כסא הכבוד, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"בהאבקו עמו\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בתיאור נקמת ה' באויבים \"בסופה ובשערה דרכו \u0003וענן אבק רגליו\"\u0004 (נחום א, ב).","\u0003ו\u0004מתוך שהובאו שתי מדרשותיו של ר' יהושע בן לוי בענין גיד הנשה, מביאים עוד מדבריו בענין זה. \u0003אמר ר' יהושע בן לוי: למה נקרא שמו גיד הנשה? שנשה\u0004 (יצא) \u0003ממקומו ועלה, וכן הוא אומר: \"נשתה גבורתם היו לנשים\"\u0004 (ירמיהו נא, ל).","ועוד מדרשות חכמים בענין גיד הנשה, \u0003אמר ר' יוסי בר' חנינא מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"דבר שלח\u0004 ה' \u0003ביעקב ונפל בישראל\"\u0004 (ישעיהו ט, ל)? \u0003\"דבר שלח ביעקב\"\u0004 — \u0003זה\u0004 איסור \u0003גיד הנשה, \"ונפל בישראל\"\u0004 — \u0003שפשט איסורו בכל ישראל. ו\u0004עוד","\u0003אמר ר' יוסי בר' חנינא\u0004 בענין איסור גיד הנשה: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בתיאור פגישת יוסף ואחיו \"הבא את האנשים הביתה \u0003וטבוח טבח והכן\u0004 כי אתי יאכלו האנשים בצהרים\" (בראשית מג, טז)? \"וטבוח טבח\" — \u0003פרע\u0004 (גלה) \u0003להן\u0004 את \u0003בית השחיטה,\u0004 שידעו שהבהמה נשחטה כראוי, \u0003\"והכן\"\u0004 — \u0003טול\u0004 את \u0003גיד הנשה בפניהם.\u0004 ואומרים: הרי זה \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003גיד הנשה נאסר לבני נח,\u0004 שנאסר לבני יעקב עוד לפני מתן תורה, אף שהיו אז בגדר של בני נח.","מתוך שהובאו למעלה פירושי מקראות שבענין מאבקו של יעקב במלאך, מביאים עוד פירושי מקראות בענין זה. נאמר \u0003\"ויותר יעקב לבדו\u0004 ויאבק איש עמו עד עלות השחר\" (שם כד), ובטעם הדבר שנשאר יעקב לבדו, אחר שהעביר כבר את כל משפחתו את מעבר נחל יבוק, \u0003אמר ר' אלעזר: שנשתייר\u0004 בצד הזה של הנחל \u0003על פכין קטנים\u0004 שלא העבירום לצד השני של הנחל, \u0003מכאן\u0004 למדנו \u0003ל\u0004עניינם של ה\u0003צדיקים שחביב עליהם ממונם יותר מגופם,\u0004 עד שהסתכן יעקב בגופו בשל ממונו. \u0003וכל כך למה? לפי ש\u0004הצדיקים \u0003אין פושטין ידיהן בגזל\u0004 לכן קשה עליהם השגת הממון והם דואגים לו. עוד נאמר באותו כתוב","\u0003\"ויאבק איש עמו עד עלות השחר\"\u0004 — \u0003אמר ר' יצחק: מכאן\u0004 למדנו \u0003ל\u0004עניינו של \u0003תלמיד חכם שלא יצא יחידי בלילה,\u0004 שהרי יעקב יצא יחידי בלילה, וניזוק. \u0003ר' אבא בר כהנא אמר מהכא\u0004 \u0005[מכאן,\u0006 ממקרא זה\u0005]\u0006 יש ראיה לכך:"],["שכן אמרה נעמי לרות אודות בועז \u0003\"הנה הוא זורה את גורן השעורים\u0004 הלילה... עד כלותו לאכול ולשתות. ויהי בשכבו וידעת את המקום אשר ישכב שם\" (רות ג, ב—ד). הרי שלא הלך בועז לביתו אחר שזרה את גורנו, מפני שאין ראוי לתלמיד חכם לצאת יחידי בלילה.","ו\u0003ר' אבהו אמר\u0004 כי יש להביא ראיה לדבר \u0003מהכא\u0004 \u0005[מכאן,\u0006 מהנאמר בעקידת יצחק\u0005]:\u0006 \u0003\"וישכם אברהם בבקר ויחבוש את\u0004 חמורו ויקח את שני נעריו עמו ואת יצחק בנו ויבקע עצי עולה ויקם וילך אל המקום אשר לו האלקים\" (בראשית כב, ג), ולא הקדים ויצא למקום העקידה כבר בלילה. שכן אין זה ראוי לתלמיד חכם לצאת בלילה.","\u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]\u0006 כי יש להביא ראיה לכך \u0003מהכא\u0004 \u0005[מכאן,\u0006 מהנאמר ביעקב השולח את יוסף לשכם\u0005]:\u0006 \u0003\"לך נא ראה את שלום אחיך ואת שלום\u0004 הצאן והשיבני דבר\" (שם לז, יד), שלא הלך יוסף אלא בזמן שאדם יכול לראות את הנעשה אצל בני אדם ואצל הצאן, שהוא ביום ולא בלילה.","ו\u0003רב אמר\u0004 כי יש להביא ראיה לכך \u0003מהכא\u0004 \u0005[מכאן,\u0006 מהנאמר ביעקב לאחר מאבקו עם המלאך בפנואל \u0003\"ויזרח לו השמש\u0004 כאשר עבר את פנואל\" (שם לב, לא), שלא הלך יעקב לדרכו בלילה אלא משזרחה השמש. שכן אין ראוי לתלמיד חכם לצאת בלילה.","מתוך שהובאה דרשת הכתוב \"ויזרח לו השמש\", מביאים עוד בדרשת כתוב זה. \u0003אמר ר' עקיבא: שאלתי את רבן גמליאל ואת ר' יהושע\u0004 בעת שהיו \u0003באיטליז\u0004 (מקום מכירת בשר) \u0003של\u0004 היישוב \u0003אימאום, שהלכו\u0004 חכמים אלה \u0003ליקח\u0004 (לקנות) \u0003בהמה ל\u0004בשרה, לצורך \u0003משתה\u0004 (חתונה) של \u0003בנו של רבן גמליאל.\u0004 ושאלתי היתה, \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויזרח לו השמש\", וכי\u0004 ה\u0003שמש לו\u0004 ליעקב \u0003לבד זרחה? והלא לכל העולם\u0004 כולו \u0003זרחה!\u0004","\u0003אמר ר' יצחק\u0004 בהסבר הדברים: \u0003שמש\u0004 זו \u0003הבאה\u0004 (ששקעה) בעבר \u0003בעבורו\u0004 של יעקב, \u0003זרחה\u0004 הפעם במיוחד \u0003בעבורו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויצא יעקב מבאר שבע וילך חרנה\"\u0004 (שם כח, י), הרי שהלך לחרן והגיע לשם, \u0003ו\u0004אולם בהמשך הפסוק \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויפגע במקום\u0004 וילן שם כי בא השמש\", והיה זה בבית אל, ולא בחרן. ומעתה כיצד יתפרשו הכתובים הסותרים? ויש לפרש שאכן הגיע יעקב לחרן, ואולם \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003לחרן אמר: אפשר עברתי\u0004 בדרכי לחרן \u0003על\u0004 פני ה\u0003מקום ש\u0004בו \u0003התפללו אבותי,\u0004 אברהם ויצחק, \u0003ואני לא התפללתי\u0004 בו? \u0003כד יהיב דעתיה למיהדר\u0004 \u0005[כאשר נתן דעתו לחזור]\u0006 לשם להתפלל \u0003קפצה ליה ארעא\u0004 \u0005[קפצה לו הארץ],\u0006 ו\u0003מיד \"ויפגע במקום\".\u0004","\u0003כד צלי, בעי למיהדר\u0004 \u0005[כאשר\u0006 סיים שם \u0005להתפלל, רצה לחזור\u0006 לחרן\u0005],\u0006 \u0003אמר הקדוש ברוך הוא: צדיק זה בא לבית מלוני, ויפטר\u0004 משם \u0003בלא לינה? מיד, \"בא השמש\"\u0004 ששקעה השמש קודם זמנה. והיא השמש ששקעה ליעקב קודם זמנה, שבה וזרחה ליעקב קודם זמנה.","מתוך שהובאה דרשת ר' יצחק בסתירת כתובים הנאמרים ביציאת יעקב לחרן, מביאים עוד מדרשותיו בסתירה שבכתובים אלה. בתחילה \u0003כתיב\u0004 \u0005[נאמר]\u0006 כי לאחר ששקעה השמש \u0003\"ויקח מאבני המקום\u0004 וישם מראשותיו\" (שם), הרי שלקח יעקב כמה אבנים לשים מראשותיו בלילה, \u0003ו\u0004אולם לאחר מכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \"וישכם יעקב בבוקר \u0003ויקח את האבן\",\u0004 משמע שהיתה זו רק אבן אחת! \u0003אמר ר' יצחק: מלמד ש\u0004אמנם לקח יעקב כמה אבנים, ואולם \u0003נתקבצו כל אותן אבנים למקום אחד, וכל אחת ואחת אומרת \"עלי יניח צדיק זה\u0004 את \u0003ראשו\". תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003וכולן נבלעו ב\u0004אבן \u0003אחד.\u0004","ועוד בבירור מקראות ביציאת יעקב לחרן, נאמר שם: \u0003\"ויחלום והנה סולם מוצב ארצה\u0004 וראשו מגיע השמימה והנה מלאכי אלהים עולים ויורדים בו\" (שם, יב), \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כמה\u0004 היה \u0003רחבו של סולם\u0004 זה? \u0003שמונת אלפים פרסאות,\u0004 ומסבירים \u0003:\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור הסולם: \u0003\"והנה מלאכי אלהים עולים ויורדים בו\",\u0004 ונדייק: \u0003\"עולים\"\u0004 — הרי זה מורה כי \u0003שנים\u0004 מלאכים הם העולים בסולם, וכן \u0003נאמר\u0004 \u0003\"ויורדים\"\u0004 — הרי זה מורה כי עוד \u0003שנים\u0004 מלאכים הם היורדים בו. \u0003ו\u0004\u0003מעתה\u0004 \u0003כי פגעו בהדי הדדי\u0004 \u0005[כאשר\u0006 הם \u0005נפגשים יחד]\u0006 \u0003הוו להו\u0004 \u0005[הריהם]\u0006","\u0003ארבעה\u0004 הנמצאים בסולם כאחד. \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003במלאך \"וגויתו כתרשיש\"\u0004 (דניאל י, ו), \u0003וגמירי\u0004 \u0005[ומסור בידינו]\u0006 שמידתו של הים הנקרא \u0003תרשיש תרי אלפי פרסי הוו\u0004 \u0005[אלפיים פרסה הם],\u0006 ואם יש ארבעה מלאכים הנמצאים כאחד בסולם הרי שרוחבו של הסולם הוא שמונת אלפים פרסה.","ועוד \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בענין הכתוב \"עולים ויורדים בו\" וסמיכותו לאמור לאחר מכן \"והנה ה' נצב עליו\" (בראשית שם, יג): היו המלאכים \u0003עולין\u0004 המלאכים \u0003ומסתכלין בדיוקנו\u0004 של יעקב \u0003של מעלה\u0004 (פרצוף אדם שבארבע חיות, כנאמר בחזון המרכבה בספר יחזקאל פרק א, שהוא בדמותו של יעקב), \u0003ויורדין\u0004 המלאכים \u0003ומסתכלין בדיוקנו\u0004 יעקב \u0003של מטה. בעו לסכוניה\u0004 \u0005[רצו לסכן אותו,\u0006 את יעקב\u0005]\u0006 מפני הקנאה. \u0003מיד, \"והנה ה' נצב עליו\",\u0004 לשומרו. ובכתוב זה \u0003אמר ר' שמעון בן לקיש: אלמלא מקרא\u0004 זה \u0003כתוב, אי אפשר לאמרו\u0004 מדעתנו, \u0003כאדם שמניף על בנו\u0004 שמנפנף לו במניפה לעשות לו נחת, כך היה ה' ניצב עליו לשומרו מפני המלאכים.","עוד בדרשות הכתובים בפרשה זו, נאמר בהתגלות ה' ליעקב \u0003\"הארץ אשר אתה שוכב עליה\u0004 לך אתננה ולזרעך\" (בראשית שם), ושואלים: \u0003מאי רבותיה\u0004 \u0005[מה גדולתה]\u0006 של הבטחה זו, שהרי מקום שכיבתו של אדם הריהו פיסת ארץ קטנה מאד! \u0003אמר ר' יצחק: מלמד שקפלה הקדוש ברוך הוא לכל ארץ ישראל\u0004 כולה \u0003והניחה\u0004 למשכב \u0003תחת יעקב אבינו,\u0004 ונמצא שכל ארץ ישראל הובטחה ליעקב ולזרעו. וכל כך למה? כדי \u0003שתהא נוחה ליכבש לבניו.\u0004","ושבים לדרשות הכתובים בענין מאבקו של יעקב עם המלאך. \u0003\"ויאמר שלחני כי עלה השחר\"\u0004 (שם לב, כו), \u0003אמר לו\u0004 יעקב למלאך: וכי \u0003גנב אתה, או קוביוסטוס\u0004 (משקר, מרמה בקוביות) \u0003אתה, שמתיירא מן השחר\u0004 פן תתגלה לאור היום ותיתפס, ולכן אתה צריך לצאת מיד עם עלות השחר? \u0003אמר לו:\u0004 אין אני מכלל בני אדם, אלא \u0003מלאך אני, ומיום שנבראתי לא הגיע\u0004 עדיין \u0003זמני לומר שירה עד עכשיו,\u0004 ועכשיו צריך אנו לעלות ולומר שירה.","ואומרים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003ל\u0004דעת \u0003רב חננאל אמר רב,\u0004 שכן \u0003אמר רב חננאל אמר רב: שלש כתות\u0004 חדשות \u0003של מלאכי השרת אומרות שירה בכל יום, אחת\u0004 מהן \u0003אומרת \"קדוש\", ואחת\u0004 מהן \u0003אומרת \"קדוש\", ואחת\u0004 מהן \u0003אומרת \"קדוש ה' צבאות\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו כי \u0003חביבין ישראל לפני הקדוש ברוך הוא יותר ממלאכי השרת. ש\u0004כן \u0003ישראל אומרים שירה בכל שעה\u0004 שרוצים, \u0003ו\u0004אילו \u0003מלאכי השרת אין אומרים שירה אלא פעם אחת ביום, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאומרים המלאכים \u0003פעם אחת בשבת\u0004 (בשבוע) בלבד, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאינם אומרים אלא \u0003פעם אחת בחודש, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי שירתם של המלאכים היא \u0003פעם אחת בשנה, ואמרי לה\u0004 \u0005[ויש\u0006 \u0005אומרים]\u0006 כי היא רק \u0003פעם אחת בשבוע\u0004 (בשבע שנים), \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי היא אינה \u0003אלא\u0004 \u0003פעם אחת ביובל\u0004 (חמישים שנה), \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאין היא אלא \u0003פעם אחת בעולם\u0004 בכל ימי חייהם.","\u0003ו\u0004עוד מחיבתן של ישראל היתירה על מלאכי השרת, ש\u0003ישראל מזכירין את השם\u0004 מיד ל\u0003אחר שתי תיבות\u0004 שאומרים, \u0003ש\u0004כן \u0003נאמר: \"שמע ישראל ה'\u0004 אלהינו ה' אחד\" (דברים ו, ד), \u0003ו\u0004אילו \u0003מלאכי השרת אין מזכירין את השם אלא לאחר שלש תיבות, כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 במלאכים \"וקרא זה אל זה ואמר \u0003קדוש קדוש קדוש ה' צבאות\u0004 מלוא כל הארץ כבודו\" (ישעיה ו, ג).","\u0003ו\u0004לא עוד אלא ש\u0003אין מלאכי השרת אומרים שירה\u0004 בעולמות \u0003ש\u0004\u0003למעלה, עד ש\u0004לפני כן \u0003יאמרו ישראל\u0004 שירה בעולם ש\u0003למטה,\u0004 בעולם הזה. \u0003ש\u0004כן \u0003נאמר: \"ברן יחד כוכבי בקר\"\u0004 (איוב לח, ז), הם בני ישראל המשולים לכוכבים, \u0003ו\u0004רק אחר כך \u0003הדר\u0004 \u0005[חזר]\u0006 הכתוב לומר \u0003\"ויריעו כל בני אלהים\",\u0004 הם מלאכי \u0003השרת.\u0004 ואם כן, למדנו שאין המלאכים מזכירים את שם ה' אלא לאחר שלוש תיבות (\"קדוש קדוש קדוש\"), ושלא כדברי רב חננאל בשם רב שהכת השלישית של מלאכי השרת מזכירה את שם ה' לאחר תיבה אחת (\"קדוש\")!","\u0003אלא\u0004 צריך לומר כך בדברי רב חננאל בשם רב: כת \u0003אחת אומרת \"קדוש\", ו\u0004כת \u0003אחת אומרת \"קדוש קדוש\", ו\u0004כת \u0003אחת אומרת \"קדוש קדוש קדוש ה' צבאות\".\u0004 ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם אמירת מלאכים שיש בה הזכרת שם ה' לאחר שתי תיבות, שכן נאמר בנבואת יחזקאל \"ותשאני רוח ואשמע אחרי קול רעש גדול \u0003ברוך\u0004 כבוד ה' ממקומו. וקול כנפי החיות משיקות אשה אל אחותה וקול האופנים לעומתם וקול רעש גדול\" (יחזקאל ג, יב—יג). הרי שמזכירים שאף המלאכים מזכירים את שם ה' לאחר שתי תיבות בלבד (\"ברוך כבוד\")!"],["ומשיבים: \u0003\"ברוך\u0004 כבוד ה' ממקומו\" אינו נאמר על ידי השרפים, אלא ה\u0003אופנים הוא דאמרי ליה\u0004 \u0005[שאומרים אותה],\u0006 ולא באופנים אמר רב את דבריו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003כיון דאתיהיב רשותא\u0004 \u0005[ש\u0006כבר \u0005ניתנה רשות]\u0006 למלאכים להזכיר את השם, לאחר שלוש תיבות \"קדוש\" שאמרו, \u0003אתיהיב\u0004 \u0005[ניתנה]\u0006 להם רשות להזכיר אף אחרי שתי תיבות.","ועוד בדרשות הכתובים בענין מאבק יעקב והמלאך, נאמר בנביא בתיאור מאבק זה \u0003\"וישר אל מלאך ויוכל בכה ויתחנן לו\"\u0004 (הושע יב, ה). אכן מכתוב זה כשלעצמו \u0003איני יודע מי נעשה שר למי,\u0004 אם יעקב למלאך או המלאך ליעקב? ולכן \u0003כשהוא\u0004 המלאך \u0003אומר\u0004 ליעקב לאחר המאבק \u0003\"כי שרית עם אלהים\u0004 ועם אנשים ותוכל\" (בראשית לב, כח), \u0003הוי אומר\u0004 כי \u0003יעקב\u0004 הוא זה ש\u0003נעשה שר למלאך.\u0004","וכן בהמשך דברי הנביא \u0003\"בכה ויתחנן לו\", איני יודע מי\u0004 הוא זה ש\u0003בכה\u0004 והתחנן \u0003למי,\u0004 אם יעקב למלאך או המלאך ליעקב. אבל \u0003כשהוא\u0004 המלאך \u0003אומר\u0004 ליעקב \u0003\"ויאמר שלחני\u0004 כי עלה השחר\" (בראשית שם, כו), \u0003הוי אומר:\u0004 ה\u0003מלאך\u0004 הוא זה ש\u0003בכה\u0004 והתחנן \u0003ליעקב.\u0004","ועוד בדרשות הכתובים הללו. נאמר כי אמר המלאך ליעקב \u0003\"כי שרית עם אלהים ועם אנשים\", אמר רבה: רמז רמז לו שעתידים שני שרים\u0004 (מנהיגי אומה) \u0003לצאת ממנו,\u0004 והם \u0003ראש\u0004 ה\u0003גולה שבבבל, ו\u0004ה\u0003נשיא שבארץ ישראל.\u0004 ו\u0003מכאן\u0004 גם ש\u0003רמז לו\u0004 על \u0003גלות\u0004 עם ישראל העתידה להיות.","וכן בחלומו של שר המשקים במצרים \u0003\"ובגפן שלשה שריגים\"\u0004 (שם מ, י), \u0003אמר רב חייא בר אבא, אמר רב: אלו שלשה שרי גאים\u0004 (\"שריגים\"), מנהיגים נישאים, \u0003היוצאים מישראל בכל דור ודור,\u0004 בבבל ובארץ ישראל. ומאלה \u0003פעמים ש\u0004מקומם של \u0003שנים\u0004 מהם הוא \u0003כאן\u0004 בבבל \u0003ו\u0004מקומו של ה\u0003אחד\u0004 הנוסף הוא \u0003בארץ ישראל,\u0004 ו\u0003פעמים ש\u0004מקומם של \u0003שנים\u0004 מהם הוא \u0003בארץ ישראל ו\u0004מקומו של ה\u0003אחד\u0004 הנוסף הוא \u0003כאן\u0004 בבבל. ומסופר כי \u0003יהיבו רבנן עינייהו\u0004 \u0005[נתנו חכמים עיניהם]\u0006 כדוגמה לשני מנהיגי הדור הגרים בבבל, \u0003ברבנא\u0004 \u0005[ברב]\u0006 \u0003עוקבא ורבנא\u0004 \u0005[ורב]\u0006 \u0003נחמיה בני ברתיה\u0004 \u0005[בני בתו]\u0006 של \u0003רב\u0004 שהיו מבית ראש הגולה.","\u0003רבא אמר\u0004 בפירוש הכתוב \"ובגפן שלושה שריגים\": \u0003אלו שלשה שרי גוים\u0004 (מלאכים הממונים על אומות העולם) \u0003שמלמדים זכות על ישראל בכל דור ודור.\u0004","ועוד מדרשות חכמים על הכתוב \"ובגפן שלושה שריגים\", \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: \"גפן\"\u0004 — \u0003זה העולם, \"שלשה שריגים\"\u0004 — \u0003זה אברהם יצחק ויעקב, \"והיא כפורחת עלתה נצה\"\u0004 — \u0003אלו האמהות, \"הבשילו אשכלותיה ענבים\"\u0004 — \u0003אלו השבטים.\u0004","\u0003אמר לו ר' יהושע\u0004 לר' אליעזר: \u0003וכי מראין לו לאדם,\u0004 כדרך שהראו לשר המשקים במצרים בחלומו, את \u0003מה ש\u0004כבר \u0003היה?\u0004 והרי האבות והאמהות והשבטים כבר היו! \u0003והלא אין מראין לו לאדם\u0004 בחזון \u0003אלא מה שעתיד להיות! אלא\u0004 כך יש לדרוש מקרא \u0003זה:\u0004 \u0003\"גפן\"\u0004 — \u0003זה תורה,\u0004 שעתידים ישראל לקבלה במעמד הר סיני, \u0003\"שלשה שריגים\"\u0004 — \u0003אלו משה ואהרן ומרים\u0004 שעתידים להנהיג את ישראל כשיצאו ממצרים, \u0003\"והיא כפורחת עלתה נצה\"\u0004 — \u0003אלו סנהדרין\u0004 שעתידים לשפוט ולהנהיג את ישראל. \u0003\"הבשילו אשכלותיה ענבים\"\u0004 — \u0003אלו הצדיקים ש\u0004עתידים להיות \u0003בכל דור ודור.\u0004","\u0003אמר רבן גמליאל:\u0004 בפירוש מקרא זה, אף שדרשוהו ר' אליעזר ור' יהושע, \u0003עדיין צריכין אנו ל\u0004דבריו של ר' אלעזר ה\u0003מודעי,\u0004 שהוא גדול באגדה, \u0003דמוקים ליה כוליה בחד מקום\u0004 \u0005[שמעמיד את כל\u0006 דברי הכתוב \u0005במקום אחד].\u0006 שכך היה \u0003ר' אלעזר המודעי אומר: \"גפן\"\u0004 — \u0003זה ירושלים, \"שלשה שריגים\"\u0004 — \u0003זה מקדש, מלך, וכהן גדול, \"והיא כפורחת עלתה נצה\"\u0004 — \u0003אלו פרחי כהונה, \"הבשילו אשכלותיה ענבים\"\u0004 — \u0003אלו נסכים.\u0004","ומביאים עוד בדרשת כתוב זה כי \u0003ר' יהושע בן לוי מוקים לה\u0004 \u0005[מעמיד,\u0006 מפרש \u0005אותו]\u0006 \u0003ב\u0004ענין ה\u0003מתנות\u0004 שנתן הקדוש ברוך הוא לישראל. שכך \u0003אמר ר' יהושע בן לוי: \"גפן\"\u0004 — \u0003זו\u0004 ה\u0003תורה,\u0004 שניתנה לעם ישראל בסיני. \u0003\"שלשה שריגים\"\u0004 — \u0003זה\u0004 מתנות ה\u0003באר, עמוד ענן, ומן\u0004 שניתנו לישראל במדבר. \u0003\"והיא כפורחת עלתה נצה\"\u0004 — \u0003אלו\u0004 פירות ארץ ישראל, שהנחילה הקדוש ברוך הוא לישראל מלאת פירות הראויים להביא מהם את \u0003הבכורים. \"הבשילו אשכלותיה ענבים\"\u0004 — \u0003אלו\u0004 ה\u0003נסכים\u0004 הבאים מענביה.","ואילו \u0003ר' ירמיה בר אבא\u0004 העמיד את הכתוב כמדבר בעם ישראל, שכך \u0003אמר\u0004 בדרשת הכתוב: \u0003\"גפן\"\u0004 — \u0003אלו ישראל, וכן הוא אומר\u0004 בתיאור עם ישראל היוצא ממצרים: \u0003\"גפן ממצרים תסיע\u0004 תגרש גוים ותטעה. פנית לפניה ותשרש שרשיה ותמלא ארץ\" (תהלים פ, ט—י), \u0003\"שלשה שריגים\"\u0004 — \u0003אלו שלשה רגלים שישראל עולין בהן\u0004 לירושלים \u0003בכל שנה ושנה, \"והיא כפורחת עלתה נצה\"\u0004 — \u0003הגיע זמנן של ישראל לפרות ולרבות, וכן הוא\u0004 הכתוב \u0003אומר\u0004 בתיאור התרבות בני ישראל במצרים: \u0003\"ובני ישראל פרו וישרצו\u0004 וירבו ויעצמו במאד מאד ותמלא הארץ אותם\" (שמות א, ז),","\u0003\"עלתה נצה\"\u0004 — \u0003הגיע זמן של ישראל ליגאל, וכן הוא,\u0004 הכתוב, \u0003אומר\u0004 בתיאור הגאולה ונקמת ה' באויביהם: \u0003\"ויז נצחם על בגדי וכל מלבושי אגאלתי\"\u0004 (ישעיהו סג, ג), \u0003\"הבשילו אשכלותיה ענבים\"\u0004 — \u0003הגיע זמנה של מצרים לשתות כוס התרעלה.\u0004","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא: שלשה כוסות האמורות במצרים\u0004 בחלומו של שר המשקים (\"וכוס פרעה בידי ואקח את הענבים ואשחט אותם אל כוס פרעה ואתן את הכוס על כף פרעה\". בראשית מ, יא) \u0003למה?\u0004 — כנגד שלוש כוסות תרעלה שעתידה מצרים לשתות: \u0003אחד, ששתה\u0004 העם המצרי \u0003בימי משה\u0004 בעשרת המכות וקריעת ים סוף. \u0003ואחד ששתה בימי פרעה נכה\u0004 (בחורבן שהמיט עליה נבוכדנצר מלך בבל), \u0003ואחד שעתידה\u0004 מצרים \u0003לשתות עם כל הגוים\u0004 לעת ימות המשיח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לר' ירמיה בר אבא: כי דריש להו\u0004 \u0005[כאשר דרש אותם]\u0006 \u0003רב להני קראי באגדתא\u0004 \u0005[את הפסוקים הללו באגדה],\u0006 \u0003כוותך דריש להו\u0004 \u0005[כמוך דרש אותם],\u0006 ולא כדרשות האחרות.","ומוסיפים כי כדרך שדרש ר' ירמיה בר אבא את הכתוב \"גפן\" כמתאר את עם ישראל, כך גם \u0003אמר ר' שמעון בן לקיש: אומה זו\u0004 ישראל \u0003כגפן נמשלה.\u0004 וכשם שיש בגפן זמורות (הענפים), ואשכולות (ענבים), ועלים, וקנוקנות (כעין חוטים שבהם נאחזים ענבי הגפן), כן יש בעם ישראל. \u0003זמורות שבה\u0004 — \u0003אלו\u0004 הם \u0003בעלי בתים,\u0004 שכשם שזמורות הגפן נושאות עליהן את האשכולות והעלים והקנוקנות, כן בעלי הבתים הם המקיימים בממונם את כלל האומה. \u0003אשכולות\u0004 הענבים \u0003שבה\u0004 — \u0003אלו\u0004 הם \u0003תלמידי חכמים,\u0004 שהם הפרי. ה\u0003עלין שבה\u0004 — \u0003אלו\u0004 הם \u0003עמי הארץ\u0004 המגוננים על תלמידי החכמים בעם ישראל, כדרך שהעלים מגינים על אשכלות הענבים. ואילו ה\u0003קנוקנות שבה\u0004 — \u0003אלו\u0004 הם ה\u0003ריקנים שבישראל,\u0004 וכעין הקנוקנות, שאינן תורמות דבר לאשכולות הענבים.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 בבקשה: \u0003ליבעי רחמים איתכליא על עליא\u0004 \u0005[יבקשו רחמים,\u0006 יתפללו \u0005האשכולות על העלים],\u0006 שכן \u0003אילמלא עליא לא מתקיימן איתכליא\u0004 \u0005[העלים לא יתקיימו האשכולות].\u0006","למעלה דובר בענין ראשי עם ישראל שבבבל ושבארץ ישראל, ובענין זה מביאים עוד. שכן נאמר \u0003\"ואכרה לי בחמשה עשר כסף\u0004 וחומר שעורים ולתך שעורים\" (הושע ג, ב), ובפירוש פסוק זה \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יהוצדק: אין כירה\u0004 האמור בכתוב זה (\"ואכרה\") \u0003אלא לשון מכירה, ש\u0004כן \u0003נאמר\u0004 בדברי יעקב ליוסף \u0003\"בקברי אשר כריתי לי\u0004 בארץ כנען שמה תקברני\" (בראשית נ, ה), ואין הכוונה אלא לקנין הקבר (מידי עשיו), ולא שנחפר כבר הקבר.","\u0003\"בחמשה עשר\"\u0004 — \u0003זה חמשה עשר בניסן שבו נגאלו ישראל ממצרים, \"כסף\"\u0004 — \u0003אלו צדיקים, וכן הוא אומר \"צרור הכסף לקח בידו\"\u0004 (משלי ז, כ),","\u0003\"חומר שעורים ולתך שעורים\"\u0004 — \u0003אלו ארבעים וחמשה צדיקים שהעולם מתקיים בהם.\u0004 שכן מידת חומר היא בת שלושים סאה, ומידת הלתך היא בת חמישה עשר סאה, ומסתכמים שניהם בארבעים וחמש סאים, כמניינם של הצדיקים. כאשר שלושים מהם נמצאים במקום אחד וחמישה עשר במקום אחר, \u0003ו\u0004מתוך הכתוב הזה עדיין \u0003איני יודע אם\u0004 ה\u0003שלשים\u0004 נמצאים \u0003כאן\u0004 בבבל \u0003ו\u0004ה\u0003חמשה עשר בארץ ישראל, ואם\u0004 ה\u0003שלשים בארץ ישראל ו\u0004ה\u0003חמשה עשר כאן.\u0004 ואולם \u0003כשהוא\u0004 הכתוב \u0003אומר: \"ואקחה שלשים\u0004 ה\u0003כסף ואשליך אותו בית ה' אל היוצר\"\u0004 (זכריה יא, יג), \u0003הוי אומר: שלשים\u0004 הצדיקים נמצאים \u0003בארץ ישראל וחמשה עשר כאן\u0004 בבבל.","\u0003אמר אביי: ורובייהו\u0004 \u0005[ורוב]\u0006 חמישה עשר הצדיקים שבבבל \u0003משתכחי בבי כנישתא דתותי אפתא\u0004 \u0005[מצויים בבית הכנסת שמתחת ליציע].\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]\u0006 עוד בנבואת זכריה (שם יב) בדברי ה' לאומות העולם \u0003\"ואומר אליהם אם טוב בעיניכם הבו שכרי ואם לא חדלו וישקלו את שכרי שלשים כסף\".\u0004 שיחזירו לה' את שלושים הצדיקים, שהיו מקבלים בעבורם שכר.","\u0003ר' יהודה אומר: אלו שלשים צדיקי אומות העולם, ש\u0004בזכותם \u0003אומות העולם מתקיימים עליהם. עולא אמר: אלו שלשים מצות שקבלו עליהם בני נח\u0004 מתחילה, \u0003ו\u0004אולם הם \u0003אין מקיימין\u0004 מהם \u0003אלא שלשה\u0004 בלבד, ואלו הן: \u0003אחת\u0004 —"],["\u0003שאין כותבין כתובה לזכרים,\u0004 שאף על פי שנוהגים במשכב זכר, ואף מייחדים להם זכר לתשמישם, אין הם מזלזלים עד כדי כך באיסור זה לעשותו כדרך שעושים בנישואין, בכתיבת כתובה. \u0003ואחת\u0004 — אף \u0003ש\u0004חשודים הם על אכילת בשר \u0003המת,\u0004 \u0003אין\u0004 הם \u0003שוקלין בשר המת במקולין\u0004 (באיטליז) למוכרו לעיני כל. \u0003ואחת\u0004 — \u0003שמכבדין את התורה.\u0004","שנינו במשנתנו כי גיד הנשה \u0003אינו נוהג בעוף,\u0004 מפני שאין לו בליטת בשר עגולה סביב הירך (\"כף\"), ובאיסור גיד הנשה נאמר \"אשר על כף הירך\" (בראשית לב, לב). ותוהים: \u0003והא קא חזינן דאית ליה\u0004 \u0005[והרי אנו רואים שיש לו,\u0006 לעוף\u0005]\u0006 בליטת בשר כזו? ומשיבים: אמנם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 לעוף בליטת בשר זו, \u0003ו\u0004אולם היא \u0003לא עגיל\u0004 \u0005[עגולה]\u0006 סביב עצם הירך אלא ברוחבה בלבד.","ומביאים כי בענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 במקרה ו\u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לעוף\u0004 כף שכזו, \u0003ועגיל\u0004 \u0005[ו\u0006היא \u0005עגולה],\u0006 וכן במקרה ו\u0003אית ליה\u0004 \u0005[יש לה]\u0006 \u0003לבהמה\u0004 כף הירך, \u0003ו\u0004אולם היא \u0003לא עגיל\u0004 \u0005[אינה עגולה],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003בתר דידיה אזלינן\u0004 \u0005[אחריו,\u0006 אחרי אותו בעל חיים \u0005לעצמו\u0006 \u0005אנו הולכים\u0006 בקביעת דינו\u0005],\u0006 \u0003או\u0004 שמא \u0003בתר מיניה אזלינן\u0004 \u0005[אחר מינו\u0006 של בעל החיים \u0005אנו הולכים\u0006 בקביעת דינו\u0005],\u0006 ולכך עוף זה אף שכף הירך שלו עגולה, אין נוהג בו איסור גיד הנשה. ואילו בהמה זו אף שאין כף הירך שלה עגולה, מכל מקום נוהג בה איסור גיד הנשה. ומסכמים: שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","\u0003ו\u0004עוד שנינו במשנתנו כי איסור גיד הנשה \u0003נוהג בשליל,\u0004 ור' יהודה אומר כי אינו נוהג בשליל, וחלבו גם כן מותר. ובפירוש הדברים \u0003אמר שמואל\u0004 כי הלשון \u0003\"וחלבו מותר\"\u0004 הנאמרת במשנתנו אינה המשך לדברי ר' יהודה, אלא זוהי הלכה \u0003לדברי הכל,\u0004 שאף חכמים החולקים על ר' יהודה בדין גיד הנשה בשליל, סבורים כן.","ושואלים: \u0003חלבו\u0004 זה שמותר הוא לדעת שמואל לדברי הכל, חלב \u0003דמאי\u0004 \u0005[של מה]\u0006 הוא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא לחלבו של ה\u0003שליל\u0004 — אין לומר כן, כי \u0003הא מיפלג פליגי\u0004 \u0005[הרי חלוקים]\u0006 חכמים \u0003ביה\u0004 \u0005[בו,\u0006 בדין זה\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 איסור גיד הנשה \u0003נוהג בשליל, ו\u0004כן \u0003חלבו\u0004 של השליל \u0003אסור,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר\u0004 כי איסור גיד הנשה \u0003אינו נוהג בשליל, וחלבו\u0004 של השליל \u0003מותר.\u0004","\u0003ואמר ר' אלעזר, אמר ר' אושעיא\u0004 בפירוש \u0003מחלוקת\u0004 זו, כי המדובר בה \u0003ב\u0004וולד \u0003בן תשעה\u0004 חודשים \u0003חי\u0004 העומד לפנינו, שנמצא במעי בהמה לאחר שנשחטה. \u0003והלך ר' מאיר\u0004 בהלכה זו \u0003לשיטתו\u0004 (כמבואר לעיל עד,א) שוולד כזה דורש שחיטה לעצמו כדי להתירו באכילה, ואינו מותר לאכילה על ידי שחיטת אמו (כדרך עובר אחר). ומאחר וולד כזה נחשב לעצמו, והינו כשאר בהמות, לכך אף נוהגים בו איסורי גיד הנשה וחלב כבשאר בהמות. \u0003ו\u0004כן \u0003ר' יהודה\u0004 הלך בה \u0003לשיטתו\u0004 בענין זה, שסבור כי ולד כזה ניתר לאכילה על ידי שחיטת אמו. ומכאן שאינו נחשב כבעל חיים לעצמו, ולכך אף אין נוהגים בו איסורי גיד הנשה וחלב. הרי שאין דין חלבו של שליל מוסכם על הכל!","\u0003ואלא\u0004 תאמר בדברי שמואל שהכוונה היא ל\u0003חלבו\u0004 של \u0003גיד\u0004 הנשה — אף כך אין לומר, כי \u0003הא מיפלג פליגי\u0004 \u0005[הרי חלוקים]\u0006 חכמים \u0003בה,\u0004 בהלכה זו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדרך הוצאת \u0003גיד הנשה\u0004 מן הירך, שצריך שיהא \u0003מחטט אחריו בכל מקום שהוא, וחותך שמנו מעיקרו\u0004 (משורשו), שמוציא מכל מקום שהוא בלוע בבשר הירך, אלו הם \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר\u0004 כי אין צורך להוציא מכל מקום, אלא די שיהא \u0003גוממו\u0004 (גודעו) \u0003עם השופי\u0004 (בהחלקה, ביישור), שדי בהסרת הגבשושית שמעל הירך, באופן שהכל יהיה משטח ישר, ואולם אין צורך להעמיק יתר על כך בהוצאת הגיד. הרי איפוא שחלוקים חכמים על ר' יהודה גם בדין חלבו של הגיד, ומעתה אין זה ברור מה כוונת דברי שמואל!","ומשיבים: \u0003לעולם\u0004 מדובר ב\u0003חלבו\u0004 של \u0003גיד\u0004 הנשה, ולדעת שמואל הכל (ואף ר' מאיר) סבורים שהריהו מותר מן התורה, \u0003ו\u0004אולם \u0003מודה שמואל\u0004 ש\u0003ל\u0004שיטת \u0003ר' מאיר מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 חלבו של גיד הנשה \u0003אסור,\u0004 ולכך יש לדעת ר' מאיר לגוממו. וראיה לדבר שלדעת ר' מאיר מותר חלבו של גיד הנשה מן התורה ואינו אסור אלא מדברי חכמים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ושמנו\u0004 של גיד הנשה \u0003מותר\u0004 מן התורה, \u0003ו\u0004אולם \u0003ישראל\u0004 ש\u0003קדושים\u0004 הם \u0003נהגו בו איסור. מאי לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' מאיר היא\u0004 ש\u0003אמר: מותר מן התורה ואסור מדרבנן\u0004 \u0005[מדברי סופרים]?!\u0006","ודוחים: אין מכאן ראיה שכן \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה יודע שברייתא זו היא כדעת ר' מאיר, \u0003דילמא\u0004 \u0005[שמא]\u0006 כשיטת \u0003ר' יהודה היא, אבל לר' מאיר מדאורייתא נמי אסיר\u0004 \u0005[מהתורה גם כן אסור\u0006 חלבו של גיד הנשה\u0005]!\u0006","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[אל יעלה על דעתך]\u0006 לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 האומרת כי \u0003גיד הנשה מחטט אחריו בכל מקום שהוא, ושמנו מותר.\u0004 ויש לברר: \u0003מאן\u0004 \u0005[מי]\u0006 החכם ש\u0003שמעת ליה דאית ליה\u0004 \u0005[אותו שיש לו,\u0006 שהוא \u0005סבור\u0006\u0005]\u0006 דין זה של \u0003חטיטה?\u0004 הלא \u0003ר' מאיר\u0004 הוא, כמבואר למעלה, ושלא כדעת ר' יהודה. \u0003וקאמר\u0004 \u0005[והוא אומר]\u0006 בברייתא זו כי \u0003שמנו\u0004 של גיד הנשה \u0003מותר.\u0004 הרי איפוא \u0003שסבור ר' מאיר כי מן התורה מותר חלבו של גיד הנשה, ואינו אסור אלא מדברי חכמים.\u0004","ועוד בענין איסור גיד הנשה, \u0003אמר רב יצחק בר שמואל בר מרתא, אמר רב: לא אסרה תורה אלא\u0004 רק את ה\u0003קנוקנות שבו,\u0004 הגידים הדקים שלאורך הירך מתחת לבשר, וסמוכים לגיד העיקרי, שרק הם אסורים, שכן הם רכים ויש בהם טעם. ואולם הגיד עצמו, שהוא קשה ואין בו טעם, הריהו כעץ ולא נאסר מן התורה. ואילו \u0003עולא אמר\u0004 כי אמנם הגיד עצמו כ\u0003עץ הוא,\u0004 ואולם \u0003התורה חייבה עליו.\u0004 כפי שהוא, אף שאין בו טעם.","\u0003אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003עולא מסתברא\u0004 \u0005[מסתבר],\u0006 שהרי \u0003אמר רב ששת, אמר רב אסי\u0004 כי ה\u0003חוטין שב\u0004תוך ה\u0003חלב\u0004 (כחוטי הכסלים, והחוטים הדקים שעל הקרב) \u0003אסורין\u0004 באכילה, \u0003ו\u0004אולם \u0003אין חייבין עליהן, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חלב אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא חוטין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003גיד אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא קנוקנות.\u0004","למעלה הובאה הלכה שאמר רב ששת בשם רב אסי לבירור הכרעת הדין במחלוקת רב ועולא, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה].\u0006 שכן \u0003אמר רב ששת, אמר רב אסי: חוטין שבחלב אסורין, ואין חייבין עליהן,\u0004 חוטים \u0003שבכוליא\u0004 (כליה) \u0003אסורין ואין חייבין עליהן. לובן כוליא\u0004 שהוא כעין חלב, נחלקו בכך רבי ור' חייא, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר וחד שרי\u0004 \u0005[ואחד מהם התיר],\u0006","\u0003רבה ממרטט ליה\u0004 \u0005[היה מחטט אחריו],\u0006 \u0003ר' יוחנן ממרטט ליה\u0004 \u0005[היה מחטט אחריו],\u0006 \u0003ר' אסי גאים ליה\u0004 \u0005[חותך אותו]\u0006 מבחוץ. \u0003אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' אסי מסתברא\u0004 \u0005[מסתבר],\u0006 שכן \u0003אמר ר' אבא, אמר רב יהודה, אמר שמואל:\u0004"],["\u0003חלב ש\u0004על הכסלים, שתחת הכליות, שנראה בגובה הכסלים, ולאחר מכן \u0003הבשר חופה אותו,\u0004 שנבלע תחת הבשר — הריהו \u0003מותר. אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 כי דווקא בחלב זה \u0003שעל הכסלים אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שהוא אסור, \u0003ולא\u0004 בחלב \u0003שבתוך הכסלים. הכא נמי\u0004 \u0005[כאן,\u0006 בענייננו, \u0005גם כן]\u0006 יש לומר כי דווקא חלב \u0003שעל הכליות אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שהוא אסור, \u0003ולא\u0004 בחלב \u0003שבתוך הכליות.\u0004","מקודם, במהלך הסוגיה, הובאו דברים בדינו של חלב שהבשר חופה אותו. ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לגופה,\u0006 כשלעצמה\u0005].\u0006 \u0003אמר ר' אבא, אמר רב יהודה, אמר שמואל: חלב שהבשר חופה אותו\u0004 — הריהו \u0003מותר.\u0004 ושואלים על כך: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן היא]\u0006 דעת ר' אבא בשם רב יהודה בשם שמואל, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא, אמר רב יהודה, אמר שמואל: האי תרבא דתותי מתני\u0004 \u0005[זה החלב שתחת המתניים]\u0006 — הריהו \u0003אסיר\u0004 \u0005[אסור],\u0006 אף שהוא מכוסה בבשר המתניים, הרי שחלב המכוסה בבשר אסור!","\u0003אמר אביי\u0004 בתשובה: ה\u0003בהמה בחייה,\u0004 בשעה שהיא נעה ממקום למקום, \u0003פרוקי מיפרקא\u0004 \u0005[מפורקת,\u0006 שאבריה נפרדים זה מזה\u0005],\u0006 ואף הכסלים והמתניים מתרחקים אלה מאלה בשעה שהיא נעה, שהמתניים עולות כלפי מעלה, והכסלים יורדים כלפי מטה, ובאותה עת החלב שעל הכסלים מתגלה, ולכך אין הוא נחשב כחלב המכוסה בבשר. וכיוצא בדבר \u0003אמר ר' יוחנן: אנא לאו טבחא אנא ולאו בר טבחא אנא\u0004 \u0005[אני לא טבח אני ולא בן טבח אני],\u0006 ואין אני בקי בטיבן של בהמות, \u0003ו\u0004אולם \u0003נהירנא דהכי הוו אמרי בי מדרשא\u0004 \u0005[זוכר אני שכך היו אומרים בבית המדרש]:\u0006 \u0003בהמה בחייה\u0004 בשעת תנועתה ממקום למקום \u0003פרוקי מיפרקא\u0004 \u0005[מפורקת\u0006 איברים\u0005].\u0006","ועוד בדיני החלב \u0003אמר ר' אבא, אמר רב יהודה, אמר שמואל:\u0004 ה\u0003חלב שעל\u0004 חלק הקיבה המכונה \u0003המסס ו\u0004כן זה שעל חלק הקיבה המכונה \u0003בית הכוסות\u0004 — \u0003אסורין\u0004 באכילה, \u0003ו\u0004האוכלם \u0003ענוש כרת, וזהו\u0004 החלב שאמרה בו התורה \"ה \u0003חלב (שעל)\u0004 אשר על \u0003הקרב\"\u0004 (ויקרא ג, ג). ועוד \u0003אמר ר' אבא, אמר רב יהודה, אמר שמואל: האי תרבא\u0004 \u0005[חלב זה]\u0006 הנמצא על העצם הנקרא \u0003קליבוסתא\u0004 — הריהו \u0003אסור\u0004 באכילה \u0003ו\u0004האוכלו \u0003ענוש כרת\u0004 על אכילתו, \u0003וזהו\u0004 החלב שאמרה בו תורה \"ה \u0003חלב\u0004 אשר עליהן \u0003(שעל)\u0004 אשר על \u0003הכסלים\"\u0004 (שם ד).","\u0003ו\u0004עוד \u0003אמר ר' אבא, אמר רב יהודה, אמר שמואל:\u0004 ה\u0003חוטין\u0004 (ורידי הדם) \u0003ש\u0004נמצאים \u0003ביד\u0004 (כתף הבהמה) \u0003אסורין\u0004 באכילה. \u0003אמר רב ספרא\u0004 בתמיהה על דברי רב יהודה בשם שמואל: \u0003משה\u0004 (כינוי לתלמיד חכם), כיצד אתה אומר כן, \u0003מי אמר רחמנא \"לא תיכול בישרא\"\u0004 \u0005[האם אמרה התורה \"אל תאכל בשר\"]?!\u0006 שהרי אף חוטים אלה הינם בשר, ולא חלב! וכמו כן \u0003אמר רבא\u0004 בתמיהה על דברי רב יהודה: \u0003משה, מי אמר רחמנא \"אכול דמא\"\u0004 \u0005[האם אמרה התורה \"אכול דם\"]?!\u0006 שהרי חוטים אלה אסורים באכילה משום דם הנמצא בהם, ולכך, אם \u0003חתכיה ומלחיה\u0004 \u0005[חתכם ומלחם,\u0006 כדי להוציא בכך את הדם מתוכם\u0005],\u0006 \u0003אפילו ל\u0004בישול ב\u0003קדירה נמי שפיר דמי\u0004 \u0005[גם כן יפה הוא,\u0006 מותר הדבר\u0005].\u0006","ועוד הלכה בדין חלב \u0003אמר רב יהודה, אמר שמואל:\u0004 החלב הנמצא ב\u0003ריש מעיא\u0004 \u0005[תחילת המעיים],\u0006 במקום בו המעיים הדקים יוצאים מהקיבה, \u0003באמתא בעי\u0004 \u0005[ב\u0006שיעור \u0005אמה צריך]\u0006 \u0003גרירה,\u0004 \u0003וזהו\u0004 החלב המכונה בפי חכמים \u0003\"חלב שעל\u0004 המעיים \u0003הדקין\".\u0004","\u0003ו\u0004עתה מביאים מהלכות איסור חלב שאמרן רב יהודה עצמו, וכן הלכות באיסור חלב שיש אומרים שרב יהודה הוא שאמרן. \u0003אמר רב יהודה: חוטין ש\u0004נמצאים \u0003בעוקץ\u0004 (עצם הזנב) \u0003אסורין\u0004 באכילה משום חלב. ומבאר דבריו: \u0003חמשא חוטי אית ביה בכפלא\u0004 \u0005[חמישה חוטים יש בו במקום הזנב],\u0006 שהם \u0003תלתא מימינא ותרתי משמאלא\u0004 \u0005[שלושה מימין\u0006 הבהמה \u0005ושנים משמאל],\u0006 אלה \u0003תלתא מפצלי לתרי תרי\u0004 \u0005[\u0006ה\u0005שלושה מתפצלים\u0006 כל אחד מהם \u0005לשנים שנים\u0006 חוטים\u0005],\u0006 ואילו אלה \u0003תרי מפצלי לתלתא תלתא\u0004 \u0005[השנים מתפצלים לשלושה שלושה].\u0006 ובטעם פירוט זה: \u0003נפקא מינה\u0004 \u0005[יוצא מכך]\u0006 השלכה הלכתית במקרה \u0003דאי שליף להו עד דחמימי\u0004 \u0005[שאם שלף אותם עד שהם חמים,\u0006 בעוד שהבשר טרי\u0005],\u0006 מיד לאחר השחיטה — כל החוטים הללו \u0003משתלפי\u0004 \u0005[נשלפים]\u0006 היטב. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 שלף אותם באותה עת — \u0003בעי חטוטי בתרייהו\u0004 \u0005[צריך לחטט אחריהם],\u0006 וצריך איפוא לדעת את מספרם כדי למצוא את כולם.","ועוד בהלכה דומה, \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה: חמשא חוטי הוו\u0004 \u0005[חמישה חוטים\u0006 האסורים באכילה, \u0005הם]\u0006 המצויים בחמשה מקומות בבהמה, \u0003תלתא\u0004 \u0005[שלשה]\u0006 מהם אסורים \u0003משום תרבא\u0004 \u0005[חלב],\u0006 \u0003ותרין\u0004 \u0005[ושנים]\u0006 מהם אסורים \u0003משום דמא\u0004 \u0005[דם],\u0006 ומפרטים: החוטים \u0003דטחלי ודכפלי ודכוליתא\u0004 \u0005[של הטחול ושל הזנב ושל הכליות]\u0006 אסורים \u0003משום תרבא\u0004 \u0005[החלב],\u0006 ואילו החוטים \u0003דידא ודלועא\u0004 \u0005[של היד ושל הלוע]\u0006 אסורים \u0003משום דמא\u0004 \u0005[דם].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם הם אסורים משום חלב או משום דם? ומשיבים: \u0003הני דמשום דמא\u0004 \u0005[אלה ש\u0006אסורים \u0005משום דם],\u0006 \u0003אי מחתך להו ומלח להו\u0004 \u0005[אם חותך\u0006 אותם מגוף הבהמה, \u0005ומולח אותם,\u0006 להוציא את דמם\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הוא],\u0006 שהותרו בכך לאכילה. ואולם \u0003הנך\u0004 \u0005[האחרים,\u0006 שאסורים משום חלב\u0005] —\u0006 \u0003לית להו תקנתא\u0004 \u0005[אין להם תקנה]\u0006 לאוכלם. ועוד הלכה דומה.","\u0003אמר רב כהנא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה: חמשא קרמי הוו\u0004 \u0005[חמישה קרומים הם]\u0006 האסורים באכילה, \u0003תלתא\u0004 \u0005[שלושה]\u0006 מהם אסורים \u0003משום תרבא\u0004 \u0005[חלב],\u0006 \u0003ותרי\u0004 \u0005[ושנים]\u0006 אסורים \u0003משום דמא\u0004 \u0005[דם],\u0006 ומפרטים: הקרומים \u0003דטחלי דכפלי ודכוליתא\u0004 \u0005[של הטחול, של הזנב ושל הכליות]\u0006 \u0005אסורים באכילה\u0006 \u0003משום תרבא\u0004 \u0005[חלב],\u0006 ואילו הקרומים \u0003דביעי ודמוקרא\u0004 \u0005[של ביצי,\u0006 אשכי בהמה \u0005ושל המוח]\u0006 הריהם אסורים \u0003משום דמא\u0004 \u0005[דם].\u0006","מסופר, \u0003רב יהודה בר אושעיא הוה קא קליף ליה טחלא\u0004 \u0005[היה קולף לו\u0006 את \u0005קרום\u0006 \u0005הטחול]\u0006 \u0003ללוי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בר חייא, הוה קא גאים ליה מעילאי\u0004 \u0005[היה הוא חותך אותו מלמעלה,\u0006 בחלק \u0005העליון של הטחול\u0006\u0005]\u0006 בלבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לוי בנו של רב הונא לרב יהודה בר אושעיא: \u0003חות ביה טפי\u0004 \u0005[רד בו יותר,\u0006 עליך לחתוך יותר עמוק\u0005],\u0006 ולהסיר את כל הקרום! \u0003אתא אבוה אשכחיה\u0004 \u0005[בא אביו\u0006 של לוי, רב הונא בר חייא, \u0005מצא אותו]\u0006 בשעה שהוא אומר כן לרב יהודה בר אושעיא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לבנו, \u0003הכי אמר אבוה דאמך\u0004 \u0005[כך אמר אבי אמך]\u0006 \u0003משום\u0004 \u0005[בשם]\u0006 \u0003רב, ומנו\u0004 \u0005[ומיהו]\u0006 אבי אמו של לוי? \u0003רב ירמיה בר אבא: לא אסרה תורה אלא\u0004 את קרום הטחול \u0003שעל הדד\u0004 (מקום עוביו של הטחול) \u0003בלבד.\u0004","הקשה לוי לאביו: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב המנונא, תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: ה\u0003קרום שעל הטחול אסור\u0004 באכילה, \u0003ואין חייבים\u0004 עונש כרת \u0003עליו,\u0004 על אכילתו, שאין זה כאוכל חלב. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה לקרום \u0003שעל הדד\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין חייבין עליו? אלא\u0004 צריך לומר שהכוונה לקרום \u0003דכוליה\u0004 \u0005[\u0006שמכסה \u0005את כולו],\u0006 ואין זה רק הקרום שעל הדד, הרי איפוא שאין לאכול את כל הקרום שעל הטחול. ולכך אמרתי לו שיסיר היטב את כל הקרום! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו של לוי לבנו: \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 ברייתא \u0005שכזו, הריהי\u0006 \u0005שנויה],\u0006 ובטלים דברי ר' ירמיה בר אבא מפני דברי הברייתא.","למעלה הובאו דברי הברייתא בדין הקרום שעל הטחול, ועתה דנים בה \u0003גופא\u0004 \u0005[לגופה,\u0006 עצמה\u0005].\u0006 \u0003אמר רב המנונא, תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: ה\u0003קרום שעל הטחול אסור\u0004 באכילה, \u0003ואין חייבין\u0004 כרת \u0003עליו,\u0004 על אכילתו. וכיוצא בדבר אף ה\u0003קרום שעל גבי כוליא\u0004 \u0005[כליה]\u0006 \u0003אסור\u0004 באכילה, \u0003ואין חייבין\u0004 כרת \u0003עליו.\u0004 \u0003ותוהים:\u0004 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם \u0005אכלו קרום שעל הטחול או קרום שעל הכליה\u0006 \u0003חייבין עליו!\u0004","ומשיבים: סתירה זו מדין קרום \u0003טחול\u0004 שבברייתא זו על דין קרום \u0003טחול\u0004 שבברייתא האחרת, \u0003לא קשיא\u0004 \u0005[לא קשה],\u0006 שכן יש לומר כי \u0003הא\u0004 \u0005[זו\u0006 הברייתא המחייבת על אכילת קרום הטחול\u0005]\u0006 מדברת בקרום ש\u0003כנגד הדד.\u0004 ואילו \u0003הא\u0004 \u0005[זו\u0006 הברייתא שאינה מחייבת על אכילת קרום הטחול\u0005]\u0006 מדברת בקרום הטחול \u0003שלא כנגד הדד.\u0004","וכן גם הסתירה שבין דין קרום \u0003כוליא\u0004 \u0005[כליה]\u0006 שבברייתא זו לבין דין קרום \u0003כוליא\u0004 \u0005[כליה]\u0006 שבברייתא האחרת, \u0003נמי לא קשיא\u0004 \u0005[גם כן לא קשה],\u0006 שכן יש לומר כי \u0003הא\u0004 \u0005[זו\u0006 הברייתא המחייבת על אכילת קרום כליה\u0005]\u0006 מדברת \u0003בעילאה\u0004 \u0005[ב\u0006קרום \u0005העליון\u0006 שבכליה\u0005].\u0006 ואילו \u0003הא\u0004 \u0005[זו\u0006 הברייתא שאינה מחייבת על אכילת קרום כליה\u0005]\u0006 מדברת \u0003בתתאה\u0004 \u0005[ב\u0006קרום \u0005התחתון\u0006 שבכליה\u0005].\u0006","למעלה הוזכר דין הקרום שעל ביצי הזכר, ובענין ביצים אלה שנינו \u0003ביעי חשילתא\u0004 \u0005[ביצי זכר]\u0006 הנמצאות בתוך כיס האשכים ונמעכו, ואולם עדיין הן מחוברות בחוטים שלהן לגוף הבהמה, ולאחר מכן נשחטה הבהמה, נחלקו בדבר \u0003רב אמי ורב אסי.\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר\u0004 אותם באכילה, \u0003וחד שרי\u0004 \u0005[ואחד\u0006 מהם \u0005התיר],\u0006 ומסבירים את טעמיהם: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר,\u0004"],["סבור כי \u0003מדלא קא בריין\u0004 \u0005[מכיון שאינן מבריאות,\u0006 שאין הביצים הללו מתפתחות\u0005]\u0006 לאחר שנמעכו, הרי זה מוכיח כי כאילו פרשו מגופה משנמעכו, וממילא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003אבר מן החי נינהו\u0004 \u0005[הן],\u0006 ולכך שחיטתה לא התירה אותם באכילה. והרי זה כשאר אבר שנלקח מן החי, שאסור באכילה. ואילו \u0003מאן דשרי\u0004 \u0005[מי שהתיר]\u0006 את הביצים באכילה, סבור כי \u0003מדלא קא מסרחן\u0004 \u0005[מכיון שאינן מסריחות],\u0006 הרי זה מוכיח כי \u0003הני חיותא אית בהו\u0004 \u0005[אלה חיות יש בהם],\u0006 שהריהן עדיין יונקות מהבהמה, ואינן נחשבות כאילו פרשו מן הבהמה ואינן בכלל איסור אבר מן החי ושחיטתן מתירתן.","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר,\u0006 האוסר\u0005],\u0006 מה הוא אומר על כך שאין הביצים מסריחות? ומשיבים: סבור הוא כי \u0003האי דלא קא מסרחן\u0004 \u0005[זה שהן לא מסריחות]\u0006 אין הוא משום שהן עדיין יונקות מהבהמה, אלא משום \u0003דלא קא שליט בהו אוירא\u0004 \u0005[שאין שולט בהן האויר]\u0006 הגורם לרקבונו ולסרחונו של דבר שנלקח מן החי, שהרי ביצים אלה נתונות בתוך כיס האשכים. ושואלים לצד האחר, \u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר\u0006 המתיר\u0005]\u0006 מה הוא משיב להוכחה מהעובדה שאין הביצים מתפתחות? ומשיבים: סבור הוא כי \u0003האי דלא בריין כחישותא הוא דנקט להו\u0004 \u0005[זה שאינן מתפתחות]\u0006 אינו משום שהן מנותקות מגוף הבהמה, אלא משום ש\u0003כחישותא\u0004 \u0005[רזון,\u0006 חולשה\u0005]\u0006 \u0003הוא דנקט להו\u0004 \u0005[שאחזה בהן].\u0006","ומביאים בענין ביצים אלה, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לרב שמן בר אבא: הני ביעי חשילתא שריין\u0004 \u0005[אותן ביצים המעוכות\u0006 הריהן \u0005מותרות]\u0006 באכילה, \u0003ו\u0004אולם \u0003את לא תיכול\u0004 \u0005[ואתה אל תאכל מהם]\u0006 \u0003משום \"ואל תטוש תורת אמך\"\u0004 (משלי א, ח), שכך הוא מנהג מקומך, שאתה בא מארץ בבל, ושם נוהגים איסור בהן.","ועוד בדיני ביצי בהמת זכר. \u0003אמר מר בר רב אשי: הני ביעי דגדיא\u0004 \u0005[אלה הביצים של גדי],\u0006 בפרק הזמן מלידתו של הגדי \u0003ו\u0004\u0003עד\u0004 שהוא מגיע להיות בן \u0003תלתין יומין\u0004 \u0005[שלושים יום]\u0006 — \u0003שריין\u0004 \u0005[מותרות]\u0006 הביצים אף \u0003בלא קליפה\u0004 של הקרום שעליהן, שכן בשלב זה של התפתחותו, עדיין אין בגדי כמות דם הנבלעת בקרום ביציו. ואולם \u0003מכאן ואילך, אי אזרען\u0004 \u0005[אם יש בהן זרע]\u0006 — הריהן \u0003אסורין, ואי לא אזרען\u0004 \u0005[ואם אין בהן זרע]\u0006 — הריהן \u0003שריין\u0004 \u0005[מותרות].\u0006 \u0003מנא ידעינן\u0004 \u0005[מנין יודעים אנו]\u0006 אם יש בהן זרע? — \u0003אי אית בהו שורייקי סומקי\u0004 \u0005[אם יש בהן גידים אדומים]\u0006 — סימן הוא שיש בהן זרע ו\u0003אסירן\u0004 \u0005[אסורות],\u0006 ואם \u0003לית בהו שורייקי סומקי\u0004 \u0005[אין בהן גידים אדומים]\u0006 — סימן הוא שאין בהן זרע ו\u0003שריין\u0004 \u0005[מותרות].\u0006","ומתוך שהובא למעלה בדינן של ביצים, מביאים כי בדינם של \u0003אומצי ביעי ומזרקי\u0004 \u0005[אומצות\u0006 בשר, חתיכות בשר חי שלא בושל, \u0005ביצי\u0006 בהמת זכר, \u0005ומזרקים,\u0006 ורידי הצוואר\u0005],\u0006 \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא.\u0004 ובטרם מציגים את הדעות החלוקות אומרים: \u0003בכל\u0004 דיני \u0003התורה כולה\u0004 שנחלקו בהם רב אחא ורבינא, ולא נתפרש מיהו המיקל ומיהו המחמיר במחלוקות הללו, דעת \u0003רבינא\u0004 היא \u0003לקולא\u0004 \u0005[להקל]\u0006 \u0003ו\u0004דעת \u0003רב אחא\u0004 היא \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 \u0003ו\u0004נקבעה \u0003הלכתא\u0004 \u0005[הלכה]\u0006 במחלוקות הללו \u0003כ\u0004דעת \u0003רבינא לקולא\u0004 \u0005[להקל],\u0006 \u0003לבר מהני תלת\u0004 \u0005[חוץ משלוש\u0006 מחלוקות \u0005אלה]\u0006 שבהן \u0003רב אחא\u0004 הוא זה שהולך בהן \u0003לקולא\u0004 \u0005[להקל]\u0006 \u0003ו\u0004אילו \u0003רבינא\u0004 הוא זה הולך בהן \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 \u0003ו\u0004נקבעה בהן \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב אחא לקולא\u0004 \u0005[להקל].\u0006","ומפרטים מהן שלוש מחלוקות אלה: \u0003אומצא דאסמיק\u0004 \u0005[חתיכת בשר חי שהאדימה]\u0006 מחמת מכה שהוכתה הבהמה בחייה במקום שממנו נלקחה האומצה, אם עמד ו\u0003חתכה\u0004 לאומצה זו לחתיכות רבות, \u0003ומלחה\u0004 — הרי המלח שאב את הדם ממנה, ומעתה \u0003אפילו ל\u0004תבשיל ב\u0003קדרה נמי שפיר דמי\u0004 \u0005[גם כן יפה הדבר,\u0006 מותר לעשות כן\u0005],\u0006 וכמו כן אם עמד ו\u0003תלייה נמי בשפודא\u0004 \u0005[תלה אותה גם כן בשיפוד]\u0006 בתוך התנור לצלותה, אף שלא חתכה לחתיכות, ולא מלחה אלא בשיעור מועט (כראוי לבשר הנצלה) — הריהי מותרת באכילה, שכן \u0003דאיב דמא\u0004 \u0005[זב הדם].\u0006 ואולם אם הניח אותה \u0003אגומרי\u0004 \u0005[על גחלים],\u0006 \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא.\u0004 ש\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהריהי מותרת לאכילה, שכן הגחלים \u0003משאב שאיבי ליה\u0004 \u0005[שואבים אותו,\u0006 את הדם\u0005]\u0006 והוא יוצא כולו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שאסורה, שכן הגחלים \u0003מצמת צמתי ליה\u0004 \u0005[מצמיתים,\u0006 מקרישות \u0005אותו,\u0006 את הדם\u0005],\u0006 והוא נשאר באומצה. \u0003וכן\u0004 נחלקו רב אחא ורבינא בדין \u0003ביעי\u0004 \u0005[ביצים],\u0006 \u0003וכן\u0004 נחלקו בדין \u0003מזרקי\u0004 \u0005[ורידי הצוואר].\u0006","מתוך שהוזכר למעלה דין האומצה הניתנת על הגחלים, מביאים דין דומה. \u0003רישא\u0004 \u0005[ראש\u0006 בהמה\u0005]\u0006 שרוצים להסיר את שערו, ולשם כך כובשים אותו \u0003בכיבשא\u0004 \u0005[ברמץ,\u0006 אפר חם\u0005],\u0006 אם \u0003אותביה\u0004 \u0005[הושיב אותו]\u0006 על \u0003בית\u0004 (מקום) \u0003השחיטה,\u0004 שהניח את ראש הבהמה באופן שמקום השחיטה שבראש נתון מלמטה — באופן זה \u0003דייב דמא ושרי\u0004 \u0005[זב הדם, ומותר].\u0006 ואם הניח את ראש הבהמה \u0003על ה\u0004\u0003צדדין\u0004 — באופן זה \u0003מיקפא קפי\u0004 \u0005[קופא,\u0006 נקרש\u0005]\u0006 הדם בתוך הראש, \u0003ואסור.\u0004 ואם \u0003אותביה אנחיריה\u0004 \u0005[הושיב אותו על נחיריו],\u0006 אם \u0003דץ ביה מידי\u0004 \u0005[נעץ בו דבר]\u0006 שלא ייסתמו — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 נעץ בו דבר — \u0003אסיר\u0004 \u0005[אסור].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 הלכה זו בנוסח אחר: אם הניח את ראש הבהמה באפר \u0003אנחיריה\u0004 \u0005[על הנחירים]\u0006 ועל \u0003בית השחיטה\u0004 — \u0003דאיב\u0004 \u0005[זב]\u0006 הדם, ומותר. ואם הניח אותו על ה\u0003צדדין, אי דץ ביה מידי\u0004 \u0005[אם נעץ בו דבר]\u0006 — הריהו \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — הריהו \u0003אסיר\u0004 \u0005[אסור].\u0006","ושבים לבירור דינו של גיד הנשה, כמובא למעלה (צא,א). \u0003אמר רב יהודה, אמר שמואל: שני גידין הן\u0004 בגיד הנשה, הגיד \u0003הפנימי\u0004 ה\u0003סמוך לעצם\u0004 — \u0003אסור\u0004 מן התורה, \u0003וחייבין\u0004 מלקות \u0003עליו,\u0004 על אכילתו. ואילו הגיד ה\u0003חיצון\u0004 ה\u0003סמוך לבשר\u0004 — \u0003אסור\u0004 באכילה, \u0003ו\u0004אולם \u0003אין חייבין עליו\u0004 מלקות.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 הגיד \u0003ה\u0004\u0003פנימי סמוך לבשר,\u0004 ושלא כדברי שמואל! \u0003אמר רב אחא, אמר רב כהנא:\u0004 הגיד הפנימי אכן סמוך לעצם, אך הוא חוזר ו\u0003איקלודי מיקליד\u0004 \u0005[חודר]\u0006 אל תוך הבשר.","ומוסיפים ומקשים על דברי שמואל בגיד החיצון שסמוך לבשר: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 כי הגיד \u0003ה\u0004\u0003חיצון\u0004 הוא זה \u0003הסמוך לעצם! אמר רב יהודה:\u0004 הברייתא מדברת \u0003היכא דפרעי טבחי\u0004 \u0005[במקום\u0006 הירך שבו חותכים ו\u0005חושפים הטבחים\u0006 את הגיד\u0005]\u0006 ששם הגיד החיצון הוא סמוך לעצם.","מתוך שהוזכר מנהג הטבחים המנקרים את הבהמה מן הדברים האסורים בה, מביאים עוד בענין זה. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003טבח שנמצא חלב אחריו,\u0004 שלאחר שהוציא את החלב, עדיין נותר חלב בבשר, \u0003רב יהודה אמר:\u0004 שיעור החלב שדנים את הטבח הוא \u0003בכשעורה. ר' יוחנן אמר:\u0004 שיעורו הוא \u0003בכזית.\u0004","\u0003אמר רב פפא: ולא פליגי\u0004 \u0005[ולא נחלקו\u0006 ביניהם רב יהודה ור' יוחנן\u0005],\u0006 אלא כל אחד אמר את דבריו לענין אחר. \u0003כי\u0004 \u0003כאן\u0004 שאמר ר' יוחנן ששיעורו בכזית, מדובר לענין \u0003להלקותו\u0004 לאותו טבח על רשלנותו. ואילו \u0003כאן\u0004 שאמר רב יהודה ששיעורו בכשעורה, הרי זה לענין \u0003לעברו\u0004 (להעבירו, להדיח את הטבח מתפקידו), שכיון שהתרשל מעבירים אותו ממלאכתו.","הסבר אחר בדבר: \u0003אמר מר זוטרא:\u0004 רב יהודה ור' יוחנן אינם חלוקים, וזה שאמר \u0003רב יהודה\u0004 \u0003כשעורה\u0004 — הכוונה היא שנמצא החלב דווקא \u0003במקום אחד.\u0004 וזה שאמר ר' יוחנן \u0003כזית\u0004 — הכוונה היא \u0003אפילו\u0004 היה מפוזר החלב \u0003בשנים ובשלשה מקומות.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: לענין \u0003להלקותו\u0004 — הרי זה דווקא \u0003ב\u0004חלב שיש בו שיעור \u0003כזית,\u0004 לענין \u0003לעברו\u0004 (להעבירו מתפקידו) — אפילו \u0003בכשעורה.\u0004","שנינו במשנתנו שלדעת ר' מאיר \u0003אין הטבחין נאמנין\u0004 על גיד הנשה, ולדעת חכמים הריהם נאמנים. \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: חזרו\u0004 אחר כך \u0003לומר\u0004 שלדעת הכל הטבחים \u0003נאמנין.\u0004","\u0003אמר רב נחמן\u0004 בתמיה: וכי \u0003אכשור דרי\u0004 \u0005[הוכשרו הדורות],\u0006 שדורות אחרונים נאמנים יותר מדורות ראשונים? ומשיבים: לא מטעם זה אלא \u0003מעיקרא דהוו סברי לה\u0004 \u0005[מתחילה שהיו סבורים]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 בברייתא המצריך לחטט אחר גיד הנשה היטב, ויש בדבר זה טירחה מרובה — \u0003לא הוו מהימני\u0004 \u0005[לא היו נאמנים]\u0006 הטבחים על גיד הנשה. \u0003ו\u0004אולם \u0003לבסוף סברי\u0004 \u0005[סברו]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 שאין צריך לחטט אחר גיד הנשה אלא די לגודעו (\"גוממו\"), ובדבר קטן זה אין לחשוד בטבחים שלא יעשוהו, ולכך האמינום.","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונים אותה\u0006 הלכה \u0005על סוף\u0006 משנתנו\u0005],\u0006 ששנינו בה: \u0003וחכמים אומרים נאמנין עליו,\u0004 על גיד הנשה, \u0003ועל החלב,\u0004 ועל כך \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: חזרו\u0004 חכמים \u0003לומר אין נאמנין. אמר רב נחמן\u0004 על כך: ואולם \u0003בזמן הזה נאמנין\u0004 הטבחים.","ותוהים: וכי \u0003אכשור דרי\u0004 \u0005[הוכשרו הדורות]?\u0006 ומשיבים: \u0003מעיקרא סברוה\u0004 \u0005[מתחילה\u0006 חכמים \u0005סברו]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה,\u0004 שאין צורך לחטט היטב היטב, ולכך האמינו לטבחים על כך. ואולם \u0003הדר סברוה\u0004 \u0005[חזרו\u0006 אחר כך ו\u0005סברו]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 המצריך לחטט אחר גיד הנשה.","וכל \u0003כמה דהוו דכירי לה\u0004 \u0005[זמן שהיו\u0006 הטבחים עדיין \u0005זוכרים אותה],\u0006 את שיטת \u0003ר' יהודה\u0004 ונהגו לפיה — \u0003לא מהימני\u0004 \u0005[לא היו נאמנים].\u0006 \u0003והשתא דאנשיוה\u0004 \u0005[ועכשיו ששכחוה]\u0006 את שיטת \u0003ר' יהודה\u0004 והמנהג הוא כשיטת ר' מאיר — הרי הם \u0003מהימני\u0004 \u0005[נאמנים].\u0006","למעלה הוזכר שלדעת חכמים במשנה הטבחים נאמנים על גיד הנשה \u0003ועל החלב.\u0004 ותוהים: \u0003חלב, מאן דכר שמיה\u0004 \u0005[מי הזכיר\u0006 את \u0005שמו].\u0006 שהרי לא הזכיר ר' מאיר בדבריו חלב! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 ר' מאיר, \u0005אמר],\u0006 כך יש לשנות: \u0003אין נאמנין עליו,\u0004 על גיד הנשה, \u0003ו\u0004כן אין נאמנים אף \u0003על החלב.\u0004 \u0003ו\u0004כנגד זה אמרה המשנה כי \u0003חכמים אומרים\u0004 ש\u0003נאמנין\u0004 הטבחים הן \u0003עליו ו\u0004הן \u0003על החלב.\u0004","אף שאסור אדם מישראל באכילת גיד הנשה, \u0003שולח\u0004 (מותר שישלח) \u0003אדם\u0004 מישראל \u0003ירך\u0004 שלימה של בהמה \u0003לגוי\u0004 כמתנה, אף על פי \u0003שגיד הנשה בתוכה\u0004 של ירך זו. ואין אנו חוששים שמא יחזור הגוי וימכרנה לאדם מישראל, ונמצא השולח לגוי מכשיל ישראל, \u0003מפני שמקומו\u0004 של גיד הנשה \u0003ניכר\u0004 הוא בירך. ואדם מישראל הקונה ירך מן הגוי הריהו רואה שלא ניטל ממנה גיד הנשה.","שנינו במשנתנו כי רשאי אדם מישראל לשלוח ירך בהמה לגוי, אף שגיד הנשה לא הוצא ממנה. ומן הלשון \"ירך\" שמשמעה — ירך שלימה, מדייקים: דווקא ירך \u0003שלמה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר לשלוח לגוי, בלא שהוציאו את גיד הנשה מתוכה, ואולם ירך \u0003חתוכה\u0004 שלא הוצא ממנה גיד הנשה — \u0003לא\u0004 הותר לשלוח לגוי. שיש לחשוש שמא יקנה ישראל מידי הגוי את הירך הזה, ויחשוב שהוצא גיד הנשה ממנה, ויבוא לכלל עבירה. ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003במקום ש\u0004בו כל השוחטים הם ישראליים, וכאשר מזדמנת להם בהמה טריפה \u0003אין\u0004 הם \u0003מכריזין\u0004 (מפרסמים) שמכרו באותו \u0003יום בשר טריפה לגוי — הרי במקום כזה אין בני ישראל לוקחים בשר מאת הגויים (שמא הוא בשר טריפה), ומעתה לא רק ירך שלימה מותר לשלוח לגוי, אלא אף\u0004"],["ירך \u0003חתוכה נמי\u0004 \u0005[גם כן]\u0006 יהיה מותר \u0003לישדר ליה\u0004 \u0005[לשלוח לו],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אתו למזבן מיניה\u0004 \u0005[לא יבואו\u0006 ישראלים \u0005לקנות ממנו]!\u0006 \u0003אלא\u0004 תאמר שמדובר \u0003במקום ש\u0004בו הטבחים \u0003מכריזין\u0004 בכל מקרה בו נמכר בשר טריפה לגויים, ומשום כך נוהגים בני ישראל לקנות בשר אצל הגויים (כשלא הוכרז על טריפה שניתנה לגויים) — לא רק ירך חתוכה אין לשלוח לגוי, אלא אף ירך \u0003שלימה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לישדר ליה\u0004 \u0005[לא ישלח לו],\u0006 שיש לחשוש \u0003דחתיך ליה ומזבין ליה\u0004 \u0005[ש\u0006הגוי \u0005יחתוך אותה,\u0006 את הירך עם הגיד שבה, \u0005וימכור אותה]\u0006 לישראלי, ולא יוכל הישראלי להבחין שלא ניטל ממנה הגיד, ויבוא לאוכלו!","ומשיבים באופנים שונים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר במשנתנו \u0003במקום ש\u0004בו \u0003מכריזין\u0004 הטבחים על מכירתו של בשר טריפה לגוי, ומדובר ביום שלא הכריזו על כך, וסימן הוא שלא נמכרה היום טריפה לגוי. ובאותו יום קונים בני ישראל בשר מאת הגוי. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שבמשנתנו מדובר \u0003במקום ש\u0004בו \u0003אין\u0004 הטבחים \u0003מכריזין\u0004 על בשר טריפה שנמכר לגוי, ושם אין בני ישראל קונים בשר מאת הגוי.","ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר במשנתנו \u0003במקום ש\u0004בו \u0003מכריזין\u0004 על מכירת בשר טריפה לגוי, והטעם שמותר לשלוח לגוי ירך שלימה ואין חוששים שיחתוך הגוי את הירך, ועלול ישראל להיכשל באכילת גיד הנשה — כיון ש\u0003חיתוכא\u0004 \u0005[החיתוך]\u0006 של ה\u0003גוי, מידע ידיע\u0004 \u0005[ידוע],\u0006 שניכר שהוא של גוי. ולכך אין מקום לחשש שיחתוך הגוי ולא יבחינו בכך בני ישראל.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר במשנתנו \u0003במקום ש\u0004בו \u0003אין מכריזין\u0004 על מכירת בשר טריפה לגוי, ובאותו מקום אין בני ישראל קונים בשר מן הגוי, ומשום כך מותר לשלוח להם ירך שלימה. וזה שאסרו לשלוח להם ירך חתוכה — הרי זו \u0003משום\u0004 \u0003גזירה\u0004 שגזרו חכמים בדבר, ומפני החשש \u0003שמא\u0004 בן ישראל \u0003יתננה לו\u0004 לגוי את הירך החתוכה \u0003בפני ישראל אחר,\u0004 וישראלי הרואה כן עלול לחשוב שאין זה בשר טריפה ויבוא לקנותה מן הגוי. ומאחר וזו היא ירך חתוכה, עלול הישראלי הקונה לחשוב שהוצא גיד הנשה מן הירך כראוי.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 בטעם הדבר שאסור לשלוח לגוי ירך חתוכה (במקום שבו אין מכריזים על מכירת בשר טריפה לגוי) — \u0003משום דקא גניב ליה לדעתיה\u0004 \u0005[שהוא\u0006 הישראלי \u0005גונב את דעתו\u0006 של הגוי\u0005],\u0006 שהגוי סבור שישראלי זה ששלח לו את הירך החתוכה עשה כן משום שהריהו מחבבו ביותר, עד שטרח וחתך את הירך כדי להוציא את גיד הנשה מתוכה, וראויה היתה ירך זו להיאכל על ידי השולח, ועמד ושלחה לגוי. ומתוך כך הגוי מחזיק לו טובה בחינם לישראל זה. שכן \u0003אמר שמואל: אסור לגנוב דעת הבריות, ו\u0004בכלל זה \u0003אפילו דעתו של גוי.\u0004","מתוך שהובאה דעת שמואל מרחיבים \u0003בה דברים\u0004 : \u0003והא\u0004 \u0005[ו\u0006הלכה \u0005זו]\u0006 של \u0003שמואל, לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה]\u0006 מפיו כהוראה מפורשת, \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 מעשה שהיה \u0005נאמרה].\u0006 שכן פעם אחת \u0003שמואל הוה קא עבר במברא\u0004 \u0005[היה עובר\u0006 את הנהר \u0005במעבורת],\u0006 \u0003אמר ליה לשמעיה\u0004 \u0005[לו\u0006 שמואל \u0005לשמשו]:\u0006 \u0003פייסיה, למבוריה\u0004 \u0005[פייס,\u0006 הנח דעתו בתשלום הוגן, \u0005את בעל המעבורת],\u0006 עמד השמש ו\u0003פייסיה ואיקפד\u0004 \u0005[פייס אותו, והקפיד\u0006 על כך שמואל\u0005].\u0006","ושואלים: \u0003מאי טעמא איקפד\u0004 \u0005[מה הטעם הקפיד]\u0006 שמואל על כך? \u0003אמר אביי: תרנגולת טרפה הואי\u0004 \u0005[היתה]\u0006 זו שנתן השמש לבעל המעבורת בשכרו, \u0003ויהבה ניהליה במר\u0004 \u0005[ונתן אותה לו כמו היתה זו]\u0006 תרנגולת \u0003שחוטה,\u0004 ונמצא שגנב את דעתו של הגוי, ועל כך הקפיד שמואל. \u0003רבא אמר\u0004 כי סיבת הדבר ששמואל הקפיד על השמש היתה משום ששמואל ב\u0003אנפקא\u0004 \u0005[כלי המשמש לשתייית יין חי]\u0006 \u0003אמר ליה לאשקויי\u0004 \u0005[לו להשקותו\u0006 את בעל המעבורת\u0005],\u0006 \u0003ו\u0004אילו \u0003הוא\u0004 \u0003אשקייה חמרא מזיגא\u0004 \u0005[השקה אותו יין מזוג],\u0006 ועל גניבת דעת זו הקפיד שמואל.","ושואלים: \u0003וכי מכללא מאי\u0004 \u0005[ואם מכלל\u0006 מעשה \u0005הובן שזו דעת שמואל,\u0006 \u0005מה\u0006 בכך\u0005]?\u0006 והלא על כל פנים למדים אנו כי דעתו של שמואל שאסור לגנוב את דעת הבריות, ואף זו של הגוי! ומסבירים: מאחר ולא אמר שמואל כן במפורש — אין זו הוראה גמורה, כי ניתן לפרש את הקפדתו של שמואל על שמשו מטעם אחר: \u0003למאן דאמר טרפה הואי\u0004 \u0005[ל\u0006דעת \u0005מי שאמר\u0006 כי תרנגולת \u0005טריפה היתה]\u0006 זו שניתנה לבעל המעבורת\u0005,\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לשמש בהקפדה: \u0003אמאי תשהא איסורא\u0004 \u0005[מדוע אתה משהה\u0006 ברשותך \u0005דבר\u0006 \u0005איסור\u0006 כתרנגולת טריפה זו\u0005],\u0006 שאפשר להיכשל בו?","ו\u0003למאן דאמר אנפקא אמר ליה לאשקויי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 כי \u0005אנפקא אמר לו להשקות],\u0006 ואילו הוא השקה אותו יין מזוג \u0003— הקפיד עליו שמואל, משום שכאשר הוא הורה לו להשקות את בעל המעבורת\u0004 \"אנפקא\", \u0003אנפקא חייא משמע\u0004 \u0005[יין חי משמע]\u0006 דבריו היה, ולא יין מזוג, והקפיד עליו שמואל על שעבר על דבריו.","מתוך שהובא למעלה איסור גניבת דעת, מביאים עוד בענין זה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: אל יסרהב\u0004 (יפציר) \u0003אדם לחבירו לסעוד אצלו, ו\u0004כשהוא \u0003יודע בו\u0004 בחבירו \u0003שאינו סועד\u0004 אצלו. שהרי זו גניבת דעת, שחבירו סבור שהוא מזמינו בכנות, ולאמיתו של דבר לא התכוון לכך. \u0003ו\u0004בדומה לכך \u0003לא ירבה לו בתקרובת\u0004 (מתנות) \u0003ו\u0004כשהוא \u0003יודע בו שאינו מקבל\u0004 מתנות.","\u0003ו\u0004בדומה לכך, \u0003לא יפתח לו\u0004 לאורח הסועד אצלו \u0003חביות המכורות\u0004 כבר \u0003לחנוני.\u0004 שכן האורח סבור כי המארח פתח את חבית היין לכבודו, ואין פותחים חבית חדשה אלא לכבודו של אורח חשוב (שכן יין משובח הוא זה הבא מחבית שעתה נפתחה. ומשעה שנפתחת חבית היין, היין שבה הולך ומאבד את ערכו). ולאמיתו של דבר לא פתח המארח את החבית אלא משום שהריהו עומד להעבירה אל החנווני, המוכר יין בחנותו. \u0003אלא אם כן הודיעו\u0004 שהוא פותח את החבית בין כה וכה, עבור החנווני. \u0003ו\u0004בדומה לכך, \u0003לא יאמר לו\u0004 לאורחו \u0003\"סוך שמן\",\u0004 בזמן שיודע שהאורח לא יסוך מהפך שלפניו, אם היה זה \u0003פך ריקן\u0004 משמן. \u0003ו\u0004אולם \u0003אם\u0004 המארח עשה כן, לא על מנת שיחזיק לו האורח טובה על כך, אלא \u0003בשביל כבודו\u0004 של האורח, שמראה בכך שנחשב הוא בעיני מארחו — \u0003מותר\u0004 הדבר.","ושואלים על מה ששנינו שאין פותחים לאורח חבית חדשה המכורה לחנווני: \u0003איני\u0004 \u0005[האמנם כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עולא איקלע לבי\u0004 \u0005[נזדמן לבית]\u0006 \u0003רב יהודה, פתח לו חביות המכורות לחנוני!\u0004 ומשיבים: \u0003רב יהודה\u0004 \u0003אודועי אודעיה\u0004 \u0005[הודיע לו\u0006 לעולא\u0005]\u0006 שחביות אלה הינן מכורות לחנווני. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003עולא\u0004 מסתם אורח, שכן \u0003חביב ליה\u0004 \u0005[עליו]\u0006 על \u0003רב יהודה, דבלאו הכי נמי פתוחי מפתח ליה\u0004 \u0005[שבלי זה,\u0006 שהחביות היו מכורות לחנווני, \u0005גם כן היה פותח לו\u0006 חבית חדשה\u0005],\u0006 ואם כן לא הטעה אותו.","ומביאים עוד מענין הטעיית הבריות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לא ילך אדם לבית האבל, ובידו לגין\u0004 (כד) \u0003המתקשקש,\u0004 שאינו מלא יין, ואולם האבל סבור שלגין זה מלא יין. \u0003ולא ימלאנו\u0004 לאותו לגין ב\u0003מים, מפני שמתעהו\u0004 את האבל הסבור שלגין יין הביא. אבל \u0003אם יש שם חבר עיר\u0004 (ציבור, קבוצה גדולה של אנשים), וכוונת מביא הלגין לכבד את האבל, שיראו אנשים כי מכובד האבל בעיני המביא — \u0003מותר\u0004 הדבר. ועוד מענין הטעיית הבריות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא ימכור אדם לחבירו סנדל\u0004 העשוי מעור \u0003של\u0004 בהמה \u0003ש\u0004\u0003מתה\u0004 מעצמה, ולא נשחטה, \u0003בכלל\u0004 (בתור) סנדל העשוי מעור \u0003של\u0004 בהמה \u0003חיה שחוטה,\u0004 שעור בהמה שמתה מעצמה גרוע מעור בהמה בריאה שנשחטה. וטעם האיסור, \u0003מפני שני דברים: אחד\u0004 — \u0003מפני שמתעהו,\u0004 שכן \u0003סבור הקונה\u0004","\u0003שהסנדל עשוי מעור משובח, ולמעשה הריהו מקבל סנדל העשוי מעור פחות.\u0004 \u0003ואחד\u0004 — \u0003מפני הסכנה,\u0004 שמא מתה הבהמה מחמת נשיכת נחש, והארס חלחל אל העור שממנו נעשה הסנדל. \u0003ו\u0004כן \u0003לא ישגר\u0004 (ישלח) \u0003אדם לחבירו חבית של יין ושמן צף על פיה,\u0004 ויהיה המקבל סבור שיש בידו חבית שמן. \u0003ו\u0004מספרים כי אכן היה \u0003מעשה ב\u0004אדם \u0003אחד ששיגר לחבירו חבית של יין ושמן צף על פיה,\u0004 וחשב המקבל שיש בידו חבית שמן, \u0003והלך וזימן עליה\u0004 (על סמך זה) \u0003אורחין\u0004 לסעודה. \u0003ו\u0004כיון ש\u0003נכנסו\u0004 האורחים הלך אותו אדם לקחת שמן מאותה חבית, ו\u0003מצאה שהיא של יין. ו\u0004מרוב בושה שאין בידו לתת לאורחים שזימן לסעודתו, עמד ו\u0003חנק את עצמו\u0004 למוות.","\u0003ו\u0004עוד אמרו חכמים כי על מנת שלא לגרום לבעל הבית בושה, \u0003אין האורחין רשאין ליתן ממה שלפניהם לבנו ולבתו של בעל הבית, אלא אם כן נטלו רשות מבעל הבית\u0004 לעשות כן.","\u0003ומעשה\u0004 היה \u0003ב\u0004אדם \u0003אחד שזמן\u0004 לביתו לסעודה \u0003שלשה אורחין,\u0004 והיה הדבר \u0003בשני\u0004 (בשנות) \u0003בצורת,\u0004 ומועטים היו מזונותיו. \u0003ולא היה לו להניח לפניהם אלא כשלש ביצים. בא בנו של בעל הבית, נטל אחד מהן\u0004 מן האורחים את \u0003חלקו ונתנו לו, וכן\u0004 עשה האורח ה\u0003שני, וכן\u0004 עשה האורח ה\u0003שלישי.\u0004 כיון ש\u0003בא אביו של\u0004 אותו \u0003תינוק, מצאו שעוזק\u0004 (מחזיק) \u0003אחד בפיו ושתים בידו,\u0004 כעס האב על הבן ו\u0003חבטו בקרקע, ומת. כיון שראתה אמו\u0004 שנהרג בנה בידי בעלה, \u0003עלתה לגג ונפלה ומתה, אף הוא\u0004 שראה כי מתו בנו ואשתו,","\u0003עלה לגג ונפל ומת. אמר ר' אליעזר בן יעקב: על דבר זה\u0004 (שנתנו האורחים ממזונם לבנו של המארח, בלא קבלת רשות ממנו) \u0003נהרגו שלש נפשות מישראל!\u0004 ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' אליעזר בן יעקב, \u0005השמיע לנו]\u0006 בכך, והרי הדברים מפורשים לפנינו? ומשיבים: דבריו אלה באו להורות \u0003דכולה\u0004 \u0005[שכולה,\u0006 כל הברייתא\u0005],\u0006 דעת \u0003ר' אליעזר בן יעקב היא.\u0004","ועוד בענין שליחת ירך. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השולח ירך לחבירו,\u0004 אם היתה הירך \u0003שלימה\u0004 לגמרי — השולח \u0003אינו צריך שיטול הימנה\u0004 (ממנה) את \u0003גיד הנשה,\u0004 שהרי המקבל רואה שלא ניטל ממנה גיד הנשה. ואם היתה הירך \u0003חתוכה\u0004 — השולח \u0003צריך ליטול הימנה\u0004 את \u0003גיד הנשה,\u0004 מפני שהמקבל עלול להניח שכבר ניטל גיד הנשה מהירך, ויבוא לאכילת גיד הנשה. \u0003וב\u0004אשר לשליחת ירך ל\u0003גוי, בין\u0004 שהיתה \u0003חתוכה ובין שלימה\u0004 — \u0003אין צריך ליטול הימנה גיד הנשה.\u0004","\u0003ומפני שני דברים אמרו\u0004 חכמים ש\u0003אין מוכרין\u0004 בשר בהמות \u0003נבילות וטרפות לגוי\u0004 בלא להודיעו שבשר זה אינו כשר: \u0003אחד\u0004 — \u0003מפני שמתעהו,\u0004 שכן חושב הגוי שהבשר כשר, והרי בשר כשר עדיף מבשר נבילה וטריפה. \u0003ואחד\u0004 — \u0003שמא יחזור\u0004 הגוי \u0003וימכרנה לישראל אחר. ו\u0004כן","\u0003לא יאמר אדם לגוי \"קח\u0004 (קנה) \u0003לי בדינר זה\u0004 שאני נותן לך \u0003בשר\", מפני שני דברים:\u0004"],["טעם \u0003אחד\u0004 — \u0003מפני האנסין,\u0004 שמא אותו גוי יקח את הדינר לעצמו, ויכריח את מוכר הבשר לתת לו בשר בלא תשלום. \u0003ו\u0004עוד טעם \u0003אחד\u0004 — \u0003שמא\u0004 מוכרי הבשר \u0003מוכרין לו\u0004 לגוי זה בשר \u0003נבלות וטרפות\u0004 שברשותם, שהרי אינם יודעים שהוא שליח של ישראל, ויביאם למשלח, ויכשילו באכילת איסור.","ודנים בברייתא זו, \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 \u0003וב\u0004זמן ששולח אדם מישראל ירך ל\u0003גוי, בין\u0004 שהיא \u0003שלימה בין\u0004 שהיא \u0003חתוכה\u0004 — \u0003אינו צריך ליטול הימנה\u0004 (ממנה) \u0003גיד הנשה.\u0004 ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה אופן, \u0005עוסקים אנו]\u0006 בהלכה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003במקום ש\u0004בו \u0003מכריזין\u0004 הקצבים הישראלים שהיום נמכר בשר בהמה נבלה וטרפה לגויים. ובמקום כזה קונים היהודים בשר מן הגויים, אלא אם כן הוכרז באותו יום שנמכר לגויים בשר אסור — ירך \u0003חתוכה אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו צריך ליטול הימנה גיד הנשה?\u0004 והרי \u0003כיון דלא אכרוז\u0004 \u0005[שלא הכריזו]\u0006 היום שנמכר לגויים בשר האסור באכילה, \u0003אתי למיזבן מיניה\u0004 \u0005[יבואו\u0006 היהודים \u0005לקנות ממנו,\u0006 מהגוי\u0005],\u0006 שיחשבו כי מירך חתוכה זו שקנה ניטל גיד הנשה, ויבואו לאוכלה!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר בברייתא זו \u0003במקום ש\u0004בו \u0003אין מכריזין\u0004 על מכירת בשר אסור לגויים. ובמקום \u0003כזה אין היהודים קונים מן הגויים\u0004 — \u0003אימא מציעתא\u0004 \u0005[אמור\u0006 את ההלכה \u0005האמצעית\u0006 שבברייתא\u0005]:\u0006 \u0003מפני שני דברים אמרו\u0004 ש\u0003אין מוכרין נבלות וטרפות לגוי: אחד, מפני שמטעהו. ואחד, שמא יחזור וימכרנה לישראל אחר. ו\u0004אולם","\u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003במקום ש\u0004בו \u0003אין מכריזין\u0004 על מכירת בשר אסור לגויים — \u0003הא לא אתי למיזבן מיניה\u0004 \u0005[הרי לא יבואו לקנות ממנו]!\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003במקום שמכריזין.\u0004","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של הברייתא: \u0003לא יאמר אדם לגוי \"קח\u0004 (קנה) \u0003לי בדינר זה בשר\" מפני שני דברים, אחד\u0004 — \u0003מפני האנסין, ואחד\u0004 — \u0003שמא מוכרין לו נבילות וטרפות, ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003במקום שמכריזין, אי איתא דהוה\u0004 \u0005[אם אמנם היה\u0006 מקרה \u0005שהיתה]\u0006 \u0003טרפה\u0004 — \u0003אכרוזי הוו מכרזי\u0004 \u0005[היו מכריזים\u0006 על כך\u0005]!\u0006","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003במקום שאין מכריזין,\u0004 ונמצא אם כן שאתה מעמיד את \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 של הברייתא \u0003במקום שאין מכריזין,\u0004 ואילו את \u0003מציעתא\u0004 \u0005[האמצעית]\u0006 \u0003במקום שמכריזין!\u0004","\u0003אמר אביי: אין\u0004 \u0005[כן],\u0006 באמת כך צריך להעמיד, \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 \u0003במקום שאין מכריזין, מציעתא\u0004 \u0005[האמצעית]\u0006 \u0003במקום שמכריזין.\u0004","ואילו \u0003רבא אמר:\u0004 הברייתא \u0003כולה\u0004 מדברת \u0003במקום שמכריזין, רישא וסיפא\u0004 \u0005[בהתחלה ובסוף]\u0006 מדובר באופן \u0003שהכריזו, מציעתא\u0004 \u0005[באמצעית]\u0006 מדובר במקום שמכריזים אבל במקרה זה \u0003לא הכריזו.\u0004","ואילו \u0003רב אשי אמר: כולה\u0004 מדברת \u0003במקום שאין מכריזין,\u0004 \u0003ומציעתא\u0004 \u0005[והאמצעית]\u0006 האומרת שאסור למכור לגוי אינה מעיקר הדין, אלא \u0003גזירה שמא ימכרנה בפני ישראל.\u0004","למעלה דובר על ההכרזה שמכריזים אם נמכרה טריפה לגוי, ועתה מבררים: \u0003היכי מכרזינן\u0004 \u0005[איך,\u0006 באיזו לשון, \u0005מכריזים]?\u0006 \u0003אמר רב יצחק בר יוסף,\u0004 אומרים: \u0003נפל בישרא לבני חילא\u0004 \u0005[נפל בשר לבני העיר],\u0006 שבא לידינו בשר עבור הגוים.","\u0003ולימא נפל טריפתא לבני חילא\u0004 \u0005[ושיאמרו נפלה טריפה לבני העיר\u0006 הגוים\u0005]!\u0006 ומשיבים: אם יכריזו בלשון זו \u0003לא זבני\u0004 \u0005[לא יקנו],\u0006 הגוים בשר זה, מפני שבזוי בעיניהם לאכול דבר שאין ישראל רוצים לאכול.","ושואלים: \u0003והא קמטעי להו\u0004 \u0005[והרי\u0006 באופן הכרזה זה שהצענו, \u0005הוא מטעה אותם,\u0006 את הגוים, \u0005בכך],\u0006 שאין הם יודעים שזהו בשר טריפה? ומשיבים: \u0003אינהו הוא דקמטעו נפשייהו\u0004 \u0005[הם שמטעים את עצמם],\u0006 שהרי אינו אומר להם איזה בשר הוא מוכר. ומביאים ראיה שאין זו נחשבת הטעיה,","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה],\u0006 ש\u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן הוה קאזיל\u0004 \u0005[היה הולך]\u0006 \u0003מ\u0004העיר \u0003סיכרא\u0004 שבבבל \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003מחוזא, ו\u0004באותה עת \u0003רבא ורב ספרא הוו קא אתו\u0004 \u0005[היו הולכים]\u0006 \u0003ל\u0004עיר \u0003סיכרא, פגעו אהדדי\u0004 \u0005[פגשו זה את זה].\u0006 \u0003הוא,\u0004 מר זוטרא, \u0003סבר\u0004 \u0005[סבור היה]\u0006 כי רבא ורב ספרא \u0003לאפיה\u0004 \u0005[לקדם פניו]\u0006 \u0003הוא דקאתו\u0004 \u0005[שהם באו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003למה להו לרבנן דטרוח ואתו כולי האי\u0004 \u0005[מדוע להם לחכמים שטרחו ובאו כל כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא: אנן לא הוה ידעינן דקאתי מר\u0004 \u0005[אנו לא ידענו שאדוני בא].\u0006 \u0003אי הוה ידעינן, טפי הוה טרחינן\u0004 \u0005[אם היינו יודעים, יותר היינו טורחים].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב ספרא: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמרת ליה הכי\u0004 \u0005[לו כך],\u0006 \u0003דאחלישתיה לדעתיה\u0004 \u0005[ש\u0006הרי \u0005החלשת את דעתו],\u0006 שהודעת לו שלא באנו לקבל את פניו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא לרבא בתשובה: \u0003והא\u0004 \u0005[והרי]\u0006 אילו לא הייתי מספר שלא יצאנו כדי לקבל את פניו \u0003קא מטעינן ליה\u0004 \u0005[אנו\u0006 נמצאים ש\u0005מטעים אותו]!\u0006 אמר לו רבא לרב ספרא: אין זה נחשב שאנו מטעים אותו, שכן \u0003איהו הוא דקא מטעי נפשיה\u0004 \u0005[הוא\u0006 זה \u0005שמטעה עצמו].\u0006","ומביאים עוד בענין מכירת נבילות וטריפות לגוי, ובמקום שמכריזים בו כשנמכרת טריפה לגוי. מסופר: \u0003ההוא טבחא\u0004 \u0005[שוחט אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006"],["\u0003אי הוות פייסת מינאי\u0004 \u0005[אם היית מתפייס איתי,\u0006 עושה עמי שלום\u0005],\u0006 \u0003מי לא ספיי\u0004 \u0005[האם לא הייתי מאכיל]\u0006 \u0003לך\u0004 נתח \u0003משור של פטם\u0004 (בהמה שהואכלה לשם השמנתה, שבשרה משובח ביותר), \u0003דעבדי\u0004 \u0005[שעשיתי,\u0006 ששחטתי\u0005]\u0006 \u0003אתמול? אמר ליה\u0004 \u0005[לו]\u0006 אותו חבר בתשובה: אף שלא השלמתי אתך, בכל זאת \u0003אכלי\u0004 \u0005[אכלתי]\u0006 מבשר שור זה, ולא עוד אלא שהיה זה \u0003משופרי שופרי\u0004 \u0005[מ\u0006חלק \u0005היפה יפה\u0006 שבאותו שור\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 השוחט: \u0003מנלך\u0004 \u0005[מנין\u0006 הגיע \u0005אליך]\u0006 בשר זה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 חבירו: הרי זה ממה \u0003דזבן\u0004 \u0005[שקנה]\u0006 \u0003פלוני גוי, וספא\u0004 \u0005[ונתן]\u0006 \u0003לי. אמר ליה\u0004 \u0005[לו]\u0006 השוחט: \u0003תרי עבדי\u0004 \u0005[שני\u0006 שוורים של פטם \u0005עשיתי,\u0006 שחטתי\u0005]\u0006 אתמול, \u0003וההוא\u0004 \u0005[ואותו]\u0006 שור שקנה הגוי \u0003טרפה הוה\u0004 \u0005[היה].\u0006","וכשבא מעשה לפני רבי, \u0003אמר רבי:\u0004 האם \u0003בשביל\u0004 מעשה שהיה בשוחט \u0003שוטה זה שעשה שלא כהוגן\u0004 (שמכר בשר טריפה לגוי, וגרם להכשיל את חבירו באכילת בשר אסור), \u0003אנו\u0004 נקום ו\u0003נאסור\u0004 לקנות בשר היום מ\u0003כל המקולין\u0004 (האיטליזים) של הגויים שבעירו של שוחט זה, שרוב השוחטים בעיר הינם יהודים?!","ומסבירים: בכך הולך \u0003רבי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר\u0004 רבי: \u0003מקולין\u0004 הנמצאים בעיר, \u0003וטבחי\u0004 (שוחטי) \u0003ישראל\u0004 מתעסקים בהם, ה\u0003בשר הנמצא ביד גוי\u0004 באיטליזים אלה, כיון שקונה אותו מן השוחטים, ואולם הוא עצמו לא שחטו — הריהו \u0003מותר\u0004 באכילה. שכן הולכים אנו אחר רוב השוחטים שהינם ישראליים. ואין אנו חוששים לטריפה — שאילו היתה טריפה יוצאת מתחת ידי השוחט הישראלי, לא היה מוכרה לגוי כדי שימכרנה באיטליז.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 שכך \u0003אמר רבי:\u0004 האם \u0003מפני שוטה זה דאיכוון לצעוריה לחבריה\u0004 \u0005[שהתכוון\u0006 בדבריו \u0005לצער את חבירו]\u0006 על שלא עשה עמו שלום, \u0003אנו נאסור\u0004 את \u0003כל\u0004 הבשר \u0003ה\u0004נמצא ב\u0003מקולין?!\u0004 שהרי ודאי שיקר אותו שוחט, ולא כך היו הדברים.","ונדייק מנוסח זה של דברי רבי: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין אנו אוסרים היום את הבשר הנמצא באיטליזים שבעיר, משום שאנו מניחים \u0003דאיכוון לצעוריה לחבריה\u0004 \u0005[שהתכוון לצער את חבירו],\u0006 ושקר בפיו. ומכאן נסיק: \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא היה כן],\u0006 שלא התכוין לצער את חבירו, היה הבשר \u0003אסור.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: מקולין\u0004 הנמצאים בעיר \u0003וטבחי ישראל\u0004 מתעסקים בהם, \u0003בשר הנמצא ביד גוי\u0004 — \u0003מותר,\u0004 ומעתה, מאחר שבחזקת היתר עומד הבשר שבאיטליזים, מדוע \u0003נאסור אותו בשל גוי אחד שקנה בשר טריפה. שאין מקרה אחד סיבה לאסור היום את כל הבשר שבעיר!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן,\u0006 בזמן שידוע לנו שקנה גוי בשר טריפה\u0005],\u0006 \u0003דאיתחזק איסורא\u0004 \u0005[ש\u0006כן \u0005הוחזק איסור\u0006 טריפה\u0005],\u0006 בעקבות דברי שוחט זה, ומעתה יש לחשוש שכשם שמכר בשר טריפה לגוי זה כן מכר בשר טריפה לגויים רבים אחרים.","מתוך שהובאו למעלה דברי רבי בברייתא בדין בשר הנמצא בידי גוי, מביאים דברים הנוגעים לברייתא זו. \u0003אמר רב: בשר, כיון שנתעלם מן העין,\u0004 שלא השגיחו עליו — הריהו \u0003אסור\u0004 באכילה, שמא נתחלף בבשר טריפה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, \u0003רבי אומר: מקולין וטבחי ישראל, בשר הנמצא ביד גוי\u0004 — הריהו \u0003מותר,\u0004 אף שבהיותו \u0003אצל גוי הריהו כנתעלם מן העין!\u0004 ודוחים: כאשר \u0003נמצא\u0004 הבשר \u0003ביד גוי שאני\u0004 \u0005[שונה]\u0006 מבשר סתם שהתעלם מן העין. שהרי שמור היה הבשר בידי הגוי, מה שאין כן בבשר שלא הושגח כלל, שיש מקום לחשש שמא הוחלף.","ודנים עוד בדברי רב אלה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שלא כשיטתך ממה ששנינו בברייתא: היו בעיר \u0003תשע חנויות\u0004 ש\u0003כולן מוכרות בשר שחוטה\u0004 (בשר כשר), \u0003ו\u0004עוד חנות \u0003אחת\u0004 העשירית \u0003ה\u0004\u0003מוכרת בשר נבלה, ולקח\u0004 (קנה) בשר \u0003מאחת מהן, ואינו יודע מאיזה מהן לקח\u0004 — \u0003ספקו אסור.\u0004 \u0003וב\u0004בשר ה\u0003נמצא\u0004 בעיר זו — \u0003הלך\u0004 (לך) \u0003אחר הרוב,\u0004 והריהו כשר. והרי זה שלא כשיטת רב, שהרי הבשר בטרם נמצא היה במצב של התעלם מן העין! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אין המדובר בבשר שלא היה תחת השגחת אדם, אלא \u0003ב\u0004בשר ה\u0003נמצא ביד גוי.\u0004","ומביאים עוד ראיה, שלא כשיטת רב, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: עיר שגרים בה ישראלים וגויים, ו\u0003מצא בה בשר (אם\u0004 הבשר עדיין \u0003חי,\u0004 שלא נתבשל\u0003)\u0004 — \u0003הלך אחר רוב טבחים\u0004 (שוחטים) בעיר, שאם רובם ישראלים — הבשר מותר. \u0003ואם\u0004 הבשר הנמצא הינו \u0003מבושל\u0004 — \u0003הלך אחר רוב אוכלי בשר\u0004 שבעיר, שאם רוב תושבי העיר האוכלים בשר הינם גויים, הבשר אסור באכילה, אף שרוב השוחטים הינם ישראלים. שיש לחשוש שנאסר (אפילו בשר כשר) בבישול גוי. ומכל מקום שנינו שיש אופן שמותר הבשר הנמצא אף שהתעלם מן העין, ושלא כשיטת רב!","ומוסיפים: \u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כאן גם כן]\u0006 מדובר \u0003ב\u0004בשר ה\u0003נמצא ביד גוי,\u0004 ולא בבשר שהתעלם מן העין — אין לומר כן, שהרי אם כן מדוע בבשר \u0003מבושל הלך אחר רוב אוכלי בשר? ונחזי אי דגוי נקיט ליה\u0004 \u0005[ונראה אם גוי מחזיק אותו],\u0006 \u0003אי דישראל נקיט ליה\u0004 \u0005[אם ישראל מחזיק אותו]!\u0006 ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]:\u0006 שמוצא הבשר היה \u0003עומד ורואהו\u0004 את הבשר המבושל כשנפל מתחת ידי אדם מסויים, ואין זה בכלל בשר שנתעלם מן העין. ואולם אין הרואה יודע אם אותו אדם הוא ישראלי או גוי, ולכך נזקקים אנו לקביעה על פי רוב אוכלי הבשר שבעיר.","ומביאים עוד ראיה שלא כשיטת רב, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: אם \u0003נמצא\u0004 בשר \u0003בגבולין\u0004 (בערי ישראל, שמחוץ לירושלים), אם היה הבשר מפורק ל\u0003אברים\u0004 — יש לחשוש שהריהם \u0003נבלות,\u0004 ואם היה הבשר חתוך ל\u0003חתיכות\u0004 הראויות לאכילה — הרי אלה \u0003מותרות,\u0004 שבוודאי חתכו רק דבר המותר. ושלא כשיטת רב האוסר בשר שהתעלם מן העין! \u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כאן גם כן]\u0006 מדובר \u0003בעומד ורואהו,\u0004 וכדרך שתירצנו למעלה — אין אתה יכול לומר כן, שהרי שנינו במשנה זו כי אם היה הבשר מפורק ל\u0003אברים\u0004 — הריהם \u0003נבלות,\u0004 ואם מדובר כשראה העומד שנפל הבשר מתחת ידי אדם, \u0003אמאי\u0004 \u0005[מדוע]\u0006 ייאסר הבשר?","ודוחים: \u0003מידי הוא טעמא\u0004 \u0005[וכי נאמר הדבר,\u0006 שאלה זו\u0005]\u0006 \u0003אלא ל\u0004שיטת \u0003רב,\u0004 ואולם \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה]\u0006 על אותה משנה עצמה. \u0003רב אמר:\u0004 הגרסה צריכה להיות \"חתיכות \u0003מותרות משום נבלה\",\u0004 שאין הן מטמאות בטומאת נבילה, ואין לוקים על אכילתן, ואולם הן אסורות משום בשר שהתעלם מן העין. \u0003ו\u0004בעקבות הדיון בשיטת רב, מביאים כי החכם \u0003לוי\u0004 חלק על רב, והוא \u0003אמר\u0004 כי חתיכות אלה אף \u0003מותרות באכילה.\u0004 ומעתה אין מקום להקשות מדברי המשנה על שיטת רב, שיתכן שדעת התנא במשנה כדעת לוי.","למעלה הובאו דברי רב בדין בשר שנתעלם מן העין, \u0003ו\u0004בעיקרם של דברים \u0003אומרים\u0004 : \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב, לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמרה]\u0006 מפיו, \u0003אלא מכללא אתמר\u0004 \u0005[מכלל\u0006 דבריו \u0005נאמרה],\u0006 שכן מסופר כי \u0003רב הוה יתיב אמברא\u0004 \u0005[היה יושב על המעבורת]\u0006 של המקום \u0003אישתטית, חזיא לההוא גברא דהוה קא\u0004 \u0005[ראה אדם אחד שהיה]\u0006"],["\u0003מחוור רישא\u0004 \u0005[מנקה ראש]\u0006 של בהמה, ששטף אותו במי הנהר. \u0003נפל\u0004 הראש \u0003מיניה\u0004 \u0005[ממנו]\u0006 אל תוך הנהר, \u0003אזל אייתי סילתא\u0004 \u0005[הלך\u0006 אותו אדם \u0005והביא סל]\u0006 כדי להוציא באמצעותו את ראש הבהמה שנפל. \u0003שדא אסיק תרין\u0004 \u0005[השליך\u0006 אותו אדם את הסל אל תוך המים ו\u0005העלה\u0006 עם הסל \u0005שני\u0006 ראשי בהמה\u0005].\u0006 \u0003אמר רב:\u0004 וכי \u0003עבדי נמי הכי\u0004 \u0005[עשויים\u0006 הדברים להיות \u0005גם כן כך],\u0006 האם כך הוא הדבר הרגיל, שאדם מאבד חפץ אחד ומוצא במקומו שנים? אם כן יתכן שאף לא אחד מהם הוא זה שנפל מידיו למים. ולכך עמד ו\u0003אסרינהו ניהליה\u0004 \u0005[אסר אותם עליו].\u0006","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב\u0004 בשאלה: מדוע ייאסרו שני הראשים הללו, שהרי אף אם לא אחד מהם הוא זה שנפל מידיו, מכל מקום וכי דווקא ראשי בהמה \u0003דאיסורא שכיחי\u0004 \u0005[של איסור מצויים],\u0006 ואילו ראשי בהמה \u0003דהתירא לא שכיחי\u0004 \u0005[של היתר אין מצויים],\u0006 ושמא \u0005אלה הם ראשי בהמה של היתר!\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב בתשובה: יש לאסור את הראשים הללו, משום שראשי בהמה \u0003דאיסורא שכיחי טפי\u0004 \u0005[של איסור מצויים יותר]\u0006 מראשי בהמה של היתר. ומכאן מסיקים שרב סבור שבשר שהתעלם מן העין אסור באכילה, שמא עורבים הביאו את הבשר הזה, שהינו אסור, ממקום אחר.","ושואלים: \u0003וכי\u0004 \u0005[ואם]\u0006 אמנם לא אמר רב את הדבר במפורש, אלא שלמדים אנו את שיטתו זו \u0003מכללא\u0004 \u0005[מכלל]\u0006 מעשה שהיה, \u0003מאי\u0004 \u0005[מה]\u0006 בכך, הרי על כל פנים יש ללמוד מכאן שזו היא שיטת רב. ומשיבים: משום שאין לסמוך על אותו מעשה כמקור להלכה כללית בבשר שהתעלם מן העין, שאסור אף במקום שבו רוב השוחטים ישראלים. שכן המקום בו אירע מעשה זה, \u0003פרוותא\u0004 \u0005[הנמל]\u0006 של \u0003גוים הואי\u0004 \u0005[היה],\u0006 ואולי דווקא באופן זה אסר רב, ואינו סבור כך במקום שיש בו רוב ישראל. ומביאים ראיה לדבר: \u0003תדע\u0004 שכן הוא, \u0003דקאמר להו\u0004 \u0005[ש\u0006הרי \u0005הוא אמר להם,\u0006 לרב כהנא ורב אסי\u0005]:\u0006 ראשי בהמה \u0003דאיסורא שכיחי טפי\u0004 \u0005[של איסור מצויים יותר]\u0006 מראשי בהמה של היתר, והרי זה מורה שמדובר במקום שיש בו רוב גויים.","ושואלים: \u0003אלא רב,\u0004 האוסר בכל מקרה שבו לא הושגח הבשר אפילו זמן קצר ביותר, \u0003היכי\u0004 \u0005[כיצד]\u0006 אם כן \u0003אכל\u0004 רב \u0003בשרא\u0004 \u0005[בשר]\u0006 מימיו? ומשיבים: רב לא אכל בשר אלא \u0003בשעתיה\u0004 \u0005[בשעתו],\u0006 מיד לאחר שנשחט, באופן זה \u0003דלא עלים עיניה מיניה\u0004 \u0005[שלא העלים עינו ממנו]\u0006 מן השחיטה ועד לאחר שהוכן לאכילה, ואז אכלו. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 רב היה אוכל בשר רק \u0003ב\u0004אופן שהוא \u0003ציירא וחתומא\u0004 \u0005[צרור וחתום],\u0006 שמובטח שלא הוחלף. \u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 באופן זה היה רב אוכל בשר: \u0003ב\u0004זמן שהיה בבשר \u0003סימנא\u0004 \u0005[סימן]\u0006 המלמד שהוא אותו בשר שנשחט, ולא הוחלף בבשר אחר. \u0003כי הא\u0004 \u0005[כמו\u0006 דרך \u0005זו]\u0006 ש\u0003רבה בר רב הונא\u0004 היה \u0003מחתך ליה\u0004 \u0005[אותו],\u0006 את הבשר ששלח לידי אשתו בידי גוים, \u0003אתלת קרנתא\u0004 \u0005[בשלש זויות,\u0006 משולש\u0005],\u0006 בדרך המיוחדת לו, וכך הבטיח שתמיד ניתן יהיה לזהות את הבשר כבשר שנשלח על ידו.","ועוד מהנהגות רב באכילת בשר שהתעלם מן העין. מסופר כי \u0003רב הוה קאזיל לבי\u0004 \u0005[היה הולך לבית]\u0006 \u0003רב חנן חתניה\u0004 \u0005[חתנו],\u0006 \u0003חזי מברא דקאתי לאפיה\u0004 \u0005[ראה מעבורת שהולכת לקראתו],\u0006 \u0003אמר: מברא קאתי לאפי, יומא טבא לגו\u0004 \u0005[מעבורת הריהי באה לקראתי,\u0006 אף שלא הזמנתיה, הרי זה סימן כי \u0005יום טוב,\u0006 סעודה גדולה, מזומנת לנו \u0005בפנים].\u0006","\u0003אזל, קם אבבא\u0004 \u0005[הלך\u0006 רב, \u0005עמד על שער\u0006 ביתו של חתנו\u0005],\u0006 \u0003אודיק בבזעא דדשא\u0004 \u0005[הסתכל דרך סדק שבדלת]\u0006 אל תוך הבית, ו\u0003חזי חיותא דתליא\u0004 \u0005[ראה בהמה שתלויה,\u0006 שמוכנה לבישול\u0005],\u0006 \u0003טרף אבבא\u0004 \u0005[דפק\u0006 רב \u0005על השער],\u0006 \u0003נפוק אתו כולי עלמא לאפיה\u0004 \u0005[יצאו הכל לקראתו],\u0006 \u0003אתא טבחי נמי\u0004 \u0005[באו הטבחים גם כן]\u0006 לקראתו, \u0003לא עלים\u0004 \u0005[העלים]\u0006 \u0003רב עיניה מיניה\u0004 \u0005[עינו ממנו]\u0006 מן הבהמה, והסתכל בה כל הזמן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכו השתא\u0004 \u0005[איך\u0006 שנהגתם \u0005עכשיו],\u0006 שהסרתם את עיניכם מהבהמה, כי אז \u0003ספיתו להו איסורא\u0004 \u0005[הייתם מאכילים\u0006 דבר \u0005איסור]\u0006 \u0003לבני ברת\u0004 \u0005[בתי],\u0006 לבניו של רב חנן חתנו. ומספרים כי \u0003לא אכל רב מההוא בישרא\u0004 \u0005[מאותו בשר].\u0006","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא אכל? \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום איעלומי\u0004 \u0005[העלמת\u0006 עין\u0005]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא איעלים\u0004 \u0005[לא נעלם]\u0006 בשר זה מן העין, שהרי רב הסתכל בו. \u0003אלא\u0004 מפני \u0003דנחיש\u0004 \u0005[שניחש]\u0006 רב בענין הזה, כסימן בבוא המעבורת, ולכך קנס את עצמו בכך שלא לאכול מן הבשר, אף שמותר היה.","ותוהים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 כי \u0003כל נחש\u0004 (ניחוש) \u0003שאינו\u0004 סומך עליו ממש, \u0003כ\u0004דרך שנהג \u0003אליעזר עבד אברהם\u0004 בלכתו להביא אשה ליצחק אבינו (בראשית כד, יד), בסימן שעשה לו שהנערה שתשאב מים עבורו ועבור גמליו מן הבאר, היא זו שתהיה ליצחק לאשה. \u0003וכ\u0004סימן שעשה \u0003יונתן בן שאול\u0004 עבורו ועבור נערו במלחמתו עם מחנה הפלשתים במעבר מכמש (שמואל א יד, ט—י), באופן בו יאמרו אליהם השומרים לכשיחשפו לפניהם. שסמך על כך לתוקפם, למרות מספרם הרב, \u0003אינו נחש.\u0004 והרי רב לא סמך ממש על ניחוש זה של בוא המעבורת! ומשיבים: \u0003אלא\u0004 הטעם שלא אכל רב מסעודה זו, שכן \u0003סעודת הרשות הואי\u0004 \u0005[היתה],\u0006 זו, \u0003ורב לא מתהני\u0004 \u0005[לא נהנה]\u0006 \u0003מסעודת הרשות,\u0004 שלא היה \u0003אוכל אלא בסעודת מצוה.\u0004","מתוך שהובא למעלה סימן שנתן רב בבוא המעבורת, מביאים עוד בענין זה. \u0003רב בדיק במברא\u0004 \u0005[היה בודק,\u0006 מנחש אם להמשיך בדרכו \u0005במעבורת],\u0006 שאם היתה המעבורת מזומנת לו בקלות \u0003—\u0004 היה מפליג בה. \u0003ו\u0004\u0003מביאים עוד מהנהגות חכמים בדרך על פיה היו בודקים דברים:\u0004 \u0003שמואל בדיק בספרא\u0004 \u0005[היה בודק בספר],\u0006 שהיה פותח את הספר לדעת על פיו מה מזדמן לו. \u0003ר' יוחנן בדיק בינוקא\u0004 \u0005[היה בודק בתינוק]\u0006 שהיה שואל תינוק מהו הפסוק שלמד, ולפיו היה קובע.","ובענין זה מסופר כי \u0003כולהו שני\u0004 \u0005[כל שנות]\u0006 \u0003רב,\u0004 כגדול התורה שבארץ בבל, \u0003הוה כתב ליה\u0004 \u0005[היה כותב לו]\u0006 \u0003ר' יוחנן\u0004 במכתביו: \u0003לקדם\u0004 \u0005[לכבוד]\u0006 \u0003רבינו שבבבל. כי נח נפשיה\u0004 \u0005[כאשר נפטר]\u0006 רב, \u0003הוה כתב\u0004 \u0005[היה\u0006 ר' \u0005יוחנן\u0006 \u0005כותב]\u0006 \u0003לשמואל: לקדם\u0004 \u0005[לכבוד]\u0006 \u0003חבירינו שבבבל. אמר\u0004 שמואל: וכי \u0003לא ידע\u0004 \u0005[אין ידוע]\u0006 \u0003לי מידי\u0004 \u0005[דבר],\u0006 שאני יודעו ור' יוחנן אינו יודעו, שמפני כך \u0003רביה אנא\u0004 \u0005[רבו אני]?\u0006 עמד שמואל ו\u0003כתב שדר ליה עיבורא דשיתין שני\u0004 \u0005[שלח לו\u0006 לר' יוחנן, חשבון \u0005עיבור ששים השנים הבאות].\u0006 \u0003אמר\u0004 ר' יוחנן: \u0003השתא, חושבנא בעלמא ידע\u0004 \u0005[עכשיו,\u0006 רואה אני כי \u0005חשבון בלבד\u0006 הוא \u0005יודע],\u0006 ואולם אין בכך כדי שייחשב לרבי.","חזר שמואל ו\u0003כתב שדר ליה תליסר גמלי\u0004 \u0005[שלח לו\u0006 לר' יוחנן, \u0005שלושה עשר גמלים]\u0006 טעונים ב\u0003ספקי טריפתא\u0004 \u0005[טריפות],\u0006 התפעל ר' יוחנן ו\u0003אמר: אית\u0004 \u0005[יש]\u0006 \u0003לי רב בבבל, איזיל איחזייה\u0004 \u0005[אלך ואראה אותו].\u0006 ברם לפני שעשה כן, עמד ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לינוקא\u0004 \u0005[לתינוק]:\u0006 \u0003פסוק לי\u0004 את \u0003פסוקיך\u0004 שאותו אתה לומד היום! \u0003אמר ליה\u0004 \u0005[לו]\u0006 התינוק את הפסוק: \u0003\"ושמואל מת\"\u0004 (שמואל א כח, ג) \u0003אמר\u0004 ר' יוחנן: \u0003שמע מינה נח נפשיה\u0004 \u0005[למד מכאן\u0006 כי \u0005נפטר]\u0006 \u0003שמואל,\u0004 ולכן לא נסע.","ואומרים: \u0003ולא היא\u0004 (לא כך היה), שבאמת באותה עת \u0003לא שכיב\u0004 \u0005[לא נפטר]\u0006 עדיין \u0003שמואל, אלא\u0004 נזדמן פסוק זה לפני ר' יוחנן, \u0003כי היכי דלא ליטרח\u0004 \u0005[כדי שלא יטרח]\u0006 \u0003ר' יוחנן\u0004 בנסיעה ארוכה וקשה לבבל.","ועוד בענין ניחוש, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 מי שהצליח (או הפסיד) בסחורה הראשונה לאחר שבנה \u0003בית,\u0004 או לאחר שנולד לו \u0003תינוק, ו\u0004לאחר שנשא לו \u0003אשה\u0004 — בכל אלה, \u0003אף על פי שאין נחש,\u0004 שאסור לנחש, מכל מקום \u0003יש\u0004 בכך משום סתם \u0003סימן.\u0004 שאם הצליח — סימן לו שהריהו הולך ומצליח, ואם לא הצליח — הרי זה סימן לו שלא ירבה לצאת בסחורה.","\u0003אמר ר' אלעזר\u0004 בהגדרת דברי ר' שמעון בן אלעזר: \u0003והוא\u0004 (אין המדובר אלא) בזמן \u0003דאיתחזק תלתא זימני\u0004 \u0005[שהוחזק\u0006 הדבר \u0005שלוש פעמים]\u0006 שרק אז יש בדבר משום סימן. וראיה לדבר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי יעקב אבינו \u0003\"יוסף איננו ושמעון איננו ואת בנימין תקחו\u0004 עלי היו כולנה\" (בראשית מב, לו), שכן אם ילקח בנימין ממנו, הרי אלה שלוש צרות, ויוחזק בכך בסימן לא טוב.","ושבים לבירור שיטת רב בדין בשר שהתעלם מן העין. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב הונא מרב:\u0004 בשר שהיה \u0003בחרוזין,\u0004 שהיו חתיכות הבשר חרוזות במחרוזת אחת, ולזמן מסוים התעלם הבשר מן העין ושב ונמצא, \u0003מהו\u0004 דינו, האם אף זה בכלל בשר שהתעלם מן העין, שאסור? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003אל תהי שוטה\u0004 בשאלה זו, שהרי ודאי שבשר \u0003בחרוזין הרי זה סימן. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 הלכה זו באופן שונה, שכך \u0003אמר רב הונא אמר רב:\u0004 בשר \u0003בחרוזין הרי זה סימן.\u0004","ועוד בענין בשר שהתעלם מן העין, מסופר: \u0003רב נחמן מנהרדעא איקלע לגבי\u0004 \u0005[הזדמן אצל]\u0006 \u0003רב כהנא\u0004 בעיר \u0003פום נהרא במעלי יומא דכפורי\u0004 \u0005[בערב יום הכיפורים],\u0006 שמרבים בו באכילת בשר. \u0003אתו עורבי שדו כבדי וכוליתא\u0004 \u0005[באו עורבים\u0006 ו\u0005השליכו\u0006 ארצה \u0005כבדים וכליות],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב נחמן: \u0003שקול\u0004 \u0005[קח]\u0006 \u0003ואכול\u0004 מהכבדים והכליות הללו, שאין אלה אסורים משום בשר שהתעלם מן העין, שכן \u0003האידנא דהיתרא שכיח טפי\u0004 \u0005[עכשיו,\u0006 בערב יום הכיפורים, בשר \u0005של היתר מצוי יותר]\u0006 מבשר של איסור, שהיהודים מרבים לשחוט.","ועוד מסופר ש\u0003רב חייא בר אבין איתבד ליה כרכשא בי דנא\u0004 \u0005[אבדו לו מעיים\u0006 של בהמה \u0005בין חביות\u0006 היין\u0005].\u0006 חיפש ומצא בין החביות מעי בהמה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב הונא\u0004 לשאול מה דין הבשר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סימנא בגויה\u0004 \u0005[סימן בו]\u0006 שעל פיו תדע שזהו הבשר שאבד לך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 חזר רב הונא ושאלו: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך טביעות עינא בגויה\u0004 \u0005[טביעת עין בו]\u0006 שתכיר אותו כבשר שלך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אמר לו: \u0003אם כן, זיל שקול\u0004 \u0005[לך קח]\u0006 אותו לאכילה, שאפשר לסמוך בענין זה על טביעות עין.","ועוד מסופר: \u0003רב חנינא חוזאה איתבד ליה גבא דבשרא\u0004 \u0005[אבד לו גב של בשר],\u0006 ולאחר מכן נמצא אותו בשר. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן\u0004 לשאול מה דין הבשר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סימנא בגויה\u0004 \u0005[יש לך סימן בו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 חזר ושאלו רב נחמן: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך טביעות עינא בגויה\u0004 \u0005[טביעת עין בו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אמר לו רב נחמן: \u0003אם כן, זיל שקול\u0004 \u0005[לך קח]\u0006 בשר זה לאכילתך.","וכן מסופר ב\u0003רב נתן בר אביי\u0004 ש\u0003איתבד ליה קיבורא דתכלתא\u0004 \u0005[אבדה לו פקעת של\u0006 חוטי \u0005תכלת\u0006 לציצית\u0005],\u0006 ולאחר מכן חזרה ונמצאה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא,\u0004 לשאול אם החוטים הללו כשרים לציצית, או שיש לחשוש שמא הם חוטים אחרים שאינם כשרים לציצית. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סימנא בגויה\u0004 \u0005[סימן בו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 חזר רב חסדא ושאל: האם \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך טביעות עינא בגויה\u0004 \u0005[טביעת עין בו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אמר לו רב חסדא: \u0003אם כן, זיל שקול\u0004 \u0005[לך קח]\u0006 אותם להשתמש בהם לציצית.","בסיפורים שהובאו למעלה דובר על סימנים שיש בדבר שאבד, ועל טביעות עין שיש בו. ובענין זה \u0003אמר רבא: מרישא הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 \u0003כי\u0004 \u0003סימנא\u0004 \u0005[סימן]\u0006 \u0003עדיף מטביעות עינא\u0004 \u0005[עין],\u0006 \u0003דהא מהדרינן אבידתא בסימנא\u0004 \u0005[שהרי אנו מחזירים אבידה בסימן],\u0006"],["\u0003ולא מהדרינן\u0004 \u0005[ואין אנו מחזירים]\u0006 אבידה \u0003ב\u0004הסתמך על \u0003טביעות עינא\u0004 \u0005[עין]\u0006 של בעל האבידה המזהה אותה כשלו. ואולם \u0003השתא דשמעתינהו להני שמעתתא\u0004 \u0005[עכשיו ששמעתי את\u0006 כל \u0005השמועות הללו],\u0006 שלא היה לבעלי האבידה סימן בדבר, אלא טביעת עין בלבד, ובכל זאת הותרו להם הדברים שאבדו להם, אף שהיה חשש איסור בהם, \u0003אמינא\u0004 \u0005[אומר אני]:\u0006 \u0003טביעות עינא עדיפא\u0004 \u0005[טביעת עין עדיפה]\u0006 מסימנים.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 \u0003היאך\u0004 (איך) \u0003סומא\u0004 (עיור) \u0003מותר ב\u0004תשמיש המיטה עם \u0003אשתו,\u0004 והלא יש לחשוש שמא זו היא אשה אחרת? \u0003ו\u0004אף \u0003בני\u0004 ה\u0003אדם\u0004 הרואים, \u0003איך\u0004 הם \u0003מותרין ב\u0004תשמיש המיטה עם \u0003נשותיהן בלילה,\u0004 בזמן שאינם רואים? \u0003אלא\u0004 יש לומר כי הותר הדבר \u0003ב\u0004הסתמך על \u0003טביעות עינא דקלא\u0004 \u0005[טביעת עין,\u0006 הכרה \u0005של הקול].\u0006 \u0003הכא נמי בטביעות עינא\u0004 \u0005[כאן,\u0006 בשמועות הללו, שהותרו דברים שיש בהם חשש איסור, \u0005גם כן\u0006 הרי זה \u0005ב\u0006הסתמך על \u0005טביעת עין].\u0006","\u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: תדע\u0004 שכך הוא, שטביעת עין עדיפה על סימנים, שכן \u0003אילו אתו בתרי ואמרי\u0004 \u0005[יבואו שנים\u0006 עדים \u0005ויאמרו]\u0006 לפני בית הדין כי \u0003פלניא, דהאי סימניה והאי סימניה, קטל נפשא\u0004 \u0005[פלוני, שזה סימנו וזה סימנו, הרג נפש]\u0006 — \u0003לא קטלינן ליה\u0004 \u0005[אין אנו הורגים אותו],\u0006 שאין בסימניו כדי לזהותו בשלמות. \u0003ו\u0004אולם \u0003אילו אמרי\u0004 \u0005[אומרים]\u0006 כי מזהים אנו שכן \u0003אית לן\u0004 \u0005[יש לנו]\u0006 \u0003טביעות עינא בגויה\u0004 \u0005[טביעת עין בו]\u0006 — על סמך עדות זו \u0003קטלינן ליה\u0004 \u0005[הורגים אנו אותו].\u0006","וכן \u0003אמר רב אשי\u0004 ראיה שטביעת עין עדיפה על סימנים: \u0003תדע,\u0004 ש\u0003אילו אמר ליה איניש לשלוחיה\u0004 \u0005[לו אדם לשלוחו]:\u0006 \u0003קרייה לפלניא, דהאי סימניה והאי סימניה\u0004 \u0005[קרא\u0006 אלי \u0005את פלוני, שזה סימנו וזה סימנו]\u0006 — \u0003ספק ידע ליה\u0004 \u0005[מכיר,\u0006 מזהה, \u0005אותו]\u0006 השליח בכך, \u0003ספק לא ידע ליה\u0004 \u0005[אין מכיר אותו],\u0006 \u0003ואילו\u0004 כאשר \u0003אית ליה טביעות עינא בגויה\u0004 \u0005[יש לו טביעת עין בו]\u0006 — \u0003כי חזי ליה, ידע ליה\u0004 \u0005[כאשר רואה אותו, מכיר אותו].\u0006","\u0003הנוטל\u0004 את \u0003גיד הנשה\u0004 מן הירך, \u0003צריך\u0004 שיחטט היטב בכל מקום בירך שבו נמצא הגיד, עד \u0003שיטול את\u0004 הגיד \u0003כולו.\u0004 \u0003ר' יהודה אומר:\u0004 אין צורך לחטט אחר הגיד, אלא די בחיתוכו מלמעלה, בחלק שעל כף הירך \u0003כדי לקיים בו\u0004 בכך \u0003מצות נטילה\u0004 של גיד הנשה.","\u0003האוכל מגיד הנשה\u0004 שיעור \u0003כזית\u0004 — \u0003סופג\u0004 (לוקה) \u0003ארבעים\u0004 (חסר אחת) מלקות, ככל העובר על איסור תורה. \u0003אכלו\u0004 את גיד הנשה כולו, \u0003ו\u0004אולם \u0003אין בו\u0004 בגיד זה כולו שיעור \u0003כזית,\u0004 וכגון שבא מבהמה קטנה ביותר — \u0003חייב\u0004 מלקות על כך. שכן גיד הנשה השלם נחשב בריה בפני עצמה, שחייבים על אכילתה אף בשיעור הקטן מכזית. היו לפניו שני גידי הנשה, של ירך ימין ושל ירך שמאל, ו\u0003אכל מזה\u0004 שיעור \u0003כזית ומזה\u0004 שיעור \u0003כזית\u0004 — \u0003סופג שמונים\u0004 (שתי סדרות מלקות, שכל אחת בת ארבעים חסר אחת). \u0003ר' יהודה אומר: אינו סופג אלא\u0004 סדרה אחת של \u0003ארבעים\u0004 מלקות, על אכילת גיד הנשה של ירך ימין ולא על אכילת הגיד של ירך שמאל.","שנינו במשנתנו שלדעת חכמים יש ליטול את כל גיד הנשה, ואילו לדעת ר' יהודה די בנטילת החלק שעל כף הירך. ובענין זה מסופר כי אדם בשם \u0003בר פיולי הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 החכם \u0003שמואל,\u0004 להכין לו סעודה, \u0003וקא מנקר אטמא\u0004 \u0005[והיה מנקר\u0006 את \u0005הירך].\u0006 ולא היה מחטט אחר גיד הנשה, אלא \u0003הוה קא גאים ליה\u0004 \u0005[היה חותך אותה],\u0006 ממה שעל כף הירך, וכשיטת ר' יהודה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003חות ביה טפי\u0004 \u0005[הכנס בו\u0006 בירך \u0005יותר],\u0006 וחטט כדי להוציא את כל גיד הנשה, \u0003השתא\u0004 \u0005[עתה]\u0006 אם \u0003לא חזיתך\u0004 \u0005[ראיתיך]\u0006 כיצד אתה נוטל את גיד הנשה, כי אז \u0003ספיתא\u0004 \u0005[היית מאכיל]\u0006 \u0003לי איסורא\u0004 \u0005[איסור]!\u0006","\u0003אירתת\u0004 \u0005[נפחד]\u0006 בר פיולי זה מפני נזיפתו של שמואל, ו\u0003נפל סכינא מידיה\u0004 \u0005[סכין\u0006 הניקור \u0005מידו]\u0006 מרוב פחדו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003לא תירתת\u0004 \u0005[אל תפחד],\u0006 שכן אין אני חושד בכך שהינך עם הארץ (הנוהג כן מחוסר ידיעה) או רשע (הנוהג כן מתוך רשעותו), וודאי הינך נוהג כדרך שהורו לך. אולם אותו חכם \u0003דאורי\u0004 \u0005[שהורה]\u0006 \u0003לך\u0004 לנהוג כן \u0003—\u0004 \u0003כ\u0004שיטת \u0003ר' יהודה אורי\u0004 \u0005[הורה]\u0006 \u0003לך,\u0004 ואין אני פוסק כן.","ובהסבר הדברים \u0003אמר רב ששת: מאי דשקל\u0004 \u0005[מה שנטל,\u0006 חתך\u0005]\u0006 \u0003בר פיולי\u0004 היה אותו חלק גיד הנשה שחייבים מ\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 ליטלו, \u0003ל\u0004דעת \u0003ר' יהודה.\u0004 ותוהים על דבריו: \u0003מכלל\u0004 הדברים נלמד שאותו חלק ש\u0003שייר\u0004 בר פיולי ולא נטלו, חייבים ליטלו מ\u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 אף \u0003ל\u0004דעת \u0003ר' יהודה. אלא\u0004 מעתה, זה \u0003דאורי ליה\u0004 \u0005[שהורה לו,\u0006 לבר פיולי\u0005]\u0006 לנהוג כפי שנהג, \u0003כמאן אורי ליה\u0004 \u0005[כמי הורה לו],\u0006 שהרי אף לדעת ר' יהודה חייבים למעשה ליטול את הכל!","\u0003אלא\u0004 יש לתקן את נוסח הדברים, שכך \u0003אמר רב ששת: מאי דשקל\u0004 \u0005[מה שנטל]\u0006 \u0003בר פיולי\u0004 היה חלק גיד הנשה שחייבים ליטלו מ\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 לדעת הכל, חכמים ור' יהודה. \u0003ומאי\u0004 \u0005[ומה]\u0006 ש\u0003שייר\u0004 בר פיולי, הוא אותו חלק גיד הנשה שחייבים מ\u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 ליטלו, \u0003ל\u0004שיטתם של חכמים במשנתנו, שהיא דעת \u0003ר' מאיר\u0004 (כמובא בברייתא לעיל צב,ב), ולא לשיטת ר' יהודה. \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 כשיטת \u0003ר' יהודה\u0004 — \u0003אפילו מדרבנן, שרי\u0004 \u0005[מדברי חכמים, מותר].\u0006","עוד שנינו במשנה כי \u0003האוכל מגיד הנשה\u0004 שיעור כזית הריהו לוקה על כך. וכן האוכל גיד הנשה שלם, אף שאין בו כשיעור כזית, הריהו לוקה על כך. ובענין זה מביאים מה ש\u0003אמר שמואל: לא אסרה תורה\u0004 באכילת גיד הנשה \u0003אלא\u0004 את החלק \u0003ש\u0004נמצא \u0003על הכף בלבד, ש\u0004כן \u0003נאמר\u0004 באיסור גיד הנשה: \"על כן לא יאכלו בני ישראל את גיד הנשה אשר \u0003על כף הירך\u0004 עד היום הזה\" (בראשית לב, לב).","\u0003אמר רב פפא:\u0004 דברי שמואל אלה שנויים \u0003כ\u0004מחלוקתם של \u0003תנאי\u0004 \u0005[תנאים].\u0006 שכך שנינו: אם \u0003אכלו\u0004 את גיד הנשה בשלימותו, \u0003ואין בו\u0004 שיעור \u0003כזית\u0004 — \u0003חייב\u0004 מלקות על כך. \u0003ר' יהודה אומר:\u0004 אין האוכל גיד הנשה חייב \u0003עד שיהא בו\u0004 שיעור \u0003כזית.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 — גיד הנשה \u0003בריה היא,\u0004 ומכיון שכך, הרי אכילתו נחשבת, אף שאין בה שיעור כזית."],["\u0003ו\u0004אילו \u0003ר' יהודה\u0004 הפוטר אכילה שכזו ממלקות, סבור לשון \u0003אכילה כתיבה ביה\u0004 \u0005[כתובה בו,\u0006 באיסור גיד הנשה\u0005],\u0006 ואין אכילה נחשבת בפחות מכזית. \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם משיבים על דבריו אלה של ר' יהודה? \u0003ההיא\u0004 \u0005[אותה]\u0006 לשון \u0003אכילה\u0004 שנאמרה בגיד הנשה, באה ללמד על מקרה מיוחד, \u0003דכי אית ביה\u0004 \u0005[שכאשר יש בו,\u0006 בגיד הנשה\u0005]\u0006 \u0005שיעור\u0006 \u0003ארבעה וחמשה זיתים, ואכל\u0004 מהם \u0003חד כזית\u0004 \u0005[כזית אחד]\u0006 בלבד — הריהו \u0003מיחייב\u0004 \u0005[חייב]\u0006 על כך. אבל כשיש בגיד הנשה כולו פחות מכזית, הריהו חייב אף על אכילתו של זה.","ושבים ושואלים: \u0003ור' יהודה,\u0004 שדרש מלשון אכילה האמורה בגיד הנשה לענין שיעור כזית, מנין לו שחייבים על אכילת כזית אחד, בגיד הנשה שיש בו ארבעה וחמישה זיתים? ומשיבים: הלכה זו \u0003מ\u0004הכתוב \u0003\"אשר על כף הירך\"\u0004 (בראשית לב, לב) \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005].\u0006","ושבים ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו הלכה זו מלשון אכילה, מה למדים הם מהכתוב \"אשר על כף הירך\"? ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לכ\u0004 דברי \u0003שמואל.\u0004 שכן \u0003אמר שמואל: לא אסרה תורה\u0004 בגיד הנשה \u0003אלא\u0004 זה \u0003שעל כף הירך.\u0004 ושואלים: \u0003ו\u0004לדעת \u0003ר' יהודה\u0004 שלמד מהכתוב \"אשר על כף הירך\" דרשה אחרת, מנין לו דברי שמואל? ומשיבים: לדעת ר' יהודה גיד הנשה שבכל הירך אסור, שלא כשיטת שמואל, שהרי \u0003\"הירך\" כתיב\u0004 \u0005[נאמר],\u0006 והרי זה מורה שהגיד שב\u0003כולה\u0004 של ה\u0003ירך\u0004 הריהי אסור.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים כדברי שמואל, כיצד הם מפרשים את הכתוב \"הירך\"? ומשיבים: הכתוב \u0003ההוא\u0004 בא להורות שמדובר בגיד \u0003דפשיט איסוריה בכוליה ירך\u0004 \u0005[שפושט איסורו בכל הירך],\u0006 והרי זה הגיד הפנימי, ו\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 את הגיד ה\u0003חיצון\u0004 הקצר, ש\u0003לא\u0004 אסור. \u0003ולעולם\u0004 לא נאסר גיד הנשה אלא בחלק \u0003שעל הכף.\u0004 הרי איפוא שמחלוקת תנאים היא בדברי שמואל.","ושואלים: למדנו למעלה שהן חכמים והן ר' יהודה דרשו מן הכתוב \"אשר על הכף\", \u0003ו\u0004אולם הלא \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"כף\" מיבעי ליה למעוטי\u0004 \u0005[נצרך לו למעט]\u0006 \u0003עוף\u0004 מאיסור גיד הנשה, \u0003דלית ליה\u0004 \u0005[ש\u0006כן \u0005אין לו]\u0006 \u0003כף!\u0004 ומשיבים: \u0003תרי\u0004 \u0005[שתי פעמים]\u0006 \u0003\"כף\" כתיבי\u0004 \u0005[כתובות].\u0006 באיסור גיד הנשה (\"על כן לא יאכלו בני ישראל את גיד הנשה אשר על כף הירך עד היום הזה כי נגע בכף ירך יעקב בהאבקו עמו\"), ללמד על שני אלה.","\u0003ירך ש\u0004לא ניטל ממנה גיד הנשה, וכשנתבשלה בקדירה \u0003נתבשל בה\u0004 עמה \u0003גיד הנשה, אם יש\u0004 בירך כשיעור שגיד הנשה יתן \u0003בה בנותן טעם\u0004 — \u0003הרי זו\u0004 הירך \u0003אסורה\u0004 באכילה. ו\u0003כיצד משערין אותה\u0004 אם יש בה כשיעור \u0003זה האוסרה באכילה?\u0004 מתייחסים לדבר \u0003כ\u0004אילו היה גיד הנשה שבירך \u0003בשר\u0004 הנתון \u0003ב\u0004תוך \u0003לפת.\u0004 ומעתה אם בשר (בשיעור זה של גיד הנשה) היה נותן טעם בלפת (בשיעור מידתה של הירך), אף הירך נאסרת על ידי גיד הנשה.","\u0003גיד הנשה שנתבשל עם הגידים\u0004 האחרים, המותרים באכילה, מה הדין? \u0003בזמן\u0004 (באופן) \u0003ש\u0004בו הוא \u0003מכירו\u0004 את גיד הנשה ומוציאו מבין שאר הגידים, ואין איפוא בתבשיל אלא פליטת טעמו — שאר הגידים אסורים רק \u0003ב\u0004מקרה שבו יש בגיד הנשה כשיעור שב\u0003נותן טעם, ואם לאו\u0004 \u0005[לא],\u0006 שאינו יכול לזהות את גיד הנשה ולהפרידו משאר הגידים — הגידים \u0003כולן אסורין,\u0004 שחוששים שכל גיד הריהו גיד הנשה. \u0003ו\u0004אילו \u0003הרוטב\u0004 שלהם נאסר רק \u0003ב\u0004זמן שיש בגיד הנשה כדי שיהיה \u0003נותן טעם\u0004 ברוטב.","\u0003וכן\u0004 הדין ב\u0003חתיכה של\u0004 בשר \u0003נבלה, וכן\u0004 הוא ב\u0003חתיכה של דג טמא שנתבשלה עם החתיכות\u0004 אחרות המותרות באכילה, ש\u0003בזמן שמכירן\u0004 את החתיכות האסורות — הריהו מוציא אותן משאר החתיכות, והן אוסרות את החתיכות המותרות רק \u0003ב\u0004שיעור שיש בו \u0003נותן טעם, ואם לאו\u0004 \u0005[לא],\u0006 שאינו מזהה את החתיכות האסורות — החתיכות \u0003כולן אסורות, והרוטב\u0004 שבו נתבשלו החתיכות אסור \u0003בנותן טעם.\u0004","שנינו במשנתנו שירך שהתבשלה עם גיד הנשה שבתוכה, הריהי נאסרת אם יש בגיד הנשה כשיעור נתינת טעם בירך. ועל כך \u0003אמר שמואל: לא שנו\u0004 במשנתנו הלכה זו \u0003אלא\u0004 באופן \u0003שנתבשל בה\u0004 הגיד בתוך הירך, שכן הרוטב שבתבשיל מפעפע ומעביר את טעם הגיד בכל המתבשל בקדירה. \u0003אבל\u0004 ירך ש\u0003נצלה בה\u0004 גיד הנשה, שאין טעם הגיד מתפשט בירך אלא נצמת במקומו — אין הירך נאסרת בכך, והריהו \u0003קולף\u0004 את בשר הירך שמעל גיד הנשה \u0003ואוכל, עד ש\u0004הוא \u0003מגיע ל\u0004מקומו של \u0003גיד\u0004 הנשה, ואז מוציא אותו.","ותוהים: \u0003איני\u0004 \u0005[כך הוא]\u0006 שאין הדבר הצלוי מפעפע?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: גדי שצלאו בחלבו\u0004 (עם החלב שבו), שלא נטל את החלב שעל הכליות לפני שנצלה הגדי — \u0003אסור לאכול\u0004 מאף חלק שבו, ו\u0003אפילו מראש\u0004 (קצה) \u0003אזנו\u0004 של הגדי, אף שאין שם חלב, והריהו מרוחק מהחלב. שנאסר כל הגדי באכילה, משום שאנו אומרים כי האיסור מפעפע בכולו!"],["ומשיבים: אין להקשות מדברי רב הונא הללו על דברי שמואל, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003חלב\u0004 מגיד הנשה, שהחלב \u0003מפעפע\u0004 ועובר בכל הבשר שנצלה אתו, ואילו הגיד אינו מפעפע.","ומקשים על דברי רב הונא: \u0003ו\u0004האם גדי שנצלה \u0003בחלב אסור\u0004 באכילה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה: עובדא הוה קמיה\u0004 \u0005[מעשה היה לפני]\u0006 \u0003ר' יוחנן בכנישתא\u0004 \u0005[בבית הכנסת]\u0006 בעיר \u0003מעון, בגדי שצלאו בחלבו, ואתו ושיילוה\u0004 \u0005[ובאו ושאלו]\u0006 את \u0003ר' יוחנן\u0004 מה דינו, \u0003ואמר\u0004 בתשובתו כי בעל הגדי \u0003קולף ואוכל עד שמגיע לחלבו,\u0004 ושלא כדברי רב הונא! ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 גדי, \u0003כחוש הוה\u0004 \u0005[היה],\u0006 ולא היה בו חלב מרובה, ובאופן זה אין הגדי כולו נאסר בצליה.","\u0003רב הונא בר יהודה אמר\u0004 הסבר אחר לדברי ר' יוחנן: לא היה זה גדי שלם שנצלה בחלבו, אלא \u0003כוליא\u0004 \u0005[כליה]\u0006 של גדי שנצלתה \u0003בחלבה הוה\u0004 \u0005[היתה]\u0006 זו, \u0003ושריא\u0004 \u0005[והתיר]\u0006 אותה ר' יוחנן באכילה, ומשום שיש עליה קרום החוצץ בינה לבין החלב שעליה, ומונע את כניסתו של החלב לתוכה אף בבישול. \u0003רבין בר רב אדא אמר\u0004 הסבר אחר להלכה זו של ר' יוחנן: \u0003כילכית\u0004 (דגיג, האסור באכילה) שנצלה \u0003באילפס\u0004 (קלחת קטנה) \u0003הוה\u0004 \u0005[היה]\u0006 זה, \u0003ואתו שיילוה\u0004 \u0005[ובאו ושאלו]\u0006 את \u0003ר' יוחנן\u0004 כיצד לנהוג, \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003ליטעמיה קפילא ארמאה\u0004 \u0005[שיטעם אותו נחתום גוי],\u0006 והוא יאמר לנו אם ניכר טעמו של הדג בתבשיל או לא.","מתוך שהובאו דברי ר' יוחנן בקביעת דין התבשיל בהסתמך על טעימת קפילא, מביאים מה ש\u0003אמר רבא\u0004 בענין זה: \u0003מריש הוה קא קשיא לי הא דתניא\u0004 \u0005[מתחילה היתה קשה לי\u0006 הלכה \u0005זו ששנויה\u0006 בברייתא\u0005]\u0006 ש\u0003קדרה שבשל בה בשר\u0004 — \u0003לא יבשל בה חלב, ואם\u0004 עבר ו\u0003בשל\u0004 בה חלב — הרי זה אוסר את החלב \u0003בנותן טעם.\u0004 וכיוצא בדבר: קדירה שבישל בה \u0003תרומה\u0004 (האסורה באכילה למי שאינו כהן) — \u0003לא יבשל בה חולין, ואם\u0004 עבר ו\u0003בשל\u0004 בה חולין — \u0003בנותן טעם.\u0004","ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 בכלי שהתבשלה בו \u0003תרומה\u0004 ולאחר מכן התבשל בו דבר חולין, ניתן לבדוק בטעימה אם התרומה נתנה טעם בחולין — שכן \u0003טעים לה\u0004 \u0005[טועם אותה]\u0006 \u0003כהן,\u0004 המותר באכילת תרומה. \u0003אלא\u0004 קדירה שהתבשל בה \u0003בשר\u0004 ולאחר מכן התבשלה \u0003בחלב, מאן טעים ליה\u0004 \u0005[מי טועם את הדבר]?!\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר ר' יוחנן\u0004 כי \u0003סמכינן אקפילא ארמאה\u0004 \u0005[סומכים אנו על נחתום גוי]\u0006 בענין כליה שנצלתה בחלבה, \u0003הכא נמי סמכינן אקפילא ארמאה\u0004 \u0005[כאן גם כן,\u0006 בענין בשר בחלב, \u0005סומכים אנו על נחתום גוי].\u0006","ובסיכום דיני ביטול דבר האסור באכילה שהתבשל עם הדבר המותר \u0003אמר רבא\u0004 : ישנם אופנים בהם \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]:\u0006 שהדבר תלוי \u0003ב\u0004נתינת \u0003טעמא\u0004 \u0005[טעם],\u0006 \u0003ו\u0004יש אופנים שבהם \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]\u0006 כי הדבר תלוי \u0003ב\u0004טעימת \u0003קפילא\u0004 \u0005[נחתום],\u0006"],["\u0003ו\u0004יש אופנים שבהם \u0003אמור רבנן\u0004 \u0005[אמרו חכמים]\u0006 כי הדבר תלוי \u0003ב\u0004שיעור פי \u0003ששים\u0004 שיש בדבר המותר כנגד הדבר האסור. \u0003הלכך\u0004 \u0005[על כן],\u0006 כשהתבשלו ביחד דברי מאכל שהם \u0003מין בשאינו מינו,\u0004 השונים בטעמם, והריהם \u0003דהיתרא\u0004 \u0005[של היתר],\u0006 ששניהם דברים \u0003המותרים באכילה לאדם מישראל (כגון תרומה שהתבשלה עם חולין, שהתרומה אף שאסורה באכילה לישראל הריהי מותרת לכהן) —\u0004 בירור הדבר נעשה \u0003בטעמא\u0004 \u0005[בטעימה],\u0006 שטועם כהן המותר באכילת שני הדברים שבתערובת. וכשהתערבו יחד דברי מאכל השונים בטעמם (מין ושאינו מינו), והריהם \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 — בירור הדבר נעשה \u0003ב\u0004טעימת \u0003קפילא\u0004 \u0005[נחתום]\u0006 גוי.","\u0003ו\u0004כשהתערבו שני מיני מאכל \u0003מין במינו,\u0004 שהם שוים בטעמם, \u0003דליכא למיקם אטעמא\u0004 \u0005[ש\u0006מעתה \u0005אין\u0006 מקום \u0005לעמוד,\u0006 להבחין, \u0005על הטעם\u0006 של דבר האיסור\u0005],\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה של \u0003מין בשאינו מינו דאיסורא\u0004 \u0005[של איסור]\u0006 ובמקרה \u0003דליכא קפילא\u0004 \u0005[שאין נחתום]\u0006 גוי — בירור הדבר נעשה \u0003ב\u0004בדיקה האם יש \u0003פי\u0004 \u0003ששים\u0004 בדבר ההיתר כנגד דבר האיסור.","למעלה הובאו דברי שמואל בדין הירך, שנתבשל או שניצלה בה גיד הנשה. ובענין זה מסופר: \u0003הנהו אטמהתא דאימליחו בי ריש גלותא בגידא נשיא\u0004 \u0005[אותן ירכות שנמלחו בבית ראש הגולה בגיד הנשה\u0006 בתוכן, שלא הוצא מהן לפני המליחה\u0005],\u0006 נחלקו חכמים בדינן, ש\u0003רבינא אסר\u0004 אותן, ואילו \u0003רב אחא בר רב אשי שרי\u0004 \u0005[התיר]\u0006 אותן. \u0003אתו שיילוה\u0004 \u0005[באו\u0006 אנשי בית ראש הגולה ו\u0005שאלו אותו]\u0006 את \u0003מר בר רב אשי\u0004 מהו דין הירכות הללו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אבא שרי\u0004 \u0005[אבי היה מתיר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר רב לרבינא: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה אוסר את הירכות הללו — משום שאתה סומך על מה ש\u0003אמר שמואל: מליח\u0004 (דבר הנתון במלח) — \u0003הרי הוא\u0004 נחשב \u0003כרותח,\u0004 דבר שהוא \u0003כבוש\u0004 (נתון בחומץ ותבלינים) — \u0003הרי הוא\u0004 נחשב \u0003כמבושל.\u0004 ולכך נאסרו הירכות הללו שהיו נתונות במלח עם גיד הנשה שבהן, שהריהן כמי שנתבשלו עמו.","\u0003ו\u0004אולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003שמואל\u0004 עצמו בהסבר דברי משנתנו בדין ירך שלא הוצא ממנה גיד הנשה כי \u0003לא שנו\u0004 שנאסרת, \u0003אלא\u0004 כ\u0003שנתבשל בה\u0004 גיד הנשה, \u0003אבל\u0004 כש\u0003נצלה בה\u0004 גיד הנשה — אין הירך נאסרת בכך, והריהו \u0003קולף ואוכל עד שמגיע לגיד,\u0004 ומעתה מדוע תיאסרנה הירכות הללו שנמלחו, ולא נתבשלו, עם גיד הנשה שבהן?","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כרותח\" דקאמר\u0004 \u0005[שהוא,\u0006 שמואל, \u0005אמר],\u0006 הכוונה שהריהו \u0003כרותח\u0004 שב\u0003מבושל\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 אין לומר כך, שכן \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 שמואל בהמשך דבריו כי \u0003כבוש הרי הוא כמבושל, מכלל\u0004 \u0005[מכאן נסיק]\u0006 שמה שאמר בתחילת דבריו כי \"מליח הרי הוא כרותח\", הכוונה ל\u0003רותח דצלי קאמר\u0004 \u0005[הוא אמר]!\u0006 ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 על שיטת רבינא.","למעלה הובא כי כאשר דבר מאכל אסור התבשל עם דבר היתר, והם מין בשאינו מינו, דבר האיסור בטל כשיש פי ששים בדבר ההיתר כנגדו. ובענין זה \u0003אמר ר' חנינא: כשהן משערין\u0004 אם יש פי ששים כנגד האיסור, \u0003משערין\u0004 בכל הנמצא בקדירה, \u0003ברוטב, ובקיפה\u0004 (חתיכות קטנות שנושרות מן הבשר), \u0003ובחתיכות\u0004 המאכל המתבשלות בקדירה, \u0003ובקדרה.\u0004 ובהסבר דברי ר' חנינא שמשערים בקדירה, מביאים שתי שיטות: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהכוונה היא שמשערים אף \u0003ב\u0004נפח ה\u0003קדרה עצמה, ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שהכוונה היא שמשערים \u0003במאי דבלעה\u0004 \u0005[במה שבולעת]\u0006 ה\u0003קדרה.\u0004","ומביאים עוד מדיני ביטול איסור בתערובת. \u0003אמר ר' אבהו אמר ר' יוחנן: כל איסורין שבתורה\u0004 (חוץ מגיד הנשה) שהתערבו עם דברים המותרים, ואי אפשר לדעת באמצעות טעימה אם נתן האיסור טעם בהיתר — \u0003משערינן\u0004 \u0005[משערים אנו]\u0006 \u0003כאילו הן\u0004 אותם דברי איסור היו \u0003בצל וקפלוט,\u0004 שטעמם ניכר ביותר. ומעתה אם בצל וקפלוט בגודל הדומה לדבר איסור זה היו נותנים טעם בדבר היתר זה — אף תערובת זו אסורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לאביי\u0004 בשאלה על הדברים הללו: \u0003ולשערינהו\u0004 \u0005[ושישער אותם]\u0006 כאילו היו דברי איסור אלה \u0003בפלפלין ותבלין,\u0004 שנותנים טעם ביותר, עד \u0003ש\u0004\u0003אפילו ב\u0004תערובת \u0003אלף\u0004 הם \u0003לא בטלין! אמר ליה\u0004 \u0005[לו]\u0006 אביי בתשובה: כך \u0003שיערו חכמים\u0004 ש\u0003אין נותן טעם באיסורין\u0004 (שאין בין הדברים האסורים דבר שנותן \u0003טעם)\u0004 \u0003יותר מבצל וקפלוט.\u0004","ועוד בדיני ביטול איסור בהיתר, \u0003אמר רב נחמן: גיד\u0004 הנשה שהתערב בהיתר והתבשלו יחד — משערים אנו \u0003בששים, ואין\u0004 ה\u0003גיד\u0004 עצמו נחשב \u0003מן המנין\u0004 של ששים של ההיתר, שצריכים אנו שיהיו ששים של היתר מלבדו. ואולם \u0003כחל\u0004 (עטין של פרה שיש בו חלב) שהתבשל עם בשר, והרי לפנינו תערובת בשר בחלב — שיעור הביטול הינו \u0003בששים, ו\u0004ה\u0003כחל\u0004 עצמו נחשב \u0003מן המנין\u0004 של בשר ההיתר, לצורך ביטול החלב. ואילו \u0003ביצה\u0004 של עוף טמא שהתבשלה עם דברי היתר — שיעור הביטול הריהו \u0003בששים, ואין\u0004 ה\u0003ביצה\u0004 נחשבת \u0003מן המנין.\u0004","\u0003אמר ר' יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: ו\u0004אף שלמדנו כי כחל שנתבשל עם בשר אחר, אם יש ששים בכלל התבשיל כנגד הכחל, לא נאסר התבשיל בכך — ה\u0003כחל עצמו\u0004 הריהו \u0003אסור\u0004 בכל מקרה, שכן הבשר שבתבשיל נתן טעם בחלב שבתוך הכחל, ונאסר בכך הכחל לאכילה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003נפל\u0004 הכחל \u0003לקדרה אחרת\u0004 והתבשל שם — הריהו \u0003אוסר\u0004 את הנמצא באותה קדירה, אם אין בה כשיעור ששים כנגד הכחל.","ומביאים עוד בדינו של כחל שהתבשל עם בשר, \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים \u0005בבית]\u0006 של \u0003רב כהנא, איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה בדינו של כחל שהתבשל בקדירה עם בשר: \u0003כי משערינן\u0004 \u0005[כאשר אנו משערים]\u0006 ששים בהיתר, האם \u0003בדידיה משערינן\u0004 \u0005[בו עצמו אנו משערים],\u0006 שצריך שיהיה פי ששים כנגד כולו. \u0003או\u0004 שמא \u0003במאי דנפק מיניה משערינן\u0004 \u0005[במה שיצא ממנו אנו משערים],\u0006 ובאופן שהכחל עצמו הוצא מן הקדירה?","ודנים בשאלה זו: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא \u0003דבדידיה משערינן\u0004 \u0005[שבו עצמו אנו משערים],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003במה דנפק מיניה\u0004 \u0005[שיצא ממנו]\u0006 אנו משערים — \u0003מנא ידעינן\u0004 \u0005[מנין יודעים אנו]\u0006 כמה יצא?! ודוחים: \u0003אלא מעתה,\u0004 שאתה אומר כי משערים בכחל עצמו, אם \u0003נפל\u0004 הכחל \u0003לקדרה אחרת\u0004 — \u0003לא יאסר\u0004 אותה, שהרי כבר יצא כל איסורו, ולא כפי שלמדנו!","ומשיבים: \u0003כיון\u0004 ש\u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: וכחל עצמו אסור,\u0004 משמע ש\u0003שויוה רבנן\u0004 \u0005[עשאוהו חכמים]\u0006 כאילו היה \u0003חתיכה\u0004 של \u0003נבלה,\u0004 שאסורה היא כשלעצמה, ולא משום מה שיש בה. ולכך הריהי אוסרת את הנמצא בקדירה אחרת שבה התבשלה.","למדנו שאמר רב נחמן כי \u0003ביצה\u0004 של עוף טמא שהתבשלה עם היתר, בטלה \u0003בששים, ואין\u0004 ה\u0003ביצה\u0004 עצמה נחשבת \u0003מן המנין.\u0004 ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אידי בר אבין לאביי: למימרא\u0004 \u0005[האם יש לומר,\u0006 להסיק\u0005]\u0006 מכאן שביצת עוף טמא המתבשלת עם ביצים כשרות, \u0003דיהבה טעמא\u0004 \u0005[שנותנת\u0006 היא בהן \u0005טעם]?\u0006 \u0003והא אמרי אינשי כי מיא דביעי בעלמא\u0004 \u0005[והרי אומרים אנשים\u0006 כביטוי הרווח לדבר \u0005חסר טעם שהריהו\u0006 \u0005\"כמו מי ביצים סתם\"],\u0006 הרי שמי ביצים אין בהם טעם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006"]]};
